        ------------------------------------------------------------------------
        function AICConfig.IsValidPlace(id: number)
            if PLACE_CONFIG[id] then
                return PLACE_CONFIG[id]
            end
            return false
        end
        
        function AICConfig.NormalizePlaceConfig(Config)
            Config = Config or {}
        
            local Waypoints = AICConfig.CloneVectorList(Config.WAYPOINTS)
            local FarmZones = AICConfig.CloneZoneList(Config.FARM_ZONES)
            local Deadzones = AICConfig.CloneZoneList(Config.DEADZONES)
        
            --// Backwards compatibility with the existing place_config format.
            if #FarmZones == 0 and Config.FARM_CENTER then
                table.insert(FarmZones, {
                    Center = AICConfig.DecodeVector3(Config.FARM_CENTER),
                    Radius = math.max(0, tonumber(Config.FARM_RADIUS) or 0),
                })
            end
        
            if #Deadzones == 0 and Config.FARM_DEADZONE_CENTER then
                local Radius = tonumber(Config.FARM_DEADZONE_RADIUS) or 0
        
                if Radius > 0 then
                    table.insert(Deadzones, {
                        Center = AICConfig.DecodeVector3(Config.FARM_DEADZONE_CENTER),
                        Radius = Radius,
                    })
                end
            end
        
            local FirstFarm = FarmZones[1]
            local FirstDeadzone = Deadzones[1]
        
            Config.WAYPOINTS = Waypoints
            --// Seconds to stand at each waypoint before moving on, one entry per
            --// waypoint. Padded with 0 and trimmed so it always lines up.
            Config.WAYPOINT_WAITS = AICConfig.NormalizeWaitList(Config.WAYPOINT_WAITS, #Waypoints)
            --// Whether to jump on reaching each waypoint, one entry per
            --// waypoint, padded with false.
            Config.WAYPOINT_JUMPS = AICConfig.NormalizeJumpList(Config.WAYPOINT_JUMPS, #Waypoints)
            Config.FARM_ZONES = FarmZones
            --// Farm zone paired with each waypoint for the waypoint loop, one
            --// entry per waypoint. 0 means the waypoint has no zone.
            Config.WAYPOINT_ZONES = AICConfig.NormalizeZonePairs(Config.WAYPOINT_ZONES, #Waypoints, #FarmZones)
            Config.DEADZONES = Deadzones
            --// Auto Mining only mines ores inside one of these.
            Config.MINE_ZONES = AICConfig.CloneZoneList(Config.MINE_ZONES)
            --// Boss Route stops (BossNavigator): a spot to stand on per boss,
            --// with its own teleport, wait and reset timers. Kept apart from
            --// WAYPOINTS so neither route moves the other.
            Config.BOSS_ROUTE = AICConfig.NormalizeBossStops(Config.BOSS_ROUTE)
            --// Where the chosen smithing table stands, or nil for "nearest".
            --// A position, not the table's Id, which may differ per server.
            Config.SMITH_TABLE = Config.SMITH_TABLE ~= nil
                and AICConfig.DecodeVector3(Config.SMITH_TABLE)
                or nil

            --// Legacy aliases remain available to old code while the actual logic
            --// supports multiple zones.
            --// Do not manufacture Vector3.zero when a zone does not exist.
            --// Missing zones stay nil so farm logic never treats (0, 0, 0) as a real zone.
            Config.FARM_CENTER = FirstFarm and FirstFarm.Center or nil
            Config.FARM_RADIUS = FirstFarm and FirstFarm.Radius or nil
            Config.FARM_DEADZONE_CENTER = FirstDeadzone and FirstDeadzone.Center or nil
            Config.FARM_DEADZONE_RADIUS = FirstDeadzone and FirstDeadzone.Radius or nil
        
            Config.REACH_DISTANCE = tonumber(Config.REACH_DISTANCE) or 5
            Config.AUTOBLOCK = Config.AUTOBLOCK == true
        
            return Config
        end
        
        --// Longest a waypoint may hold the character, so a typo cannot park
        --// the bot for hours.
        AICConfig.MAX_WAYPOINT_WAIT = 600

        function AICConfig.NormalizeWaitList(List, Count)
            local Result = {}

            for Index = 1, Count do
                local Value = type(List) == "table" and tonumber(List[Index]) or 0
                Result[Index] = math.clamp(Value or 0, 0, AICConfig.MAX_WAYPOINT_WAIT)
            end

            return Result
        end

        function AICConfig.NormalizeJumpList(List, Count)
            local Result = {}

            for Index = 1, Count do
                Result[Index] = type(List) == "table" and List[Index] == true
            end

            return Result
        end

        --// A Jump waypoint is reached only this close (studs, flat), so the
        --// jump goes off at the edge it was placed on rather than Reach
        --// Distance short of it.
        AICConfig.JUMP_WAYPOINT_REACH = 1.5

        --// Whether the character should jump now that it is at waypoint
        --// Index: it is a Jump waypoint and close enough. Returns IsJump,
        --// Reached. A non-jump waypoint returns false, nil (use Reach).
        function AICConfig.CheckJumpWaypoint(Config, Index, HorizontalDistance)
            if not (Config.WAYPOINT_JUMPS and Config.WAYPOINT_JUMPS[Index]) then
                return false, nil
            end

            return true, HorizontalDistance <= AICConfig.JUMP_WAYPOINT_REACH
        end

        function AICConfig.NormalizeZonePairs(List, Count, ZoneCount)
            local Result = {}

            for Index = 1, Count do
                local Value = math.floor(type(List) == "table" and tonumber(List[Index]) or 0)
                Result[Index] = (Value >= 1 and Value <= ZoneCount) and Value or 0
            end

            return Result
        end

        --// Target names a farm zone fights; empty means the Enemy Priority list.
        function AICConfig.CloneTargetList(List)
            local Result = {}

            for _, Name in ipairs(type(List) == "table" and List or {}) do
                if type(Name) == "string" and Name ~= "" and not table.find(Result, Name) then
                    table.insert(Result, Name)
                end
            end

            return Result
        end

        --// Boss Route limits. The defaults are what a new stop starts with:
        --// fight until the boss is down, then reset and move on. Wait After
        --// Reset gives the new character time to load, and the engage radius
        --// reaches across a boss room from the standing spot. A stop's Path is
        --// the travel points walked before it; there is no fight timer, so a
        --// stop only ever resets after the kill.
        AICConfig.DEFAULT_BOSS_RADIUS = 120
        --// Held at the corpse before a reset that would actually lose EXP.
        --// A reset that would not is not held at all, whatever this says.
        AICConfig.DEFAULT_BOSS_RESET_WAIT = 10
        AICConfig.MAX_BOSS_PATH = 64
        AICConfig.MAX_BOSS_RESET = 600
        AICConfig.MAX_BOSS_RADIUS = 500
        AICConfig.MAX_BOSS_WAYPOINT = 999
        --// How far from the boss the skill dodge settles. Small enough to be a
        --// step out of a skill rather than a run across the room; a stop can
        --// set its own in "Dodge Distance".
        AICConfig.DEFAULT_BOSS_DODGE_DISTANCE = 16
        AICConfig.MIN_BOSS_DODGE_DISTANCE = 6
        AICConfig.MAX_BOSS_DODGE_DISTANCE = 80

        --// Saved travel points for one boss stop, in the order walked.
        function AICConfig.NormalizeBossPath(List)
            local Result = {}

            for _, Point in ipairs(type(List) == "table" and List or {}) do
                if #Result >= AICConfig.MAX_BOSS_PATH then
                    break
                end

                if typeof(Point) == "Vector3" then
                    table.insert(Result, AICConfig.RoundVector3(Point))
                elseif type(Point) == "table" then
                    table.insert(Result, AICConfig.DecodeVector3(Point))
                end
            end

            return Result
        end

        --// One stop of the Boss Route (BossNavigator). Position is the spot
        --// the character stands on; a stop without one is dropped, so a
        --// half-written save cannot leave an unwalkable row.
        --//   Label       shown in the list
        --//   Targets     boss entity names; empty fights anything at the spot
        --//   Path        points walked in order on the way to Position
        --//   Waypoint    game waypoint number teleported to first, 0 walks
        --//   ResetAfterKill  reset once the boss is down, then the next stop
        --//   ResetWait   seconds held at the corpse before that reset
        --//   Wait        seconds stood at the spot before the fight, 0 none
        --//   Radius      how far from Position a boss is picked up
        --//   Dodge       sprint out of the boss's skill while it is casting
        --//   DodgeDistance  how far from the boss that dodge settles
        --//   Prompt      travel by teleporting to PromptPosition first
        --//   PromptPosition  where that interaction prompt stands
        --//   PromptName  its name, for the editor and the status line
        function AICConfig.NormalizeBossStops(List)
            local Result = {}

            for _, Stop in ipairs(type(List) == "table" and List or {}) do
                local Position = type(Stop) == "table" and Stop.Position or nil

                if typeof(Position) == "Vector3" then
                    Position = AICConfig.RoundVector3(Position)
                elseif type(Position) == "table" then
                    Position = AICConfig.DecodeVector3(Position)
                else
                    Position = nil
                end

                if Position then
                    local Label = type(Stop.Label) == "string" and Stop.Label:gsub("^%s*(.-)%s*$", "%1") or ""
                    --// Where the interaction prompt of this stop stands, saved
                    --// from the button in Edit Boss Stop. Rounded like any
                    --// other point, so a save cannot drift it.
                    local PromptPosition = Stop.PromptPosition

                    if typeof(PromptPosition) == "Vector3" then
                        PromptPosition = AICConfig.RoundVector3(PromptPosition)
                    elseif type(PromptPosition) == "table" then
                        PromptPosition = AICConfig.DecodeVector3(PromptPosition)
                    else
                        PromptPosition = nil
                    end

                    local PromptName = type(Stop.PromptName) == "string"
                        and string.sub(Stop.PromptName:gsub("^%s*(.-)%s*$", "%1"), 1, 64)
                        or ""
                    --// Stops saved before Reset After Kill existed: they were
                    --// written with the old 10 s timeout and never reset after
                    --// a kill. Treat them as the new default, fight until the
                    --// boss is down and then reset.
                    local Legacy = Stop.ResetAfterKill == nil

                    table.insert(Result, {
                        Label = Label ~= "" and Label or ("Boss " .. tostring(#Result + 1)),
                        Position = Position,
                        Path = AICConfig.NormalizeBossPath(Stop.Path),
                        Targets = AICConfig.CloneTargetList(Stop.Targets),
                        Waypoint = math.clamp(
                            math.floor(tonumber(Stop.Waypoint) or 0), 0, AICConfig.MAX_BOSS_WAYPOINT
                        ),
                        ResetAfterKill = Legacy or Stop.ResetAfterKill == true,
                        --// Saves made before v3.36 kept the fight timeout in
                        --// ResetAfter; that number is the pause at the corpse
                        --// now, so a wait the user had set keeps working.
                        ResetWait = math.clamp(
                            tonumber(Stop.ResetWait) or tonumber(Stop.ResetAfter)
                                or AICConfig.DEFAULT_BOSS_RESET_WAIT,
                            0,
                            AICConfig.MAX_BOSS_RESET
                        ),
                        --// Default on: a boss skill is worth stepping out of
                        --// until the stop says otherwise.
                        Dodge = Stop.Dodge ~= false,
                        DodgeDistance = math.clamp(
                            tonumber(Stop.DodgeDistance) or AICConfig.DEFAULT_BOSS_DODGE_DISTANCE,
                            AICConfig.MIN_BOSS_DODGE_DISTANCE,
                            AICConfig.MAX_BOSS_DODGE_DISTANCE
                        ),
                        --// On with nothing saved is allowed: the nearest prompt
                        --// to the stop is found at run time.
                        Prompt = Stop.Prompt == true,
                        PromptPosition = PromptPosition,
                        PromptName = PromptName,
                        Radius = math.clamp(
                            tonumber(Stop.Radius) or AICConfig.DEFAULT_BOSS_RADIUS,
                            1,
                            AICConfig.MAX_BOSS_RADIUS
                        ),
                        --// 0 for a new stop and for saves made before the box
                        --// came back: the fight starts on arrival, as it has
                        --// since v3.35.
                        Wait = math.clamp(
                            tonumber(Stop.Wait) or 0,
                            0,
                            AICConfig.MAX_WAYPOINT_WAIT
                        ),
                    })
                end
            end

            return Result
        end

        --// Rewrites waypoint->zone pairs after farm zones are removed or
        --// reordered. Map(oldIndex) returns the new index, or 0 if gone.
        function AICConfig.RemapWaypointZones(Config, Map)
            local Pairs = Config.WAYPOINT_ZONES or {}

            for Index, ZoneIndex in ipairs(Pairs) do
                if ZoneIndex > 0 then
                    Pairs[Index] = Map(ZoneIndex) or 0
                end
            end

            Config.WAYPOINT_ZONES = Pairs
        end

        --// Every stored position keeps two decimal places. Raw floats like
        --// 1773.4182739257812 bloat the save and the export text for no
        --// precision anyone can walk to.
        AICConfig.VECTOR_DECIMALS = 2

        function AICConfig.RoundNumber(Value)
            local Scale = 10 ^ AICConfig.VECTOR_DECIMALS
            return math.round((tonumber(Value) or 0) * Scale) / Scale
        end

        function AICConfig.RoundVector3(Value)
            return Vector3.new(
                AICConfig.RoundNumber(Value.X),
                AICConfig.RoundNumber(Value.Y),
                AICConfig.RoundNumber(Value.Z)
            )
        end

        function AICConfig.EncodeVector3(Value)
            if typeof(Value) ~= "Vector3" then
                return { X = 0, Y = 0, Z = 0 }
            end

            return {
                X = AICConfig.RoundNumber(Value.X),
                Y = AICConfig.RoundNumber(Value.Y),
                Z = AICConfig.RoundNumber(Value.Z),
            }
        end

        function AICConfig.DecodeVector3(Value)
            if typeof(Value) == "Vector3" then
                return AICConfig.RoundVector3(Value)
            end

            if type(Value) ~= "table" then
                return Vector3.zero
            end

            return AICConfig.RoundVector3(Vector3.new(
                tonumber(Value.X) or 0,
                tonumber(Value.Y) or 0,
                tonumber(Value.Z) or 0
            ))
        end
        
        function AICConfig.CloneVectorList(List)
            local Result = {}
        
            for _, Value in ipairs(List or {}) do
                table.insert(Result, AICConfig.DecodeVector3(Value))
            end
        
            return Result
        end
        
        function AICConfig.CloneZoneList(List)
            local Result = {}
        
            for _, Zone in ipairs(List or {}) do
                if type(Zone) == "table" and Zone.Center then
                    table.insert(Result, {
                        Center = AICConfig.DecodeVector3(Zone.Center),
                        Radius = math.max(0, tonumber(Zone.Radius) or 0),
                        Targets = AICConfig.CloneTargetList(Zone.Targets),
                    })
                end
            end
        
            return Result
        end
        
        function AICConfig.SerializeVectorList(List)
            local Result = {}
        
            for _, Value in ipairs(List or {}) do
                table.insert(Result, AICConfig.EncodeVector3(Value))
            end
        
            return Result
        end
        
        function AICConfig.SerializeZoneList(List)
            local Result = {}
        
            for _, Zone in ipairs(List or {}) do
                if Zone and Zone.Center then
                    table.insert(Result, {
                        Center = AICConfig.EncodeVector3(Zone.Center),
                        Radius = tonumber(Zone.Radius) or 0,
                        Targets = AICConfig.CloneTargetList(Zone.Targets),
                    })
                end
            end
        
            return Result
        end
        
        
        
        
        ------------------------------------------------------------------------
        ------------------------------------------------------------------------
        --// AICCombatUtils
        --//
        --// geometry, world queries, blade maths, movement primitives
        --//
        --// Definitions only; nothing here runs at load time.
        ------------------------------------------------------------------------

        --// Real stuck detection: barely moving while actively trying to move.
        --// Two consecutive samples prevent a single frame against a corner
        --// from counting as stuck.
        local Runtime = {}

        function Runtime:GetCharacter()
            -- Refresh from Player if character was destroyed or never set
            if not Character or not Character.Parent then
                Character = Player.Character
                Humanoid = Character and Character:FindFirstChildOfClass("Humanoid") or nil
                RootPart = Character and Character:FindFirstChild("HumanoidRootPart") or nil
            elseif not Humanoid or not Humanoid.Parent then
                Humanoid = Character:FindFirstChildOfClass("Humanoid")
            end
            if Character and Character.Parent and (not RootPart or not RootPart.Parent) then
                RootPart = Character:FindFirstChild("HumanoidRootPart")
            end
            return Character, Humanoid, RootPart
        end

        function Runtime:SetCharacter(NewCharacter, NewHumanoid, NewRootPart)
            Character = NewCharacter
            Humanoid = NewHumanoid
            RootPart = NewRootPart
        end

        function Runtime:SetInputBindableFunction(Value)
            InputBindableFunction = Value
        end

        function Runtime:GetInputBindableFunction()
            return InputBindableFunction
        end

        --// The game's Interact input is left alone for a moment after a script
        --// teleport. A prompt teleport lands the character on the prompt
        --// itself, so pressing on the way out fires the same door again -- and
        --// a door that teleports the character keeps re-firing for as long as
        --// the presses go out. Every presser (Auto Farm, Boss Route) asks
        --// this, so a teleport from any tab mutes them all.
        local InteractMutedUntil = 0

        function Runtime:MuteInteract(Seconds)
            local UntilTime = os.clock() + math.max(tonumber(Seconds) or 0, 0)

            if UntilTime > InteractMutedUntil then
                InteractMutedUntil = UntilTime
            end
        end

        function Runtime:IsInteractMuted()
            return os.clock() < InteractMutedUntil
        end

        function Runtime:GetFaceOrientation()
            return FaceOrientation
        end

        function Runtime:SetFaceOrientation(Value)
            FaceOrientation = Value
        end

        function Runtime:GetPlaceConfig()
            return PlaceConfig
        end

        function Runtime:SetPlaceConfig(Value)
            PlaceConfig = Value
        end

        function Runtime:GetBasePlaceConfig()
            return BasePlaceConfig
        end

        function Runtime:SetBasePlaceConfig(Value)
            BasePlaceConfig = Value
        end

        Context.Services = {
            Players = Players,
            Replicated = Replicated,
            StarterGui = StarterGui,
            RunService = RunService,
            UserInputService = UserInputService,
            MarketplaceService = MarketplaceService,
            PathfindingService = PathfindingService,
            HttpService = HttpService,
        }
        Context.Player = Player
        Context.PlayerGui = PlayerGui
        Context.CONFIG = CONFIG
        Context.AICConfig = AICConfig
        Context.AICProfile = AICProfile
        Context.AICCombatUtils = AICCombatUtils
        Context.AICCombat = AICCombat
        Context.AICFeature = AICFeature
        Context.AICUI = AICUI
        Context.AICDebug = AICDebug
        Context.Feature = Feature
        Context.MiningFeature = MiningFeature
        Context.UI = UI
        Context.UIRef = UIRef
        Context.NotifyAction = NotifyAction
        Context.PatrolState = PatrolState
        -- Seed character handles so GetCharacter works before first updateCharacter()
        Character = Player.Character
        if Character then
            Humanoid = Character:FindFirstChildOfClass("Humanoid")
            RootPart = Character:FindFirstChild("HumanoidRootPart")
        end

        --// Resolve the place config here, before any other module starts.
        --// ProfileManager, Farmzone, Waypoints and AutoBlock read it while
        --// they build, so it cannot wait for Bootstrap.
        PlaceConfig = AICConfig.NormalizePlaceConfig(AICConfig.IsValidPlace(game.PlaceId) or {})
        BasePlaceConfig = AICConfig.NormalizePlaceConfig(AICConfig.IsValidPlace(game.PlaceId) or {})
        CONFIG.TARGET_ENTITY_PRIORITY = PlaceConfig.DEFAULT_TARGET_PRIORITY or {}
        Context.PLACE_CONFIG = PlaceConfig

        Context.Runtime = Runtime
        Context.DEBUG_COLORS = DEBUG_COLORS

        --// Init stores whatever Start returns as Context.Runtime, so this has
        --// to be the Runtime object. Returning Context replaced Runtime with
        --// Context and every Runtime:GetX() call failed.
        return Runtime
    end,
}
]======],
	["Core/SaveConfig.lua"] = [======[
-- SaveConfig is the single list of everything a profile saves.
--
-- Adding a saved feature toggle is one line in Features; adding a saved
-- setting is one line in Settings. Runtime builds its feature state and
-- CONFIG defaults from here, ProfileManager saves, loads, exports and
-- resets from here, and Components refreshes every toggle from here.
return {
    Name = "SaveConfig",
    Dependencies = {},

    Start = function()
        local SaveConfig = {}

        --// Feature toggles, saved in the profile's FEATURES table.
        --//   Name    : key in Context.Feature and in the save file
        --//   Default : value before any profile is loaded
        --//   Key     : short key in exported profile text. Must never change
        --//             or be reused, or old exports load into the wrong toggle.
        --//             Toggles without one are saved but not exported.
        --//   Global  : stored in ProfileManager's global file, shared by every
        --//             profile and PlaceId; profiles neither save, load nor
        --//             export it. Its Key stays reserved.
        SaveConfig.Features = {
            { Name = "AutoFarm",          Default = true,  Key = "a" },
            { Name = "AutoBlock",         Default = true,  Key = "b" },
            { Name = "SafeCombat",        Default = true,  Key = "c" },
            { Name = "AutoFind",          Default = false, Key = "d" },
            { Name = "IgnoreFarmZone",    Default = false, Key = "e" },
            { Name = "AutoPatrol",        Default = false, Key = "f" },
            { Name = "ReturnToFarmZone",  Default = true,  Key = "g" },
            { Name = "AutoSkill",         Default = true,  Key = "h" },
            --// Shown as "Refill Booster": resets the character when a boost
            --// runs out so the game refills it. Owned by AutoRefill.
            { Name = "ResetOnBoostOut",   Default = true,  Key = "i" },
            { Name = "ResetStats",        Default = true,  Key = "j" },
            { Name = "DebugVisualizer",   Default = true,  Key = "k" },
            { Name = "PartySystem",       Default = false, Key = "l" },
            { Name = "WaypointLoop",      Default = false, Key = "m" },
            --// Boss Route (BossNavigator): walks its own list of boss stops,
            --// fights at each and resets on its own timers. Its stops live on
            --// the place config (BOSS_ROUTE), not in WAYPOINTS.
            { Name = "BossRoute",         Default = false, Key = "z" },
            { Name = "SafeBoosterReset",  Default = false, Key = "n" },
            { Name = "AutoBlockConfirm",  Default = false, Key = "o" },
            { Name = "AutoMining",        Default = false, Key = "p" },
            { Name = "AutoSmithing",      Default = false, Key = "q" },
            --// Server tab (ServerUI): leave when a danger group member is here,
            --// and notify about players off the whitelist.
            { Name = "DangerGroupHop",    Default = false, Key = "r", Global = true },
            { Name = "JoinAlerts",        Default = false, Key = "s" },
            --// Leaves for another server when one player keeps joining
            --// yours, and stops Auto Farm only when it cannot leave
            --// (FollowerGuard). Its sightings and hold live in the shared
            --// FollowerLog.json, so it watches across profiles and places.
            { Name = "FollowerGuard",     Default = true,  Key = "y", Global = true },
            --// Pull a pack of mobs together, then use the skill (MobGather).
            { Name = "MobGather",         Default = false, Key = "t" },
            --// Click through the title screen (AutoStartGame). Shared by every
            --// profile: it runs before the farm's profile matters.
            { Name = "AutoStartGame",     Default = false, Key = "u", Global = true },
            --// Block Whitelist players never make Auto Block hop (even when
            --// blocked) or Leave On Danger Group leave. Owned by AutoBlock;
            --// shared by every profile, like the Block Whitelist.
            { Name = "WhitelistSkipsSafety", Default = true, Key = "v", Global = true },
            --// Auto Block's other half: instead of blocking an intruder, leave
            --// the server once the Block Delay has run out. Shared by every
            --// profile, like the whitelist that decides who counts.
            { Name = "AutoBlockLeaveOnly", Default = false, Global = true },
            --// A leave the script starts on its own (Leave Instead Of Block,
            --// the Follower Guard kick, the Danger Group hop) pauses a random
            --// 2-4 s first, so the client never drops the server the same
            --// instant a stranger appeared. Owned by AutoBlock; shared by
            --// every profile, like the toggles around it.
            { Name = "RandomLeaveDelay", Default = true, Global = true },

            --// Turns off shadows, effects and particles for frames (FpsBoost).
            --// Shared by every profile: it is about the machine, not the farm.
            { Name = "FpsBoost",          Default = false, Key = "w", Global = true },
            --// Jump over something in the way while chasing a target (the
            --// DoCombatJump* helpers in CombatUtils). Off, the character keeps
            --// its feet on the ground for the whole fight; the waypoint route,
            --// patrol, mining and smithing jumps are their own.
            { Name = "JumpWhileFighting", Default = false, Key = "x" },
            { Name = "DebugWaypoints",    Default = true },
            { Name = "DebugFarmZones",    Default = true },
            { Name = "DebugDeadzones",    Default = true },
            { Name = "DebugRadiusLabels", Default = true },
            { Name = "DebugMineZones",    Default = true },
            { Name = "DebugOres",         Default = true },
            { Name = "DebugSmithing",     Default = true },
        }

        --// The game holds at most this many of one item, so no mining or
        --// smithing target can be higher.
        SaveConfig.ITEM_MAX_STACK = 500

        --// Normalizers turn whatever a save file holds into a valid value.
        --// They receive nil for a missing entry and must return the default.

        --// Numeric IDs (UserIds, group IDs) as text, duplicates dropped.
        local function NormalizeIdList(Value)
            local Result = {}

            for _, Entry in ipairs(type(Value) == "table" and Value or {}) do
                local Text = tostring(Entry or ""):gsub("%s+", "")

                if Text:match("^%d+$") and not table.find(Result, Text) then
                    table.insert(Result, Text)
                end
            end

            return Result
        end

        --// Names as the game spells them: text entries only, trimmed, blanks
        --// and duplicates dropped, order kept.
        local function NormalizeNameList(Value)
            local Result = {}

            for _, Entry in ipairs(type(Value) == "table" and Value or {}) do
                local Text = type(Entry) == "string" and Entry:gsub("^%s*(.-)%s*$", "%1") or ""

                if Text ~= "" and not table.find(Result, Text) then
                    table.insert(Result, Text)
                end
            end

            return Result
        end

        --// { Name, UserId } of the party Leader, or {} when none is set.
        local function NormalizePartyLeader(Value)
            if type(Value) ~= "table" or type(Value.Name) ~= "string" or Value.Name == "" then
                return {}
            end

            return {
                Name = Value.Name,
                UserId = tonumber(Value.UserId),
            }
        end

        --// A normalizer for { { Name, <CountKey> }, ... } in priority order,
        --// each count a whole number from 0 to ITEM_MAX_STACK (Fallback when
        --// missing). Duplicate names keep the first entry.
        local function NormalizeCountList(CountKey, Fallback)
            return function(Value)
                local Result = {}
                local Seen = {}

                for _, Entry in ipairs(type(Value) == "table" and Value or {}) do
                    local Name = type(Entry) == "table" and Entry.Name

                    if type(Name) == "string" and Name ~= "" and not Seen[Name] then
                        Seen[Name] = true
                        table.insert(Result, {
                            Name = Name,
                            [CountKey] = math.clamp(
                                math.floor(tonumber(Entry[CountKey]) or Fallback),
                                0,
                                SaveConfig.ITEM_MAX_STACK
                            ),
                        })
                    end
                end

                return Result
            end
        end

        local function NormalizePinnedState(Value)
            if type(Value) ~= "table" then
                return {}
            end

            return {
                Items = type(Value.Items) == "table" and Value.Items or {},
                Floating = Value.Floating == true,
                --// Closed with its × and shown again from the Status tab.
                Visible = Value.Visible ~= false,
                X = tonumber(Value.X),
                Y = tonumber(Value.Y),
            }
        end

        --// Settings, saved in the profile's SETTINGS table.
        --//   Key       : key in CONFIG (or the place config) and in the save
        --//   Default   : value before any profile is loaded
        --//   Min / Max : clamp for numbers
        --//   Options   : allowed values for a choice; anything else -> Default
        --//   Normalize : custom cleanup for structured values
        --//   Scope     : "Place" lives on the place config instead of CONFIG,
        --//               and defaults to that place's preset
        --//   Global    : stored outside profiles; a profile copy only seeds it
        SaveConfig.Settings = {
            { Key = "REACH_DISTANCE", Scope = "Place", Default = 5 },
            { Key = "AUTOBLOCK", Scope = "Place", Default = false },
            --// Boss Route loops back to its first stop after the last one;
            --// off, it plays the route once and switches itself off.
            { Key = "BOSS_ROUTE_LOOP", Default = true },
            --// Boss Route takes its Reset (s) before every reset, including one
            --// the EXP check would have fired at once; off, a reset that costs
            --// no EXP still happens immediately.
            { Key = "BOSS_RESET_ALWAYS_WAIT", Default = false },

            --// Retreat below this share of health (0 = never), and drink at or below the
            --// heal share.
            { Key = "RETREAT_HEALTH_PERCENT", Default = 40, Min = 0, Max = 80 },
            { Key = "AUTO_HEAL_HEALTH_PERCENT", Default = 65, Min = 30, Max = 80 },
            { Key = "SAFE_ENEMY_RANGE", Default = 4, Min = 0, Max = 30 },
            --// With Safe Combat off: how far from the target it fights
            --// (studs). 4 is just clear of its body, 12 the attack reach.
            { Key = "CLOSE_COMBAT_RANGE", Default = 6, Min = 4, Max = 12 },

            --// Tie break between mobs of equal priority.
            --// "Disabled" keeps the original nearest-first behaviour.
            { Key = "TARGET_HP_MODE", Default = "Disabled", Options = { "Disabled", "Highest HP", "Lowest HP" } },

            --// Below this share of its health a target is finished off instead
            --// of retreated from. An enemy skill still overrides it.
            { Key = "EXECUTE_CHARGE_HP_PERCENT", Default = 0, Min = 0, Max = 90 },

            --// Gather Mobs: a pack needs at least GATHER_MIN_MOBS within
            --// GATHER_RADIUS of each other; at most GATHER_MAX_MOBS are pulled.
            { Key = "GATHER_MIN_MOBS", Default = 3, Min = 2, Max = 8 },
            { Key = "GATHER_MAX_MOBS", Default = 5, Min = 2, Max = 10 },
            { Key = "GATHER_RADIUS", Default = 40, Min = 15, Max = 80 },

            --// Route hole jump (waypoint route and Waypoint Loop): the ground
            --// is sampled every ROUTE_HOLE_SAMPLE_STEP studs along the
            --// character's facing, up to ROUTE_HOLE_PROBE_DISTANCE ahead;
            --// missing ground, water or a drop of ROUTE_HOLE_MIN_DEPTH or
            --// more is a hole and the character jumps. Non-whole bounds
            --// give the sliders two decimals.
            { Key = "ROUTE_HOLE_PROBE_DISTANCE", Default = 2, Min = 0.5, Max = 6 },
            { Key = "ROUTE_HOLE_SAMPLE_STEP", Default = 0.5, Min = 0.25, Max = 2 },
            { Key = "ROUTE_HOLE_MIN_DEPTH", Default = 1, Min = 0.5, Max = 10 },

            --// Seconds Auto Block waits after first seeing a non-whitelisted
            --// player before blocking them and leaving. 0 acts at once.
            { Key = "AUTO_BLOCK_DELAY", Default = 0, Min = 0, Max = 120 },

            --// Party System Leader, followed between servers with the game's
            --// "tp friend <Name>" chat command. Empty table = no Leader.
            { Key = "PARTY_LEADER", Default = {}, Normalize = NormalizePartyLeader },

            --// Boosters Refill Booster resets the character for, by their
            --// PlayerStats value name - that is what the toggles in the Booster
            --// Reset section write. The game owns those names and the section
            --// scans for them, so anything it finds gets a toggle; this default
            --// is the two the script knows, and keeps an existing profile
            --// resetting for exactly what it did before.
            { Key = "RESET_BOOSTERS", Default = { "Boost", "BoostDrops" }, Normalize = NormalizeNameList },

            --// Ores Auto Mining collects, highest priority first, each mined
            --// until the inventory holds Target of it.
            { Key = "MINE_ORES", Default = {
                { Name = "Iron Ore", Target = 500 },
                { Name = "Copper Ore", Target = 500 },
            }, Normalize = NormalizeCountList("Target", SaveConfig.ITEM_MAX_STACK) },

            --// Recipes Auto Smithing crafts, highest priority first, each
            --// until the inventory holds Target of what it makes.
            { Key = "SMITH_RECIPES", Default = {
                { Name = "Iron Ingot", Target = 500 },
                { Name = "Copper Ingot", Target = 500 },
            }, Normalize = NormalizeCountList("Target", SaveConfig.ITEM_MAX_STACK) },

            --// Materials Auto Smithing never uses below Keep.
            { Key = "SMITH_RESERVES", Default = {}, Normalize = NormalizeCountList("Keep", 0) },

            --// Pinned item panel: items, popped out or not, and position.
            --// Shared by every PlaceId, so it lives in its own file.
            { Key = "PINNED_STATE", Default = {}, Normalize = NormalizePinnedState, Global = true },
        }

        --// Settings kept in ProfileManager's global file instead of a
        --// profile, shared by every profile and PlaceId. Same fields as
        --// Settings, without Scope.
        SaveConfig.GlobalSettings = {
            --// Enum.Font name the UI uses, picked in Configuration; "" keeps
            --// the built-in fonts.
            { Key = "UI_FONT", Default = "", Normalize = function(Value)
                return type(Value) == "string" and Value or ""
            end },

            --// UI text scale, picked in Configuration (Utils clamps it).
            { Key = "UI_TEXT_SCALE", Default = 1, Normalize = function(Value)
                return type(Value) == "number" and Value == Value and Value or 1
            end },

            --// Theme colours changed in Configuration, as Theme key -> hex
            --// ("RRGGBB"); keys left out keep the built-in colour.
            { Key = "UI_THEME", Default = {}, Normalize = function(Value)
                local Theme = {}

                if type(Value) == "table" then
                    for Key, Hex in pairs(Value) do
                        if type(Key) == "string" and type(Hex) == "string" and string.match(Hex, "^#?%x%x%x%x%x%x$") then
                            Theme[Key] = Hex
                        end
                    end
                end

                return Theme
            end },

            --// UserIds allowed to share the server. Auto Block ignores these.
            --// Shared by every profile and PlaceId.
            { Key = "BLOCK_WHITELIST", Default = {}, Normalize = NormalizeIdList },

            --// Discord webhook reporting (Webhook). The switch, the URL, the
            --// mention sent with it, the duo's name and the report format
            --// are the same on every profile and PlaceId, like the whitelist.
            { Key = "DISCORD_ENABLED", Default = true },
            { Key = "DISCORD_WEBHOOK", Default = "", Normalize = function(Value)
                return type(Value) == "string" and Value:gsub("^%s*(.-)%s*$", "%1") or ""
            end },
            { Key = "DISCORD_PING", Default = "", Normalize = function(Value)
                return type(Value) == "string" and Value:gsub("^%s*(.-)%s*$", "%1") or ""
            end },
            --// The duo's own UserId, mentioned next to the ping above.
            { Key = "DISCORD_DUO_PING", Default = "", Normalize = function(Value)
                return type(Value) == "string" and Value:gsub("^%s*(.-)%s*$", "%1") or ""
            end },
            { Key = "DISCORD_DUO", Default = "", Normalize = function(Value)
                return type(Value) == "string" and Value:gsub("^%s*(.-)%s*$", "%1") or ""
            end },
            --// Blank means the currency the script already tracks for the
            --// current event (AICUI.S.TargetCurrency).
            { Key = "DISCORD_EC_ITEM", Default = "", Normalize = function(Value)
                return type(Value) == "string" and Value:gsub("^%s*(.-)%s*$", "%1") or ""
            end },
            { Key = "DISCORD_FORMAT", Default = "Event Currency", Options = { "Event Currency", "EXP Grind" } },

            --// Group IDs Leave On Danger Group leaves for.
            { Key = "DANGER_GROUP_IDS", Default = { "5928691" }, Normalize = NormalizeIdList },

            --// UserIds Leave On Danger Group stays for. Separate from
            --// BLOCK_WHITELIST.
            { Key = "DANGER_WHITELIST", Default = {}, Normalize = NormalizeIdList },
        }

        local FeatureByName = {}
        for _, Entry in ipairs(SaveConfig.Features) do
            FeatureByName[Entry.Name] = Entry
        end

        local SettingByKey = {}
        for _, Entry in ipairs(SaveConfig.Settings) do
            SettingByKey[Entry.Key] = Entry
        end

        local function DeepCopy(Value)
            if type(Value) ~= "table" then
                return Value
            end

            local Result = {}
            for Key, Item in pairs(Value) do
                Result[Key] = DeepCopy(Item)
            end
            return Result
        end

        function SaveConfig.GetFeature(Name)
            return FeatureByName[Name]
        end

        function SaveConfig.GetSetting(Key)
            return SettingByKey[Key]
        end

        --// Fallback is used instead of Default when given, which is how a
        --// place-scoped setting falls back to that place's preset.
        function SaveConfig.NormalizeSetting(Entry, Value, Fallback)
            local Default = DeepCopy(Fallback ~= nil and Fallback or Entry.Default)

            if Entry.Normalize then
                return Entry.Normalize(Value ~= nil and Value or Default)
            end

            if type(Entry.Default) == "number" then
                local Number = tonumber(Value)

                if Number == nil then
                    Number = tonumber(Default) or Entry.Default
                end

                if Entry.Min and Entry.Max then
                    Number = math.clamp(Number, Entry.Min, Entry.Max)
                end

                return Number
            end

            if type(Entry.Default) == "boolean" then
                if type(Value) == "boolean" then
                    return Value
                end

                return Default == true
            end

            if Entry.Options then
                return table.find(Entry.Options, Value) and Value or Entry.Default
            end

            if Value == nil then
                return Default
            end

            return DeepCopy(Value)
        end

        function SaveConfig.GetSettingDefault(Entry, Fallback)
            return SaveConfig.NormalizeSetting(Entry, nil, Fallback)
        end

        return SaveConfig
    end,
}
