	["Features/AssetBrowser.lua"] = [======[
-- AssetBrowser is the Asset Explorer, a window of its own opened from the
-- Crafting tab. It shows every item in the game's assets (AssetDictionary):
--
--   * The left side lists them by type, then level, narrowed by the search
--     box and the ALL / OWNED / <type> chips. A thin bar under each row is
--     its best DMG / DEF / DEX against its type.
--   * The right side (AssetDetail) is the one picked: type, level, trade
--     lock, how many you have, its stats with their rank, buy and sell
--     price, the recipe that makes it and the mobs that drop it, and the
--     recipes that use it.
--   * DUMP DATABASE, across the bottom, writes every item, recipe and mob
--     the script can read to a JSON file (DatabaseDump).
return {
    Name = "AssetBrowser",
    IsFeature = true,
    Dependencies = {"Runtime", "Components", "BrowserShell", "DetailKit", "SmithingRecipes", "AssetDictionary", "AssetDetail", "DatabaseDump"},

    Start = function(Context)
        local UI = Context.UI
        local UIRef = Context.UIRef
        local Kit = Context.DetailKit
        local Recipes = Context.SmithingRecipes
        local Assets = Context.AssetDictionary
        local Detail = Context.AssetDetail
        local Dump = Context.DatabaseDump

        --// The inventory is read again this often while open.
        local REFRESH_INTERVAL = 2
        local ALL = "ALL"
        local OWNED = "OWNED"

        local Browser = {
            Name = "AssetBrowser",
            IsFeature = true,
            S = {
                LastRefresh = 0,
                --// Item -> count, read once per refresh.
                Stock = {},
            },
        }

        local S = Browser.S

        local function MatchesChip(Entry, Key)
            if Key == OWNED then
                return (S.Stock[Entry.Name] or 0) > 0
            end

            return Key == ALL or Key == nil or Entry.Type == Key
        end

        local function GetChips(Entries)
            local Counts, Types = {}, {}
            local Owned = 0

            for _, Entry in ipairs(Entries) do
                if not Counts[Entry.Type] then
                    Counts[Entry.Type] = 0
                    table.insert(Types, Entry.Type)
                end

                Counts[Entry.Type] += 1

                if (S.Stock[Entry.Name] or 0) > 0 then
                    Owned += 1
                end
            end

            table.sort(Types)

            local Chips = {
                { Key = ALL, Text = string.format("ALL  %d", #Entries) },
                { Key = OWNED, Text = string.format("OWNED  %d", Owned) },
            }

            for _, Type in ipairs(Types) do
                table.insert(Chips, { Key = Type, Text = string.format("%s  %d", string.upper(Type), Counts[Type]) })
            end

            return Chips
        end

        local function DescribeRow(Entry)
            local Theme = UI.Theme
            local Have = S.Stock[Entry.Name] or 0

            return {
                Info = Have > 0 and Entry.Summary .. "  ·  ×" .. Kit.FormatNumber(Have) or Entry.Summary,
                InfoColor = Have > 0 and Kit.GOOD_COLOR or nil,
                Accent = Entry.Flags.Bound and Theme.Warning or Theme.Cyan,
                Bar = Entry.Power,
                BarColor = Theme.Cyan,
            }
        end

        --// Name, type and every text value, so "fire" finds fire swords.
        local function MatchesSearch(Entry, Query)
            if string.find(string.lower(Entry.Name), Query, 1, true)
                or string.find(string.lower(Entry.Type), Query, 1, true)
            then
                return true
            end

            for _, Stat in ipairs(Entry.Stats) do
                if type(Stat.Value) == "string" and string.find(string.lower(Stat.Value), Query, 1, true) then
                    return true
                end
            end

            return false
        end

        local Shell = Context.BrowserShell.New({
            Title = "ASSET EXPLORER",
            Subtitle = "Every item  //  stats, price, where it comes from and goes",
            Width = 760,
            Height = 520,
            MinWidth = 580,
            MinHeight = 380,
            SearchPlaceholder = "SEARCH ITEM, TYPE OR VALUE...",
            ReloadText = "↻  RELOAD",
            OnReload = function()
                Browser:Reload()
            end,
            GetItems = function()
                return Assets:GetAll()
            end,
            GetChips = GetChips,
            MatchesChip = MatchesChip,
            MatchesSearch = MatchesSearch,
            DescribeRow = DescribeRow,
            GetSelected = function()
                return Detail:GetSelected()
            end,
            OnSelect = function(Name)
                Browser:Select(Name)
            end,
            GetEmptyText = function(Count)
                if Count == 0 then
                    return Assets.S.Error and "Assets unavailable" or "No items found"
                end

                return "No items match the filters"
            end,
            FooterText = "DUMP DATABASE",
            OnFooter = function()
                Browser:Dump()
            end,
        })

        function Browser:Refresh()
            if not Shell:IsOpen() then
                return
            end

            S.LastRefresh = os.clock()
            S.Stock = Recipes:GetInventory()
            Shell:RefreshList()
            Detail:Refresh(S.Stock)
        end

        function Browser:Select(Name)
            S.Stock = Recipes:GetInventory()
            Detail:Select(Name, S.Stock)
            Browser:Refresh()
        end

        --// Writes every item, recipe and mob to a JSON file, for the site's
        --// database to be built from (DatabaseDump).
        function Browser:Dump()
            Dump:Dump()
        end

        --// Reads the assets again, keeping the pick.
        function Browser:Reload()
            Assets:Load()

            if not Shell.Built then
                return
            end

            Shell:ResetRows()

            local Selected = Detail:GetSelected()

            if not Selected or not Assets:Get(Selected) then
                local First = Assets:GetAll()[1]
                Selected = First and First.Name or nil
            end

            Browser:Select(Selected)
        end

        function Browser:Open()
            if not Shell:Open() then
                return
            end

            Detail:Build(Shell.DetailScroll)

            if not Assets.S.Loaded then
                Browser:Reload()
            else
                S.Stock = Recipes:GetInventory()
                Detail:Rebuild(S.Stock)
                Browser:Refresh()
            end
        end

        function Browser:Toggle()
            if Shell:IsOpen() then
                Shell:Close()
            else
                Browser:Open()
            end
        end

        function Browser:Update()
            if Shell:IsOpen() and os.clock() - S.LastRefresh >= REFRESH_INTERVAL then
                Browser:Refresh()
            end
        end

        --// Under Open Recipe Browser on the Crafting tab, which AutoSmithing
        --// builds late too (it starts first, so its controls come first).
        function Browser:BuildLateUI()
            if UIRef.CraftSection then
                UIRef.CraftSection:AddButton{
                    Name = "Open Asset Explorer",
                    Callback = function()
                        Browser:Toggle()
                    end,
                }
            end
        end

        return Browser
    end,
}
]======],
	["Features/AssetDetail.lua"] = [======[
-- AssetDetail is the right side of the Asset Explorer (AssetBrowser): the
-- one item picked, laid out to be read at a glance:
--
--   * Its name, type, level, whether it can be traded, how it is locked
--     (pass, badge, group, event currency), and how many you have.
--   * DMG / DEF / DEX in big numbers with their rank among its type.
--   * VALUE: what the shop asks for it and pays for it.
--   * HOW TO GET: the recipe that makes it (materials against your
--     inventory) and the mobs seen dropping it, with the chance per kill.
--   * USED IN: the recipes that need it.
--   * Every number as a bar against the best of its type, its other values
--     as tags, its status effect, and COPY NAME / OPEN RECIPE.
return {
    Name = "AssetDetail",
    Dependencies = {"Runtime", "Floating", "DetailKit", "AssetDictionary", "MobDictionary"},

    Start = function(Context)
        local UI = Context.UI
        local Floating = Context.Floating
        local Kit = Context.DetailKit
        local Assets = Context.AssetDictionary
        local Mobs = Context.MobDictionary

        local Label, Button, ClearChildren = Floating.Label, Floating.Button, Floating.ClearChildren
        local FormatNumber, FormatPercent = Kit.FormatNumber, Kit.FormatPercent
        local Card, Heading, Note, Badge, Strip, Track, BarRow = Kit.Card, Kit.Heading, Kit.Note, Kit.Badge, Kit.Strip, Kit.Track, Kit.BarRow

        local STAT_BAR_HEIGHT = 30
        local LINE_HEIGHT = 16
        local POWER_KEYS = { "DMG", "DEF", "DEX" }
        local STAT_COLORS = { DMG = "Danger", DEF = "Cyan", DEX = "Warning" }

        local Detail = {
            Name = "AssetDetail",
            S = {
                Selected = nil,
                --// Inventory count, Luck and known drop sources the detail
                --// was built with; a change rebuilds it.
                Signature = nil,
            },
        }

        local S = Detail.S
        local Theme, Scroll

        local function GetStatColor(Key)
            local ThemeKey = STAT_COLORS[Key]
            return ThemeKey and Theme[ThemeKey] or Theme.TextSecondary
        end

        --// "1,200 COL", or the event currency it is bought with.
        local function FormatPrice(Entry, Amount)
            return FormatNumber(Amount) .. " " .. string.upper(Entry.EventCurrency or "Col")
        end

        --// A plain line of text, Color optional.
        local function Line(Parent, Text, Order, Color, Bold)
            return Label(Parent, Text, 10, {
                Size = UDim2.new(1, 0, 0, LINE_HEIGHT),
                TextColor3 = Color or Theme.Text,
                Font = Bold and Floating.Fonts.Bold or Floating.Fonts.Regular,
                LayoutOrder = Order,
            })
        end

        ------------------------------------------------------------------------
        --// Sections
        ------------------------------------------------------------------------

        local function BuildHero(Entry, Have, Order)
            local Hero = Card(Scroll, Order)

            Label(Hero, string.upper(Entry.Name), 16, {
                Font = Floating.Fonts.Bold,
                TextColor3 = Theme.Text,
                LayoutOrder = 1,
            })

            local Badges = Strip(Hero, 18, 2, true)
            local Flags = Entry.Flags
            local Level, LevelKind = Assets.GetLevel(Entry)
            local Index = 0

            local function Add(Text, Color)
                Index += 1
                Badge(Badges, Text, Color, Index)
            end

            Add(string.upper(Entry.Type), Theme.Cyan)

            if Level then
                Add(LevelKind .. " " .. FormatNumber(Level), Theme.TextSecondary)
            end

            Add(Flags.Bound and "BOUND" or "TRADEABLE", Flags.Bound and Theme.Warning or Kit.GOOD_COLOR)

            if Flags.Unobtainable then
                Add("UNOBTAINABLE", Theme.Danger)
            end

            if Flags.Pass then
                Add("GAME PASS", Theme.Warning)
            end

            if Flags.Badge then
                Add("BADGE", Theme.Warning)
            end

            if Flags.Group then
                Add("GROUP", Theme.Warning)
            end

            if Entry.EventCurrency then
                Add("EVENT  " .. string.upper(Entry.EventCurrency), Theme.Warning)
            end

            if Entry.Status then
                Add("☠  " .. string.upper(Entry.Status.Name), Theme.Warning)
            end

            Add(Have > 0 and ("HAVE  " .. FormatNumber(Have)) or "NOT OWNED", Have > 0 and Kit.GOOD_COLOR or Theme.TextMuted)
        end

        --// DMG / DEF / DEX in big type, or its worth when it has none.
        local function BuildTiles(Entry, Order)
            local Tiles = {}

            for _, Key in ipairs(POWER_KEYS) do
                local Value = Assets.GetStat(Entry, Key)

                if type(Value) == "number" then
                    local _, Rank, Total = Assets.GetScale(Entry.Type, Key, Value)

                    table.insert(Tiles, {
                        Value = FormatNumber(Value),
                        Label = Key,
                        Note = Rank and string.format("#%d OF %d", Rank, Total) or nil,
                        Color = GetStatColor(Key),
                    })
                end
            end

            if #Tiles == 0 and Entry.Worth then
                table.insert(Tiles, {
                    Value = FormatPrice(Entry, Entry.Worth),
                    Label = "WORTH",
                    Color = Theme.Cyan,
                })
            end

            Kit.Tiles(Scroll, Order, Tiles)
        end

        local function BuildValue(Entry, Order)
            if not Entry.Worth then
                return
            end

            local ValueCard = Card(Scroll, Order)
            Heading(ValueCard, "VALUE", 0)

            if Entry.Flags.Unobtainable then
                Line(ValueCard, "BUY  ·  not sold in shops", 1, Theme.TextMuted)
            else
                Line(ValueCard, "BUY  ·  " .. FormatPrice(Entry, Entry.Worth), 1, Theme.Cyan, true)
            end

            local Sell = Assets.GetSellPrice(Entry)

            if Sell then
                Line(ValueCard, string.format(
                    "SELL  ·  %s COL   (%s with the Agility pass)",
                    FormatNumber(Sell.Normal), FormatNumber(Sell.Agility)
                ), 2, Kit.GOOD_COLOR, true)
            else
                Line(ValueCard, "SELL  ·  the shop does not buy it", 2, Theme.TextMuted)
            end
        end

        --// The recipe: skill, and each material against the inventory.
        local function BuildRecipe(Parent, Recipe, Stock, Order)
            local Skill = Context.SmithingRecipes:GetSkill()
            local Locked = Recipe.Skill > Skill

            Line(Parent, string.format(
                "CRAFTED  ·  SMITHING SKILL %s  (YOURS %s)",
                FormatNumber(Recipe.Skill), FormatNumber(Skill)
            ), Order, Locked and Theme.Danger or Theme.Cyan, true)

            for Index, Material in ipairs(Recipe.Materials) do
                local Have = Stock[Material.Name] or 0

                Line(Parent, string.format(
                    "    %s   %s / %s",
                    Material.Name, FormatNumber(Have), FormatNumber(Material.Amount)
                ), Order + Index, Have >= Material.Amount and Theme.Text or Theme.Warning)
            end
        end

        local function BuildSources(Entry, Stock, Order)
            local Recipe = Assets:GetRecipe(Entry.Name)
            local Sources = Assets:GetDroppedBy(Entry.Name)
            local SourceCard = Card(Scroll, Order)

            Heading(SourceCard, "HOW TO GET", 0)

            if Recipe then
                BuildRecipe(SourceCard, Recipe, Stock, 1)
            end

            for Index, Source in ipairs(Sources) do
                local Holder = BarRow(
                    SourceCard, STAT_BAR_HEIGHT, 100 + Index,
                    "DROPPED BY  " .. string.upper(Source.Mob),
                    FormatPercent(Source.Chance) .. " / KILL",
                    Source.Chance > 0 and Theme.Cyan or Theme.Danger
                )

                Track(Holder, 18, { { Fraction = Source.Chance, Color = Theme.Cyan } })
            end

            if not Recipe and #Sources == 0 then
                Note(SourceCard, Entry.Flags.Unobtainable
                    and "No recipe makes it and no known mob drops it."
                    or "No recipe makes it and no known mob drops it. It may be sold in a shop.", 1)
            end

            Note(SourceCard, "Drops are known for mobs that have been in the server, now or in an earlier run (Mob Dictionary).", 999)
        end

        local function BuildUses(Entry, Order)
            local Uses = Assets:GetUses(Entry.Name)

            if #Uses == 0 then
                return
            end

            local UsesCard = Card(Scroll, Order)
            Heading(UsesCard, string.format("USED IN  %d RECIPE%s", #Uses, #Uses == 1 and "" or "S"), 0)

            for Index, Use in ipairs(Uses) do
                Line(UsesCard, string.format(
                    "%s   ×%s   ·   SKILL %s",
                    string.upper(Use.Recipe.Name), FormatNumber(Use.Amount), FormatNumber(Use.Recipe.Skill)
                ), Index)
            end
        end

        --// Every number, and its worth, against the best of its type.
        local function BuildBars(Entry, Order)
            local Rows = {}

            for _, Stat in ipairs(Entry.Stats) do
                if Stat.Numeric then
                    table.insert(Rows, { Key = Stat.Key, Label = Stat.Label, Value = Stat.Value })
                end
            end

            if Entry.Worth then
                table.insert(Rows, { Key = "Worth", Label = "WORTH", Value = Entry.Worth })
            end

            if #Rows == 0 then
                return
            end

            local BarsCard = Card(Scroll, Order)
            Heading(BarsCard, "COMPARED TO THE BEST " .. string.upper(Entry.Type), 0)

            for Index, Row in ipairs(Rows) do
                local Fraction, Rank, Total = Assets.GetScale(Entry.Type, Row.Key, Row.Value)
                local Value = FormatNumber(Row.Value) .. (Rank and string.format("   #%d/%d", Rank, Total) or "")
                local Holder = BarRow(BarsCard, STAT_BAR_HEIGHT, Index, Row.Label, Value)
                Track(Holder, 18, { { Fraction = Fraction, Color = GetStatColor(Row.Key) } })
            end
        end

        local function BuildTraits(Entry, Order)
            local Traits = {}

            for _, Stat in ipairs(Entry.Stats) do
                if not Stat.Numeric then
                    table.insert(Traits, Stat)
                end
            end

            if #Traits > 0 then
                local TraitsCard = Card(Scroll, Order)
                Heading(TraitsCard, "TRAITS", 0)
                Kit.Tags(TraitsCard, Traits, Theme.TextSecondary, 1)
            end

            if Entry.Status then
                local StatusCard = Card(Scroll, Order + 1)
                Heading(StatusCard, "STATUS EFFECT", 0)
                Line(StatusCard, "☠  " .. string.upper(Entry.Status.Name), 1, Theme.Warning, true)

                if #Entry.Status.Props > 0 then
                    Kit.Tags(StatusCard, Entry.Status.Props, Theme.Warning, 2)
                end
            end
        end

        local function BuildActions(Entry, Order)
            local Row = Strip(Scroll, 28, Order)
            Row.Size = UDim2.new(1, -6, 0, 28)

            local HasRecipe = Assets:GetRecipe(Entry.Name) ~= nil
            local CopyButton = Button(Row, "COPY NAME", Theme.TextMuted, {
                Size = UDim2.new(HasRecipe and 0.5 or 1, HasRecipe and -2 or 0, 1, 0),
                LayoutOrder = 1,
            })

            CopyButton.Activated:Connect(function()
                local Copied = Floating.CopyText(Entry.Name)
                Context.NotifyAction("Asset Explorer", Copied and "Name copied" or "No clipboard here")
            end)

            if HasRecipe then
                local RecipeButton = Button(Row, "OPEN RECIPE  ›", Theme.Cyan, {
                    Size = UDim2.new(0.5, -2, 1, 0),
                    LayoutOrder = 2,
                })

                RecipeButton.Activated:Connect(function()
                    local Browser = Context.SmithingBrowser

                    if Browser then
                        Browser:Open()
                        Browser:Select(Entry.Name)
                    end
                end)
            end
        end

        --// Changes with the counts held of it and its materials, Luck, and
        --// the mobs known to drop it.
        local function GetSignature(Stock)
            local _, _, LuckPercent = Mobs.GetLuck()
            local Name = S.Selected
            local Parts = { tostring(Stock[Name] or 0), tostring(LuckPercent), tostring(#Assets:GetDroppedBy(Name)) }
            local Recipe = Assets:GetRecipe(Name)

            for _, Material in ipairs(Recipe and Recipe.Materials or {}) do
                table.insert(Parts, tostring(Stock[Material.Name] or 0))
            end

            return table.concat(Parts, "|")
        end

        ------------------------------------------------------------------------
        --// API
        ------------------------------------------------------------------------

        function Detail:Build(Parent)
            Theme = UI.Theme
            Scroll = Parent
        end

        function Detail:GetSelected()
            return S.Selected
        end

        --// Stock is the inventory (item -> count), read once by the caller.
        function Detail:Rebuild(Stock)
            if not Scroll then
                return
            end

            ClearChildren(Scroll)

            local Entry = S.Selected and Assets:Get(S.Selected)

            if not Entry then
                local Error = Assets.S.Error
                Note(Scroll, Error or "Pick an item on the left", 0, Error and Theme.Danger or nil)
                S.Signature = nil
                return
            end

            local Have = Stock[Entry.Name] or 0
            S.Signature = GetSignature(Stock)

            BuildHero(Entry, Have, 1)
            BuildTiles(Entry, 2)
            BuildValue(Entry, 3)
            BuildSources(Entry, Stock, 4)
            BuildUses(Entry, 5)
            BuildBars(Entry, 6)
            BuildTraits(Entry, 7)
            BuildActions(Entry, 9)
        end

        function Detail:Select(Name, Stock)
            S.Selected = Name
            Detail:Rebuild(Stock)
        end

        --// Rebuilt when the count held, Luck or the known drops changed.
        function Detail:Refresh(Stock)
            if not Scroll or not S.Selected then
                return
            end

            if GetSignature(Stock) ~= S.Signature then
                Detail:Rebuild(Stock)
            end
        end

        return Detail
    end,
}
]======],
	["Features/AssetDictionary.lua"] = [======[
-- AssetDictionary turns the game's assets (CoreCommons.getAssets, read by
-- SmithingRecipes) into one entry per item for the Asset Explorer
-- (AssetBrowser):
--
--   Entry = {
--       Name, Type (the asset's Value, "Other" when empty),
--       Stats = { { Key, Label, Value, Numeric } ... },  every value child
--       Worth, Flags = { Bound, Unobtainable, Badge, Pass, Group },
--       EventCurrency (the currency it is bought with, or nil),
--       Status = { Name, Props } or nil,
--   }
--
-- It also answers where an item comes from and goes: the recipe that makes
-- it, the recipes that use it, the mobs seen dropping it (MobDictionary),
-- and what the shop pays for it. Numbers are ranked against the other items
-- of the same type.
return {
    Name = "AssetDictionary",
    Dependencies = {"Runtime", "SmithingRecipes", "MobDictionary", "DetailKit"},

    Start = function(Context)
        local Recipes = Context.SmithingRecipes
        local Mobs = Context.MobDictionary
        local Kit = Context.DetailKit

        --// Children that are flags or shown on their own, not as stats.
        local FLAG_KEYS = { Bound = true, Unobtainable = true, Badge = true, Pass = true, Group = true }
        local SPECIAL_KEYS = { StatusEffect = true, EventCurrency = true, Worth = true }
        --// Stats an item's power is judged by, for the list bar.
        local POWER_KEYS = { "DMG", "DEF", "DEX" }
        --// The shop pays this share of Worth, or the second with the
        --// Agility pass. Items needing a pass, badge or group, or bought
        --// with an event currency, cannot be sold.
        local SELL_SHARE = 0.35
        local SELL_SHARE_AGILITY = 0.45

        local Dictionary = {
            Name = "AssetDictionary",
            SELL_SHARE = SELL_SHARE,
            SELL_SHARE_AGILITY = SELL_SHARE_AGILITY,
            S = {
                Entries = {},
                ByName = {},
                --// Type -> stat key -> { Max, Sorted (descending) }.
                Scales = {},
                Loaded = false,
                Error = nil,
            },
        }

        local S = Dictionary.S

        ------------------------------------------------------------------------
        --// Reading
        ------------------------------------------------------------------------

        local function SafeValue(Object)
            local Ok, Value = pcall(function()
                return Object.Value
            end)

            return Ok and Value or nil
        end

        --// Name -> { Value, Children } for every value child of an asset; an
        --// asset is an Instance, or a plain table of the same shape.
        local function ReadChildren(Asset)
            local Children = {}

            if typeof(Asset) == "Instance" then
                for _, Child in ipairs(Asset:GetChildren()) do
                    if Child:IsA("ValueBase") then
                        Children[Child.Name] = { Value = Child.Value, Children = ReadChildren(Child) }
                    end
                end
            elseif type(Asset) == "table" then
                for Name, Child in pairs(Asset) do
                    if type(Name) == "string" and Name ~= "Value" and type(Child) == "table" then
                        Children[Name] = { Value = Child.Value, Children = ReadChildren(Child) }
                    end
                end
            end

            return Children
        end

        local function ReadStatus(Child)
            local Effect = Child and Child.Value

            if Effect == nil or Effect == false or Effect == "" or string.lower(tostring(Effect)) == "none" then
                return nil
            end

            local Status = { Name = tostring(Effect), Props = {} }

            for Name, Prop in pairs(Child.Children) do
                table.insert(Status.Props, { Label = Kit.Prettify(Name), Value = Prop.Value })
            end

            table.sort(Status.Props, function(A, B)
                return A.Label < B.Label
            end)

            return Status
        end

        local function ReadEntry(Name, Asset)
            local Type = SafeValue(Asset)
            Type = Type ~= nil and tostring(Type) or ""

            local Children = ReadChildren(Asset)
            local Entry = {
                Name = Name,
                Type = Type ~= "" and Type or Recipes.UNKNOWN_TYPE,
                Stats = {},
                Flags = {},
                Worth = tonumber(Children.Worth and Children.Worth.Value),
                EventCurrency = Children.EventCurrency and tostring(Children.EventCurrency.Value) or nil,
                Status = ReadStatus(Children.StatusEffect),
            }

            for Key, Child in pairs(Children) do
                if FLAG_KEYS[Key] then
                    Entry.Flags[Key] = true
                elseif not SPECIAL_KEYS[Key] and Child.Value ~= nil then
                    table.insert(Entry.Stats, {
                        Key = Key,
                        Label = Kit.Prettify(Key),
                        Value = Child.Value,
                        Numeric = type(Child.Value) == "number",
                    })
                end
            end

            table.sort(Entry.Stats, function(A, B)
                return A.Label < B.Label
            end)

            return Entry
        end

        function Dictionary.GetStat(Entry, Key)
            for _, Stat in ipairs(Entry.Stats) do
                if Stat.Key == Key then
                    return Stat.Value
                end
            end

            return nil
        end

        --// Level, else the skill it needs, for sorting and the list.
        function Dictionary.GetLevel(Entry)
            local Level = Dictionary.GetStat(Entry, "LVL")

            if type(Level) == "number" then
                return Level, "LV"
            end

            local Skill = Dictionary.GetStat(Entry, "Skill")
            return type(Skill) == "number" and Skill or nil, "SKILL"
        end

        ------------------------------------------------------------------------
        --// Ranking within a type
        ------------------------------------------------------------------------

        local function BuildScales()
            local Values = {}

            for _, Entry in ipairs(S.Entries) do
                Values[Entry.Type] = Values[Entry.Type] or {}

                local Numbers = {}

                for _, Stat in ipairs(Entry.Stats) do
                    if Stat.Numeric then
                        Numbers[Stat.Key] = Stat.Value
                    end
                end

                Numbers.Worth = Entry.Worth

                for Key, Value in pairs(Numbers) do
                    Values[Entry.Type][Key] = Values[Entry.Type][Key] or {}
                    table.insert(Values[Entry.Type][Key], Value)
                end
            end

            S.Scales = {}

            for Type, Keys in pairs(Values) do
                S.Scales[Type] = {}

                for Key, List in pairs(Keys) do
                    table.sort(List, function(A, B)
                        return A > B
                    end)

                    S.Scales[Type][Key] = { Max = List[1], Sorted = List }
                end
            end
        end

        --// Fraction of the highest Value among the items of Type with this
        --// stat (0..1), its rank (1 = highest) and how many have it.
        function Dictionary.GetScale(Type, Key, Value)
            local Scales = S.Scales[Type]
            local Scale = Scales and Scales[Key]

            if not Scale or type(Value) ~= "number" then
                return 0, nil, 0
            end

            local Fraction = Scale.Max > 0 and math.clamp(Value / Scale.Max, 0, 1) or 0
            return Fraction, table.find(Scale.Sorted, Value), #Scale.Sorted
        end

        --// 0..1: the best of DMG / DEF / DEX against its type, or nil when
        --// it has none of them.
        function Dictionary.GetPower(Entry)
            local Best = nil

            for _, Key in ipairs(POWER_KEYS) do
                local Value = Dictionary.GetStat(Entry, Key)

                if type(Value) == "number" then
                    Best = math.max(Best or 0, (Dictionary.GetScale(Entry.Type, Key, Value)))
                end
            end

            return Best
        end

        --// "WEAPON  ·  LV 20  ·  DMG 45  ·  DEX 3".
        function Dictionary.Summarize(Entry)
            local Parts = { string.upper(Entry.Type) }
            local Level, LevelKind = Dictionary.GetLevel(Entry)

            if Level then
                table.insert(Parts, LevelKind .. " " .. Kit.FormatNumber(Level))
            end

            for _, Key in ipairs(POWER_KEYS) do
                local Value = Dictionary.GetStat(Entry, Key)

                if type(Value) == "number" then
                    table.insert(Parts, Key .. " " .. Kit.FormatNumber(Value))
                end
            end

            return table.concat(Parts, "  ·  ")
        end

        ------------------------------------------------------------------------
        --// Load
        ------------------------------------------------------------------------

        --// Reads the assets again. False (and S.Error) when they cannot be
        --// read right now.
        function Dictionary:Load()
            local Assets = Recipes:GetAssets()

            if type(Assets) ~= "table" then
                S.Error = "The game's assets cannot be read right now. Press RELOAD to try again."
                return false
            end

            local Entries, ByName = {}, {}

            for Name, Asset in pairs(Assets) do
                if type(Name) == "string" and (typeof(Asset) == "Instance" or type(Asset) == "table") then
                    local Entry = ReadEntry(Name, Asset)
                    table.insert(Entries, Entry)
                    ByName[Name] = Entry
                end
            end

            --// By type, then level (or skill), then name.
            table.sort(Entries, function(A, B)
                if A.Type ~= B.Type then
                    return A.Type < B.Type
                end

                local LevelA = Dictionary.GetLevel(A) or 0
                local LevelB = Dictionary.GetLevel(B) or 0

                if LevelA ~= LevelB then
                    return LevelA < LevelB
                end

                return A.Name < B.Name
            end)

            S.Entries = Entries
            S.ByName = ByName
            S.Error = nil
            S.Loaded = true
            BuildScales()

            --// Fixed for the load, and wanted for every list row.
            for _, Entry in ipairs(Entries) do
                Entry.Power = Dictionary.GetPower(Entry)
                Entry.Summary = Dictionary.Summarize(Entry)
            end

            return true
        end

        function Dictionary:GetAll()
            return S.Entries
        end

        function Dictionary:Get(Name)
            return S.ByName[Name]
        end

        ------------------------------------------------------------------------
        --// Where an item comes from and goes
        ------------------------------------------------------------------------

        --// The recipe that makes Name, or nil.
        function Dictionary:GetRecipe(Name)
            return Recipes:Get(Name)
        end

        --// Recipes using Name as a material: { { Recipe, Amount } ... }.
        function Dictionary:GetUses(Name)
            local Uses = {}

            for _, Recipe in ipairs(Recipes:GetAll()) do
                for _, Material in ipairs(Recipe.Materials) do
                    if Material.Name == Name then
                        table.insert(Uses, { Recipe = Recipe, Amount = Material.Amount })
                    end
                end
            end

            return Uses
        end

        --// Mobs seen (this run or saved) that drop Name, best chance first:
        --// { { Mob, Chance (with Luck), Drop } ... }.
        function Dictionary:GetDroppedBy(Name)
            local _, _, LuckPercent = Mobs.GetLuck()
            local Sources = {}

            for MobName, Drops in pairs(Mobs.S.Drops) do
                for _, Drop in ipairs(Drops) do
                    if Drop.Name == Name then
                        table.insert(Sources, {
                            Mob = MobName,
                            Drop = Drop,
                            Chance = (Mobs.GetDropOdds(Drop, LuckPercent)),
                        })
                    end
                end
            end

            table.sort(Sources, function(A, B)
                if A.Chance ~= B.Chance then
                    return A.Chance > B.Chance
                end

                return A.Mob < B.Mob
            end)

            return Sources
        end

        --// What the shop pays for one: { Normal, Agility }, or nil when it
        --// cannot be sold there.
        function Dictionary.GetSellPrice(Entry)
            local Flags = Entry.Flags

            if not Entry.Worth or Flags.Pass or Flags.Badge or Flags.Group or Entry.EventCurrency then
                return nil
            end

            return {
                Normal = math.floor(Entry.Worth * SELL_SHARE),
                Agility = math.floor(Entry.Worth * SELL_SHARE_AGILITY),
            }
        end

        --// How many the inventory holds.
        function Dictionary:GetHave(Name)
            return Recipes:GetInventory()[Name] or 0
        end

        return Dictionary
    end,
}
]======],
	["Features/AutoBlock.lua"] = [======[
-- AutoBlock owns its state, blocking logic, whitelist, and UI.
return {
    Name = "AutoBlock",
    IsFeature = true,
    Dependencies = {"Runtime", "SaveConfig", "ProfileManager", "Components"},

    Start = function(Context)
        local Runtime = Context.Runtime
        local Services = Context.Services
        local Players = Services.Players
        local StarterGui = Services.StarterGui
        local Player = Context.Player
        local CONFIG = Context.CONFIG
        local Feature = Context.Feature
        local AICFeature = Context.AICFeature
        local AICUI = Context.AICUI
        local AICProfile = Context.AICProfile
        local UIRef = Context.UIRef
        local NotifyAction = Context.NotifyAction

        --// Roblox adds a player to the block list as soon as Block is
        --// pressed, before its block request has gone through, and takes
        --// them off again if it fails. A hop waits until they have stayed
        --// blocked this long, so leaving cannot cut the request short.
        local BLOCK_SETTLE_SECONDS = 1.5

        local AutoBlock = {
            Name = "AutoBlock",
            IsFeature = true,
            Enabled = false,
            Button = nil,
            WhitelistComponent = nil,
            WhitelistBox = nil,
            WhitelistDropdown = nil,
        }

        AICFeature.S.BlockCache = AICFeature.S.BlockCache or {}
        --// UserId -> os.clock() when Auto Block first saw that intruder.
        AICFeature.S.IntruderSeenAt = {}
        --// UserId -> os.clock() when that player was first seen blocked.
        AICFeature.S.BlockedSince = {}
        AICFeature.S.BlockEnabled = Runtime:GetPlaceConfig().AUTOBLOCK == true
        AutoBlock.Enabled = AICFeature.S.BlockEnabled
        Feature.AutoBlock.Enabled = AutoBlock.Enabled

        function AutoBlock:SetEnabled(Value, Save)
            self.Enabled = Value == true
            AICFeature.S.BlockEnabled = self.Enabled
            Feature.AutoBlock.Enabled = self.Enabled

            if self.Button then
                self.Button:Set(self.Enabled, false)
            end

            if Save ~= false and AICProfile.SaveActiveProfile then
                AICProfile.SaveActiveProfile()
            end
        end

        --// One departure per session. A teleport or kick can fail without
        --// saying so, and the farm used to ask again on the very next frame:
        --// each ask posted another departure report and, after a kick, the
        --// farm kept running behind the disconnect screen. Departing is set
        --// on the first ask and cleared only by the script reloading in the
        --// next server, or by the watchdog of a hop that never happened;
        --// LeaveStarted records that the report went out, so a retry cannot
        --// post it twice; LeaveAttempts counts teleport tries, so a refused
        --// hop gets one retry and then gives up with a notice.
        AICFeature.S.Departing = false
        AICFeature.S.LeaveStarted = false
        AICFeature.S.LeaveAttempts = 0
        --// A leave asked for before the Block Delay ran out is waiting on
        --// its timer; only one such timer is ever scheduled.
        AICFeature.S.LeaveWaiting = false

        --// Seconds before a refused teleport is tried once more.
        local LEAVE_RETRY_DELAY = 10

        --// A leave the script starts on its own pauses a random 2-4 s first,
        --// so the client never drops the server the same instant a stranger
        --// appeared: short enough not to be noticed, long enough not to look
        --// like a machine answering a join. Random Leave Delay turns it off.
        local RANDOM_LEAVE_MIN = 2
        local RANDOM_LEAVE_MAX = 4

        --// A teleport that never happens leaves the client where it was. If
        --// this timer still runs, the hop did not take, so the latch is freed
        --// and the farm may try again - with no second report, because
        --// LeaveStarted stays set. A kick runs no such timer: it is decisive,
        --// and repeating it is what put the client through five kicks' worth
        --// of reports.
        local HOP_WATCHDOG = 20

        function AutoBlock:IsLeaving()
            return AICFeature.S.Departing == true
        end

        --// The departure report, posted once. False when one was already sent,
        --// so a retry or a second caller cannot report the same leave again.
        function AutoBlock:BeginLeave(OtherPlayer)
            if AICFeature.S.LeaveStarted then
                return false
            end

            AICFeature.S.LeaveStarted = true

            if AICFeature.ReportBeforeLeave then
                AICFeature.ReportBeforeLeave(OtherPlayer)
            end

            return true
        end

        --// The teleport itself, carrying out a departure that has already been
        --// reported. A refusal is retried once, later, and then dropped with a
        --// notice rather than being asked for again every frame.
        function AutoBlock:SendHop(Target)
            AICFeature.S.LeaveAttempts += 1

            local Success, Error = pcall(function()
                game:GetService("TeleportService"):Teleport(Target, Player)
            end)

            if Success then
                task.delay(HOP_WATCHDOG, function()
                    --// Still running means the hop never took, so this attempt
                    --// is over and the next one is a new departure: it may
                    --// report again, because the first end described a leave
                    --// that did not happen.
                    AICFeature.S.Departing = false
                    AICFeature.S.LeaveStarted = false
                end)

                return true
            end

            warn("[AutoBlock] Teleport failed:", Error)

            if AICFeature.S.LeaveAttempts >= 2 then
                NotifyAction("Auto Block", "Could not leave the server", 6)
                return false
            end

            task.delay(LEAVE_RETRY_DELAY, function()
                AutoBlock:SendHop(Target)
            end)

            return false
        end

        --// Every hop in the farm (block, server age) goes through here, so the
        --// Webhook report is posted before the client is moved and cannot be
        --// cut off by the teleport. A hop caused by a player names them in the
        --// report, so the log says who it was. Only the first hop of a session
        --// is made and reported; a later call is ignored.
        function AutoBlock:TeleportToPlace(PlaceId, OtherPlayer)
            if self:IsLeaving() then
                return false
            end

            AICFeature.S.Departing = true
            self:BeginLeave(OtherPlayer)

            return self:SendHop(PlaceId or game.PlaceId)
        end

        --// Someone on the Block Whitelist is never the reason the game is
        --// closed. Their presence is what the list is for, so Leave Instead
        --// Of Block leaves them alone even if they sit on Roblox's block
        --// list as well: it is the escape from a stranger, not from a name
        --// you chose to keep.
        function AutoBlock:IsLeaveExempt(OtherPlayer)
            return OtherPlayer ~= nil
                and OtherPlayer.UserId ~= nil
                and self:IsWhitelisted(OtherPlayer.UserId) == true
        end

        --// How long a leave the script starts should wait before it happens:
        --// the random 2-4 s pause while Random Leave Delay is on, nothing at
        --// all while it is off. Every leave path reads it, so nothing leaves
        --// the instant a stranger is noticed.
        function AutoBlock:LeaveDelay()
            if not Feature.RandomLeaveDelay or Feature.RandomLeaveDelay.Enabled ~= true then
                return 0
            end

            return RANDOM_LEAVE_MIN + math.random() * (RANDOM_LEAVE_MAX - RANDOM_LEAVE_MIN)
        end

        --// The rest of a wait nobody has to spend in a frame loop. When it
        --// runs out the leave is asked for again, so the game still closes
        --// even if the caller was the only one who wanted it, and it is the
        --// only ask that skips the wait (`Ready`): one pause per leave, not
        --// one per re-ask. A player who left, or is exempt by then, is left
        --// alone: there is nobody to leave for.
        function AutoBlock:WaitThenLeave(Reason, OtherPlayer, Wait)
            if AICFeature.S.LeaveWaiting then
                return false
            end

            AICFeature.S.LeaveWaiting = true

            task.delay(Wait, function()
                AICFeature.S.LeaveWaiting = false

                if OtherPlayer ~= nil
                    and (OtherPlayer.Parent ~= Players or self:IsLeaveExempt(OtherPlayer))
                then
                    return
                end

                self:LeaveGame(Reason, OtherPlayer, true)
            end)

            return true
        end

        --// Leave Instead Of Block's way out: not another server, the game
        --// itself. A kick is the only thing a client script can use to get
        --// back out to the Roblox app, and it reports first, naming whoever
        --// made us leave.
        function AutoBlock:LeaveGame(Reason, OtherPlayer, Ready)
            --// Refused silently: a caller that asks every frame must not be
            --// answered with a notification every frame.
            if self:IsLeaveExempt(OtherPlayer) then
                return false
            end

            if self:IsLeaving() then
                return false
            end

            --// Nothing leaves instantly. The wait is whichever is longer: the
            --// Block Delay still owed to the stranger, so the setting is
            --// honoured wherever the ask came from, or the random pause that
            --// keeps a leave from landing on the very frame they joined. An
            --// ask inside it waits on one timer and looks again when it runs
            --// out; `Ready` is that second look, and waits on nothing more.
            if Ready ~= true then
                local Wait = self:LeaveDelay()

                if OtherPlayer ~= nil then
                    Wait = math.max(Wait, self:BlockDelayRemaining(OtherPlayer))
                end

                if Wait > 0 then
                    self:WaitThenLeave(Reason, OtherPlayer, Wait)
                    return false
                end
            end

            AICFeature.S.Departing = true
            self:BeginLeave(OtherPlayer)

            local Text = Reason or "Auto Block: leaving the game"

            if OtherPlayer and OtherPlayer.Name then
                Text = Text .. " (@" .. tostring(OtherPlayer.Name) .. ")"
            end

            local Success = pcall(function()
                Player:Kick(Text)
            end)

            if Success then
                return true
            end

            --// The kick was refused: hop instead, with no second report, so
            --// the setting still gets the client out of the server.
            return self:SendHop(game.PlaceId)
        end

        function AutoBlock:NormalizeUserId(Value)
            local Text = tostring(Value or ""):gsub("%s+", "")

            if Text == "" or not Text:match("^%d+$") then
                return nil
            end

            return Text
        end

        function AutoBlock:IsWhitelisted(UserId)
            local Id = self:NormalizeUserId(UserId)

            if not Id then
                return false
            end

            for _, Entry in ipairs(CONFIG.BLOCK_WHITELIST or {}) do
                if self:NormalizeUserId(Entry) == Id then
                    return true
                end
            end

            return false
        end

        --// Whether the checks that leave the server (Auto Block's hop from a
        --// blocked player, Leave On Danger Group) leave this player alone.
        --// Prompting a block always skips whitelisted players; only leaving
        --// follows Whitelist Skips Safety.
        function AutoBlock:IsSafetyExempt(UserId)
            return Feature.WhitelistSkipsSafety.Enabled == true and self:IsWhitelisted(UserId)
        end

        function AutoBlock:IsBlocked(UserId)
            local Success, BlockedUserIds = pcall(function()
                return StarterGui:GetCore("GetBlockedUserIds")
            end)

            if not Success or not BlockedUserIds then
                return false
            end

            for _, BlockedUserId in BlockedUserIds do
                if BlockedUserId == UserId then
                    return true
                end
            end

            return false
        end

        --// Whether the block on this player is done: on the block list,
        --// unbroken, for BLOCK_SETTLE_SECONDS, with Auto Confirm Block no
        --// longer working on their dialog. Ask every frame or poll; the
        --// clock starts the first time they are seen blocked.
        function AutoBlock:IsBlockSettled(OtherPlayer)
            local UserId = OtherPlayer.UserId

            if not self:IsBlocked(UserId) then
                AICFeature.S.BlockedSince[UserId] = nil
                return false
            end

            local now = os.clock()
            local Since = AICFeature.S.BlockedSince[UserId]

            if not Since then
                Since = now
                AICFeature.S.BlockedSince[UserId] = now
            end

            if AICFeature.IsConfirmingBlock and AICFeature.IsConfirmingBlock(OtherPlayer) then
                return false
            end

            return now - Since >= BLOCK_SETTLE_SECONDS
        end

        --// When Auto Block first saw this player: stamped the moment they
        --// arrived (Players.PlayerAdded in CreateUI), and on the first look
        --// at them for someone already here when the script loaded. One
        --// stamp per player per server, cleared when they leave.
        local function SeenAt(UserId)
            local Seen = AICFeature.S.IntruderSeenAt[UserId]

            if not Seen then
                Seen = os.clock()
                AICFeature.S.IntruderSeenAt[UserId] = Seen
            end

            return Seen
        end

        function AutoBlock:BlockDelay()
            return math.max(tonumber(CONFIG.AUTO_BLOCK_DELAY) or 0, 0)
        end

        --// Seconds of Block Delay still owed to this player. Zero or less
        --// means it has run out and they may be blocked or left for.
        function AutoBlock:BlockDelayRemaining(OtherPlayer)
            local Since = SeenAt(OtherPlayer.UserId)

            return self:BlockDelay() - (os.clock() - Since)
        end

        --// Block Delay: an intruder is acted on only once they have been
        --// here for AUTO_BLOCK_DELAY seconds. The clock starts on arrival,
        --// not on the decision, so a stranger is not rushed because the
        --// block or the leave was only asked about later.
        function AutoBlock:IsBlockDelayOver(OtherPlayer)
            return self:BlockDelayRemaining(OtherPlayer) <= 0
        end

        function AutoBlock:PromptBlockPlayer(OtherPlayer)
            local UserId = OtherPlayer.UserId

            if AICFeature.S.BlockCache[UserId] or self:IsBlocked(UserId) then
                return
            end

            --// Auto Confirm Block is still pressing the dialog already open
            --// for them; opening it again would pull it out from under it.
            if AICFeature.IsConfirmingBlock and AICFeature.IsConfirmingBlock(OtherPlayer) then
                return
            end

            AICFeature.S.BlockCache[UserId] = true

            local Success, ErrorMessage = pcall(function()
                StarterGui:SetCore("PromptBlockPlayer", OtherPlayer)
            end)

            if not Success then
                warn("PromptBlockPlayer failed:", ErrorMessage)
                AICFeature.S.BlockCache[UserId] = nil
                return
            end

            --// Auto Confirm Block presses Block in the dialog when it is on.
            if AICFeature.ConfirmBlockPrompt then
                AICFeature.ConfirmBlockPrompt(OtherPlayer)
            end

            task.delay(CONFIG.BLOCK_COOLDOWN, function()
                AICFeature.S.BlockCache[UserId] = nil
            end)
        end

        function AutoBlock:RefreshWhitelistPlayerDropdown()
            local Section = UIRef.BlockSection

            if not Section then
                return
            end

            table.clear(UIRef.WhitelistPlayerOptions)

            local Options = {}

            for _, OtherPlayer in ipairs(Players:GetPlayers()) do
                if OtherPlayer ~= Player and not self:IsWhitelisted(OtherPlayer.UserId) then
                    local Label = string.format(
                        "%s (@%s)  %d",
                        OtherPlayer.DisplayName,
                        OtherPlayer.Name,
                        OtherPlayer.UserId
                    )

                    UIRef.WhitelistPlayerOptions[Label] = tostring(OtherPlayer.UserId)
                    table.insert(Options, Label)
                end
            end

            table.sort(Options, function(A, B)
                return string.lower(A) < string.lower(B)
            end)

            if #Options == 0 then
                Options = {"No other players"}
            end

            self.WhitelistDropdown = AICUI.ReplaceDropdown(
                UIRef.WhitelistPlayerDropdown,
                Section,
                "Add Player In Server",
                Options,
                function(Value)
                    local Id = UIRef.WhitelistPlayerOptions[Value]

                    if not Id or self:IsWhitelisted(Id) then
                        return
                    end

                    self.WhitelistComponent:Add(Id)
                    CONFIG.BLOCK_WHITELIST = self.WhitelistComponent.Priority
                    AICProfile.WriteGlobalStore()
                    NotifyAction("Whitelist", "Added " .. tostring(Value))
                    self:RefreshWhitelistPlayerDropdown()
                end
            )

            UIRef.WhitelistPlayerDropdown = self.WhitelistDropdown
        end

        function AutoBlock:RefreshUI()
            if self.WhitelistComponent then
                self.WhitelistComponent:SetPriority(table.clone(CONFIG.BLOCK_WHITELIST or {}))
            end

            self:SetEnabled(AICFeature.S.BlockEnabled == true, false)
            self:RefreshWhitelistPlayerDropdown()
        end

        function AutoBlock:CreateUI()
            local BlockSection = UIRef.BlockSection

            if not BlockSection then
                return
            end

            --// The alternative to blocking, kept above Auto Block and set
            --// apart by a divider: the same Block Delay, then the game is
            --// closed to the Roblox app without a block at all.
            AICUI.BindFeatureToggle("AutoBlockLeaveOnly", "Leave Instead Of Block", nil, BlockSection)
            BlockSection:AddLabel("On: the game is closed to the Roblox app once Block Delay (s) runs out")

            BlockSection:AddDivider()

            self.Button = BlockSection:AddToggle{
                Name = "Auto Block",
                Default = self.Enabled,
                Callback = function(Value)
                    self:SetEnabled(Value)
                end,
            }

            Feature.AutoBlock.Button = self.Button

            --// Auto Confirm Block belongs directly under Auto Block. Its own
            --// module starts after this one and would otherwise append its
            --// toggle to the end of the section, past the whitelist; the
            --// toggle is made here and that module supplies the behaviour.
            self.ConfirmButton = AICUI.BindFeatureToggle(
                "AutoBlockConfirm",
                "Auto Confirm Block",
                function(Value)
                    if AICFeature.OnAutoBlockConfirmChanged then
                        AICFeature.OnAutoBlockConfirmChanged(Value)
                    end
                end,
                BlockSection
            )

            UIRef.BlockDelaySlider = AICUI.AddSettingSlider(
                BlockSection, "Block Delay (s)", "AUTO_BLOCK_DELAY", true
            )

            --// The pause every leave takes first, right under the delay it
            --// is added to. On by default: nothing the script does on its own
            --// should drop the server the moment a stranger appears.
            AICUI.BindFeatureToggle("RandomLeaveDelay", "Random Leave Delay", nil, BlockSection)
            BlockSection:AddLabel("On: every leave waits a random 2-4 s first, Follower Guard included")

            AICUI.BindFeatureToggle("WhitelistSkipsSafety", "Whitelist Skips Safety", nil, BlockSection)
            BlockSection:AddLabel("On: whitelisted players never make Auto Block or Leave On Danger Group leave, even if blocked")
            BlockSection:AddLabel("Whitelist and Whitelist Skips Safety are shared by every profile")

            self.WhitelistComponent = BlockSection:AddPriority(
                "Block Whitelist",
                CONFIG.BLOCK_WHITELIST or {}
            )
            UIRef.BlockWhitelistComponent = self.WhitelistComponent
            AICUI.ShowUserNames(self.WhitelistComponent)
            CONFIG.BLOCK_WHITELIST = self.WhitelistComponent.Priority

            self.WhitelistBox = BlockSection:AddTextBox{
                Name = "User ID",
                Default = "",
                Callback = function() end,
            }
            UIRef.BlockWhitelistBox = self.WhitelistBox

            BlockSection:AddButton{
                Name = "Add User ID",
                Callback = function()
                    local Id = self:NormalizeUserId(self.WhitelistBox:Get())

                    if not Id then
                        NotifyAction("Whitelist", "Enter a numeric UserId")
                        return
                    end

                    if self:IsWhitelisted(Id) then
                        NotifyAction("Whitelist", Id .. " is already on the list")
                        return
                    end

                    self.WhitelistComponent:Add(Id)
                    CONFIG.BLOCK_WHITELIST = self.WhitelistComponent.Priority
                    self.WhitelistBox:Set("")
                    AICProfile.WriteGlobalStore()
                    NotifyAction("Whitelist", "Added " .. Id)
                    self:RefreshWhitelistPlayerDropdown()
                end,
            }

            BlockSection:AddButton{
                Name = "Refresh Player List",
                Callback = function()
                    self:RefreshWhitelistPlayerDropdown()
                end,
            }

            BlockSection:AddButton{
                Name = "Add Everyone Here",
                Callback = function()
                    local Added = 0

                    for _, OtherPlayer in ipairs(Players:GetPlayers()) do
                        if OtherPlayer ~= Player and not self:IsWhitelisted(OtherPlayer.UserId) then
                            self.WhitelistComponent:Add(tostring(OtherPlayer.UserId))
                            Added += 1
                        end
                    end

                    CONFIG.BLOCK_WHITELIST = self.WhitelistComponent.Priority
                    AICProfile.WriteGlobalStore()
                    NotifyAction("Whitelist", "Added " .. tostring(Added) .. " player(s)")
                    self:RefreshWhitelistPlayerDropdown()
                end,
            }

            BlockSection:AddButton{
                Name = "Clear Whitelist",
                Callback = function()
                    self.WhitelistComponent:SetPriority({})
                    CONFIG.BLOCK_WHITELIST = self.WhitelistComponent.Priority
                    AICProfile.WriteGlobalStore()
                    NotifyAction("Whitelist", "Cleared")
                    self:RefreshWhitelistPlayerDropdown()
                end,
            }

            local OriginalRemove = self.WhitelistComponent.Remove
            local OriginalMoveUp = self.WhitelistComponent.MoveUp
            local OriginalMoveDown = self.WhitelistComponent.MoveDown

            local WhitelistComponent = self.WhitelistComponent

            function WhitelistComponent:Remove(Entry)
                local Changed = OriginalRemove(self, Entry)
                CONFIG.BLOCK_WHITELIST = self.Priority
                AICProfile.WriteGlobalStore()
                AutoBlock:RefreshWhitelistPlayerDropdown()
                return Changed
            end

            function WhitelistComponent:MoveUp(Entry)
                OriginalMoveUp(self, Entry)
                CONFIG.BLOCK_WHITELIST = self.Priority
                AICProfile.WriteGlobalStore()
            end

            function WhitelistComponent:MoveDown(Entry)
                OriginalMoveDown(self, Entry)
                CONFIG.BLOCK_WHITELIST = self.Priority
                AICProfile.WriteGlobalStore()
            end

            self:RefreshWhitelistPlayerDropdown()

            Context.Connect(Players.PlayerAdded, function(OtherPlayer)
                --// The Block Delay is counted from the moment they walk in,
                --// not from the next look at them, so a stranger is never
                --// acted on before the delay because the scan was late.
                if OtherPlayer ~= nil and OtherPlayer.UserId ~= nil then
                    SeenAt(OtherPlayer.UserId)
                end

                self:RefreshWhitelistPlayerDropdown()
            end)

            Context.Connect(Players.PlayerRemoving, function(OtherPlayer)
                --// Leaving and coming back starts the delay over.
                AICFeature.S.IntruderSeenAt[OtherPlayer.UserId] = nil
                AICFeature.S.BlockedSince[OtherPlayer.UserId] = nil

                task.defer(function()
                    self:RefreshWhitelistPlayerDropdown()
                end)
            end)

            -- Compatibility hooks for older combat/profile code.
            AICFeature.TeleportToPlace = function(PlaceId, OtherPlayer)
                return AutoBlock:TeleportToPlace(PlaceId, OtherPlayer)
            end
            AICFeature.LeaveGame = function(Reason, OtherPlayer)
                return AutoBlock:LeaveGame(Reason, OtherPlayer)
            end
            AICFeature.NormalizeUserId = function(Value)
                return AutoBlock:NormalizeUserId(Value)
            end
            AICFeature.IsWhitelisted = function(UserId)
                return AutoBlock:IsWhitelisted(UserId)
            end
            AICFeature.IsSafetyExempt = function(UserId)
                return AutoBlock:IsSafetyExempt(UserId)
            end
            AICFeature.isBlocked = function(UserId)
                return AutoBlock:IsBlocked(UserId)
            end
            AICFeature.IsBlockSettled = function(OtherPlayer)
                return AutoBlock:IsBlockSettled(OtherPlayer)
            end
            AICFeature.promptBlockPlayer = function(OtherPlayer)
                return AutoBlock:PromptBlockPlayer(OtherPlayer)
            end
            AICFeature.IsBlockDelayOver = function(OtherPlayer)
                return AutoBlock:IsBlockDelayOver(OtherPlayer)
            end
            AICFeature.BlockDelayRemaining = function(OtherPlayer)
                return AutoBlock:BlockDelayRemaining(OtherPlayer)
            end
            --// The random pause a leave takes first, for the other features
            --// that leave on their own (FollowerGuard, the Danger Group hop).
            AICFeature.LeaveDelay = function()
                return AutoBlock:LeaveDelay()
            end

            AICUI.RefreshWhitelistPlayerDropdown = function()
                return AutoBlock:RefreshWhitelistPlayerDropdown()
            end
        end

        function AutoBlock:Update()
            --// The player check runs inside the AutoFarming loop, after the
            --// Auto Farm and retreat gates, as it did in AFV2. Running it here
            --// too prompted twice and teleported with Auto Farm switched off.
            --//
            --// What is done here is dropping the stamps of players who are no
            --// longer in the server: a departure the script missed would
            --// otherwise be inherited by the same player coming back, and
            --// the Block Delay would count from the old visit - the leave
            --// then fires the moment they rejoin.
            if next(AICFeature.S.IntruderSeenAt) == nil then
                return
            end

            for UserId in pairs(AICFeature.S.IntruderSeenAt) do
                if Players:GetPlayerByUserId(UserId) == nil then
                    AICFeature.S.IntruderSeenAt[UserId] = nil
                    AICFeature.S.BlockedSince[UserId] = nil
                end
            end
        end

        AutoBlock:CreateUI()
        return AutoBlock
    end,
}
]======],
	["Features/AutoBlockConfirm.lua"] = [======[
-- AutoBlockConfirm presses "Block" in Roblox's Block dialog after Auto Block
-- opens it. Ported from Iambatman's AutoBlockConfirm.
-- Executor only: the dialog lives in CoreGui, which Studio scripts cannot read.
return {
    Name = "AutoBlockConfirm",
    IsFeature = true,
    Dependencies = {"Runtime", "SaveConfig", "Components", "AutoBlock", "GuiClick"},

    Start = function(Context)
        local Services = Context.Services
        local RunService = Services.RunService
        local GuiClick = Context.GuiClick
        local FeatureState = Context.Feature
        local AICFeature = Context.AICFeature
        local NotifyAction = Context.NotifyAction

        --// How long to look for the dialog after a prompt.
        local ARM_SECONDS = 6
        local SCAN_INTERVAL = 0.15
        --// Wait after each click method before checking the block list.
        local VERIFY_SECONDS = 0.7
        local FINAL_VERIFY_SECONDS = 2
        --// A confirm still running after this is taken as stuck, so it
        --// never holds Auto Block's hop back for good.
        local CONFIRM_MAX_SECONDS = 20
        --// Exact match: "Block and report" must never be pressed.
        local CONFIRM_TEXT = "Block"
        --// The dialog title reads "Block <name>?".
        local TITLE_PREFIX = "Block "

        local CloneReference = type(cloneref) == "function" and cloneref or function(Instance)
            return Instance
        end

        local CoreGui = CloneReference(game:GetService("CoreGui"))

        local Available = not RunService:IsStudio()
            and (pcall(function()
                return CoreGui:GetChildren()
            end))

        local Feature = {
            Name = "AutoBlockConfirm",
            IsFeature = true,
            S = {
                ArmToken = 0,
                ArmedPlayer = nil,
                ArmedUntil = 0,
                ArmedAt = 0,
                --// The click method that worked last, tried first next time.
                LastMethod = nil,
            },
        }

        local S = Feature.S

        local function Trim(Text)
            local Trimmed = string.gsub(tostring(Text or ""), "^%s*(.-)%s*$", "%1")
            return Trimmed
        end

        --// Turn on with getgenv().AICBlockConfirmDebug = true before running.
        local function IsDebug()
            local Ok, Env = pcall(function()
                return type(getgenv) == "function" and getgenv()
            end)

            return Ok and type(Env) == "table" and Env.AICBlockConfirmDebug == true
        end

        local function Log(...)
            if IsDebug() then
                print("[AutoBlockConfirm]", ...)
            end
        end

        local function IsBlocked(OtherPlayer)
            return AICFeature.isBlocked ~= nil and AICFeature.isBlocked(OtherPlayer.UserId) == true
        end

        local function WaitForBlocked(OtherPlayer, Seconds)
            local Deadline = os.clock() + Seconds

            while os.clock() < Deadline do
                if IsBlocked(OtherPlayer) then
                    return true
                end

                task.wait(0.1)
            end

            return IsBlocked(OtherPlayer)
        end

        local function GetButtonText(Button)
            if Button:IsA("TextButton") and Trim(Button.Text) ~= "" then
                return Trim(Button.Text)
            end

            for _, Descendant in ipairs(Button:GetDescendants()) do
                if (Descendant:IsA("TextLabel") or Descendant:IsA("TextButton")) and Trim(Descendant.Text) ~= "" then
                    return Trim(Descendant.Text)
                end
            end

            return ""
        end


        local function TitleNamesPlayer(Text, Names)
            if string.sub(Text, 1, #TITLE_PREFIX) ~= TITLE_PREFIX then
                return false
            end

            for _, Name in ipairs(Names) do
                if Name ~= "" and string.find(Text, Name, 1, true) then
                    return true
                end
            end

            return false
        end

        --// Only confirm a dialog whose title names our target, so a dialog
        --// the user opened for someone else is never pressed.
        local function DialogNamesPlayer(Button, OtherPlayer)
            local Names = {OtherPlayer.Name, OtherPlayer.DisplayName}
            local Node = Button.Parent

            while Node and not Node:IsA("LayerCollector") do
                for _, Descendant in ipairs(Node:GetDescendants()) do
                    if Descendant:IsA("TextLabel") and TitleNamesPlayer(Trim(Descendant.Text), Names) then
                        return true
                    end
                end

                Node = Node.Parent
            end

            return false
        end


        local function FindConfirmButton(OtherPlayer)
            local Ok, Descendants = pcall(function()
                return CoreGui:GetDescendants()
            end)

            if not Ok then
                return nil
            end

            for _, Descendant in ipairs(Descendants) do
                if Descendant:IsA("GuiButton")
                    and GuiClick.IsOnScreen(Descendant)
                    and GetButtonText(Descendant) == CONFIRM_TEXT
                    and DialogNamesPlayer(Descendant, OtherPlayer)
                then
                    return Descendant
                end
            end

            return nil
        end

        local function DumpDialogTexts()
            local Ok, Descendants = pcall(function()
                return CoreGui:GetDescendants()
            end)

            if not Ok then
                return
            end

            for _, Descendant in ipairs(Descendants) do
                if (Descendant:IsA("TextLabel") or Descendant:IsA("TextButton"))
                    and string.find(Descendant.Text, "Block", 1, true)
                then
                    print(
                        "[AutoBlockConfirm] dump:",
                        Descendant:GetFullName(),
                        Descendant.ClassName,
                        string.format("%q", Descendant.Text),
                        "onScreen=" .. tostring(GuiClick.IsOnScreen(Descendant))
                    )
                end
            end
        end

        local function Finish(Token)
            if Token == S.ArmToken then
                S.ArmedPlayer = nil
            end
        end

        local function WaitForConfirmButton(Token, OtherPlayer)
            while Token == S.ArmToken and os.clock() < S.ArmedUntil do
                local Button = FindConfirmButton(OtherPlayer)

                if Button then
                    return Button
                end

                task.wait(SCAN_INTERVAL)
            end

            return nil
        end

        local function Run(Token, OtherPlayer)
            local Button = WaitForConfirmButton(Token, OtherPlayer)

            if Token ~= S.ArmToken then
                return
            end

            if not Button then
                Log("Block dialog not found for", OtherPlayer.Name)

                if IsDebug() then
                    DumpDialogTexts()
                end

                Finish(Token)
                return
            end

            for _, Method in ipairs(GuiClick.GetOrderedMethods(S.LastMethod)) do
                if Token ~= S.ArmToken or not GuiClick.IsOnScreen(Button) then
                    break
                end

                local Sent = Method.Click(Button)
                Log(Method.Name, Sent and "sent" or "unavailable")

                if Sent and WaitForBlocked(OtherPlayer, VERIFY_SECONDS) then
                    S.LastMethod = Method.Name
                    Log("Blocked", OtherPlayer.Name, "via", Method.Name)
                    Finish(Token)
                    return
                end
            end

            --// A click may have closed the dialog while the block request is
            --// still in flight.
            if Token == S.ArmToken and not WaitForBlocked(OtherPlayer, FINAL_VERIFY_SECONDS) then
                warn("[AutoBlockConfirm] Could not confirm Block for", OtherPlayer.Name)
                NotifyAction("Auto Confirm Block", "Could not press Block; confirm it yourself.", 5)
            end

            Finish(Token)
        end

        function Feature:IsAvailable()
            return Available
        end

        --// Starts watching for the dialog PromptBlockPlayer just opened for
        --// this player.
        function Feature:Arm(OtherPlayer)
            if not Available or not FeatureState.AutoBlockConfirm.Enabled then
                return
            end

            if not OtherPlayer or not OtherPlayer.Parent or IsBlocked(OtherPlayer) then
                return
            end

            if S.ArmedPlayer == OtherPlayer and os.clock() < S.ArmedUntil then
                return
            end

            S.ArmToken += 1
            S.ArmedPlayer = OtherPlayer
            S.ArmedAt = os.clock()
            S.ArmedUntil = S.ArmedAt + ARM_SECONDS
            task.spawn(Run, S.ArmToken, OtherPlayer)
        end

        function Feature:Disarm()
            S.ArmToken += 1
            S.ArmedPlayer = nil
        end

        --// Whether a confirm for this player is still looking for, pressing
        --// or verifying their dialog.
        function Feature:IsConfirming(OtherPlayer)
            return OtherPlayer ~= nil
                and S.ArmedPlayer == OtherPlayer
                and os.clock() - S.ArmedAt < CONFIRM_MAX_SECONDS
        end

        function Feature:Update()
        end

        --// AutoBlock calls this right after it opens the dialog.
        AICFeature.ConfirmBlockPrompt = function(OtherPlayer)
            return Feature:Arm(OtherPlayer)
        end

        --// AutoBlock waits on this before prompting again or hopping.
        AICFeature.IsConfirmingBlock = function(OtherPlayer)
            return Feature:IsConfirming(OtherPlayer)
        end

        --// AutoBlock makes the toggle itself, directly under Auto Block in its
        --// section: this module starts after it, so a toggle added here would
        --// land past the whitelist instead. It calls this when it changes.
        AICFeature.OnAutoBlockConfirmChanged = function(Enabled)
            if Enabled and not Available then
                NotifyAction("Auto Confirm Block", "Executor only: Roblox's Block dialog cannot be reached here.", 5)
            end

            if not Enabled then
                Feature:Disarm()
            end
        end

        return Feature
    end,
}
]======],
	["Features/AutoFarming.lua"] = [======[
return {
    Name = "AutoFarming",
    IsFeature = true,
    Dependencies = {"Runtime", "Combat", "Targeting", "Navigation", "CombatUtils", "ProfileManager", "Components"},
    Start = function(Context)
        local Runtime = Context.Runtime
        local Services = Context.Services
        local Players = Services.Players
        local Player = Context.Player
        local PlayerGui = Context.PlayerGui
        local Replicated = Services.Replicated
        local StarterGui = Services.StarterGui
        local RunService = Services.RunService
        local PathfindingService = Services.PathfindingService
        local HttpService = Services.HttpService
        local CONFIG = Context.CONFIG
        local FeatureState = Context.Feature
        local AICConfig = Context.AICConfig
        local AICProfile = Context.AICProfile
        local AICCombatUtils = Context.AICCombatUtils
        local AICCombat = Context.AICCombat
        local AICFeature = Context.AICFeature
        local AICUI = Context.AICUI
        local AICDebug = Context.AICDebug
        local UIRef = Context.UIRef
        local UI = Context.UI
        local PatrolState = Context.PatrolState
        local MiningFeature = Context.MiningFeature
        local NotifyAction = Context.NotifyAction

        local Feature = {
            Name = "AutoFarming",
            IsFeature = true,
        }
        function Feature.updateCharacter()
            local Character = Player.Character
            local Humanoid = Character and Character:FindFirstChildOfClass("Humanoid")
            local RootPart = Character and Character:FindFirstChild("HumanoidRootPart")

            Runtime:SetCharacter(Character, Humanoid, RootPart)

            if not Character or not RootPart then
                return
            end

            if not AICFeature.S.FaceAttachment then
                AICFeature.S.FaceAttachment = Instance.new("Attachment")
                AICFeature.S.FaceAttachment.Name = "FaceGoblinAttachment"
                AICFeature.S.FaceAttachment.Parent = RootPart
            end

            local FaceOrientation = Runtime:GetFaceOrientation()
            if not FaceOrientation then
                FaceOrientation = Instance.new("AlignOrientation")
                FaceOrientation.Name = "FaceGoblin"
                FaceOrientation.Mode = Enum.OrientationAlignmentMode.OneAttachment
                FaceOrientation.Attachment0 = AICFeature.S.FaceAttachment
                FaceOrientation.RigidityEnabled = false
                --// Fast enough to track a mob circling at melee range; 25
                --// trailed visibly behind it. FaceGoblin switches to rigid
                --// for large corrections.
                FaceOrientation.Responsiveness = CONFIG.FACE_RESPONSIVENESS
                FaceOrientation.MaxTorque = math.huge
                FaceOrientation.MaxAngularVelocity = math.huge
                if FaceOrientation then
                    FaceOrientation.Enabled = false
                end
                FaceOrientation.Parent = RootPart
                Runtime:SetFaceOrientation(FaceOrientation)
            end

            task.defer(function()
                if not Humanoid then
                    return
                end

                Humanoid:SetStateEnabled(Enum.HumanoidStateType.Ragdoll, false)
                Humanoid:SetStateEnabled(Enum.HumanoidStateType.FallingDown, false)
                Humanoid:SetStateEnabled(Enum.HumanoidStateType.Physics, false)
                Humanoid:SetStateEnabled(Enum.HumanoidStateType.Climbing, false)
            end)
        end

        function Feature:Update(dt)
            -- Keep walkspeed / position UI in sync every frame (was RenderUpdate)
            AICFeature.RenderUpdate(dt)

            --// A departure is under way: the client is being teleported, or it
            --// is already disconnected behind a kick screen while the executor
            --// keeps running. Nothing acts and nothing reports again until the
            --// script reloads in the next server.
            if AICFeature.S.Departing then
                return
            end

            local now = os.clock()
            local Character, Humanoid, RootPart = Runtime:GetCharacter()
            local InputBindableFunction = Runtime:GetInputBindableFunction()
            local FaceOrientation = Runtime:GetFaceOrientation()
            local PlaceConfig = Runtime:GetPlaceConfig()

            --// Auto Block is controlled by the active profile/default config.
            --// Do not gate it by the static PLACE_CONFIG table because profiles can
            --// enable Auto Block even when the current PlaceId has no built-in config.
            --if IsValidPlace(game.PlaceId) then
            --    Enabled = false
            --    updateButton()
            --    return
            --end

            if not Humanoid or not RootPart then
                --// A Boss Route reset waiting for its character still has to
                --// see the respawn, and this is where the frame returns while
                --// there is no character at all.
                if AICFeature.BossRecoverStep then
                    AICFeature.BossRecoverStep(now)
                end

                AICFeature.updateCharacter()
                table.clear(AICCombat.S.ValidMobs)
                AICCombat.S.ClosestTarget = nil
                return
            end

            if Humanoid.Health <= 0 then
                if AICFeature.BossRecoverStep then
                    AICFeature.BossRecoverStep(now)
                end

                AICDebug.ResetDebugWaypoints()
                CONFIG.CURRENT_WAYPOINT_TARGET = 1
                AICFeature.S.WaypointWaitUntil = nil
                if AICFeature.ResetWaypointLoop then AICFeature.ResetWaypointLoop() end
                table.clear(AICCombat.S.ValidMobs)
                AICCombat.S.ClosestTarget = nil
                return
            end

            if now - AICUI.S.LAST_TEXT_UPDATE_TIME >= CONFIG.TEXT_UPDATE_INTERVAL then
                AICUI.S.LAST_TEXT_UPDATE_TIME = now
                AICUI.updatePlayTime()
                AICUI.updateEventCurrency()

                if UIRef.WayPointLabel then
                    UIRef.WayPointLabel:Set("WAYPOINTS:  ".. CONFIG.CURRENT_WAYPOINT_TARGET .. "/" .. (PlaceConfig and #PlaceConfig.WAYPOINTS or 0))
                end
                if UIRef.WalkSpeedLabel then
                    UIRef.WalkSpeedLabel:Set("WALKSPEED:  " .. tostring(math.floor(Humanoid.WalkSpeed + 0.5)))
                end
                if UIRef.DeathLabel then
                    UIRef.DeathLabel:Set("DEATH:  " .. tostring(AICFeature.S.DEATH_COUNT))
                end
            end

            if FeatureState.DebugVisualizer.Enabled then
                AICDebug.UpdateDebugWaypointColors()
            end

            --// Feeds the jump logic. Only counts while the character is actually
            --// trying to move, so standing still on purpose is not read as stuck.
            AICCombatUtils.UpdateStuckTracker(now, Humanoid.MoveDirection.Magnitude > 0.1)

            --// Realtime Mob Validation
            if now - AICCombat.S.LAST_MOB_VALIDATION_TIME >= CONFIG.MOB_VALIDATION_INTERVAL then
                AICCombat.S.LAST_MOB_VALIDATION_TIME = now
                AICCombat.UpdateValidMobs()
            end

            --// Party System is resetting or waiting to Tp to its Leader.
            if AICFeature.IsPartyHolding and AICFeature.IsPartyHolding() then
                AICFeature.SetFarmState("PARTY HOLD")

                if FaceOrientation then
                    FaceOrientation.Enabled = false
                end
                Humanoid.AutoRotate = true
                Humanoid:Move(Vector3.zero)
                return
            end

            if not AICFeature.S.Enabled then
                AICFeature.SetFarmState("AUTO FARM OFF")

                --// The Boss Route runs on its own, with Auto Farm on or off:
                --// it walks its stops, fights, and resets on its own timers.
                if AICFeature.BossStep and AICFeature.BossStep(now) then
                    AICFeature.SetFarmState("BOSS ROUTE")
                    return
                end

                --// Auto Smithing also runs with Auto Farm off: it walks to
                --// the table and crafts, and nothing else moves.
                if AICFeature.SmithingStep and AICFeature.SmithingStep(now) then
                    return
                end

                if FaceOrientation then
                    FaceOrientation.Enabled = false
                end
                Humanoid.AutoRotate = true
                Humanoid:Move(Vector3.zero)
                return
            end

            if not InputBindableFunction then
                InputBindableFunction = PlayerGui:FindFirstChild("InputBindableFunction", true) :: BindableFunction
                Runtime:SetInputBindableFunction(InputBindableFunction)
                return
            end

            local PlayerStats = Player:FindFirstChild("PlayerStats")
            local Sword = Character:FindFirstChild("Sword")

            if not Sword or not Sword:FindFirstChild("MainWeld", true) or not PlayerStats then
                return
            end

            local MainWeld = Sword:FindFirstChild("MainWeld", true)

            if AICFeature.HandleDeadzoneEscape() then
                return
            end

            --// Emergency Retreat
            local RetreatHealthPercent = math.clamp(tonumber(CONFIG.RETREAT_HEALTH_PERCENT) or 40, 0, 80)
            local AutoHealHealthPercent = math.clamp(tonumber(CONFIG.AUTO_HEAL_HEALTH_PERCENT) or 65, 30, 80)
            local RetreatHealthRatio = RetreatHealthPercent / 100
            local AutoHealHealthRatio = AutoHealHealthPercent / 100
            local RecoverHealthPercent = math.min(95, math.max(70, RetreatHealthPercent + 10))
            --// 0 = never, not even on the frame health reaches 0.
            local EmergencyHealth = RetreatHealthRatio > 0 and Humanoid.Health <= Humanoid.MaxHealth * RetreatHealthRatio
            local ShouldHeal      = Humanoid.Health <= Humanoid.MaxHealth * AutoHealHealthRatio

            --// Watches every nearby mob rather than only the current target, and
            --// latches for a short hold so a flickering sound or emitter cannot drop
            --// the dodge partway through.
            local EnemyUsingSkill = AICCombat.UpdateSkillThreat(now)

            --// Still walking the waypoint route. There the route itself is the
            --// way out: low health keeps walking and drinks on the move, and a
            --// skill is dodged and then the route resumes.
            local RouteActive = not FeatureState.AutoFind.Enabled
                and PlaceConfig ~= nil
                and type(PlaceConfig.WAYPOINTS) == "table"
                and (tonumber(CONFIG.CURRENT_WAYPOINT_TARGET) or 1) <= #PlaceConfig.WAYPOINTS

            --// Why we are retreating. A skill dodge ends with the skill; only a
            --// health retreat waits for health to come back. Both used to wait
            --// for health, so one boss skill that dropped us under the recover
            --// line kept the character fleeing long after the skill was over.
            --// The reason only counts while retreating, so one left behind by
            --// a respawn or another path clearing RETREATING cannot stick.
            if EnemyUsingSkill then
                if not (AICCombat.S.RETREATING and AICCombat.S.RetreatReason == "Health") then
                    AICCombat.S.RetreatReason = "Skill"
                end

                AICCombat.S.RETREATING = true
            end

            --// Execute: a target this close to death is finished instead of retreated
            --// from, at any health of our own. An enemy skill still overrides it,
            --// because eating a skill to land one more hit is not a good trade.
            local ExecuteCharge = false
            local ExecutePercent = math.clamp(tonumber(CONFIG.EXECUTE_CHARGE_HP_PERCENT) or 0, 0, 90)

            if ExecutePercent > 0 and not EnemyUsingSkill and AICCombat.S.ClosestTarget then
                local TargetHumanoid = AICCombat.S.ClosestTarget:FindFirstChildOfClass("Humanoid")

                if TargetHumanoid
                    and TargetHumanoid.MaxHealth > 0
                    and TargetHumanoid.Health > 0
                then
                    ExecuteCharge =
                        (TargetHumanoid.Health / TargetHumanoid.MaxHealth) * 100 <= ExecutePercent
                end
            end

            --// Retreat is a health decision only. The old build also entered retreat
            --// whenever WalkSpeed had not been raised yet, but RenderStepped restores
            --// WalkSpeed every frame, so that clause only produced random retreats.
            local Recovered = Humanoid.Health >= Humanoid.MaxHealth * (RecoverHealthPercent / 100)

            if ExecuteCharge then
                AICCombat.S.RETREATING = false
                AICCombat.S.RetreatReason = nil
            elseif EmergencyHealth and not RouteActive then
                AICCombat.S.RETREATING = true
                AICCombat.S.RetreatReason = "Health"
            elseif AICCombat.S.RETREATING
                and not EnemyUsingSkill
                and (AICCombat.S.RetreatReason ~= "Health" or RouteActive or Recovered)
            then
                AICCombat.S.RETREATING = false
                AICCombat.S.RetreatReason = nil

                --// Re-acquire a valid target immediately after healing so the
                --// combat loop does not wait for another target cycle.
                if not AICCombat.IsTargetLockValid(AICCombat.S.ClosestTarget) then
                    AICCombat.S.ClosestTarget = AICCombat.GetClosestGoblin()
                end
            end

            --// The stop's boss is already down: the reset it is owed (or the
            --// step to the next stop) has to happen now, and the reset refills
            --// health anyway. A health retreat owns the frame every frame it
            --// runs, so left alone it could not see the kill at all and kept
            --// healing until the health came back before the route ran again.
            if AICCombat.S.RETREATING
                and AICFeature.BossKillPending
                and AICFeature.BossKillPending()
            then
                AICCombat.S.RETREATING = false
                AICCombat.S.RetreatReason = nil
            end

            if AICCombat.S.RETREATING then
                AICFeature.SetFarmState("RETREAT (" .. tostring(AICCombat.S.RetreatReason or "?") .. ")")

                --// On the route the dodge may land outside the farm zones,
                --// which is where the route runs.
                AICCombatUtils.S.DodgeOffRoute = RouteActive
                local RetreatMoved = AICCombat.RetreatFromGoblins(EnemyUsingSkill)
                AICCombatUtils.S.DodgeOffRoute = false

                --// With no mob close enough to flee from, the retreat stands still
                --// to heal wherever it happens to be. Outside the farm zone that
                --// meant waiting there until health came back, which can be a very
                --// long time without a potion. Heal back inside the zone instead,
                --// once the waypoint route (if any) has been walked.
                local RouteDone = not PlaceConfig
                    or type(PlaceConfig.WAYPOINTS) ~= "table"
                    or #PlaceConfig.WAYPOINTS == 0
                    or (tonumber(CONFIG.CURRENT_WAYPOINT_TARGET) or 1) > #PlaceConfig.WAYPOINTS

                if not RetreatMoved
                    and not EnemyUsingSkill
                    and RouteDone
                    and FeatureState.ReturnToFarmZone.Enabled
                    and not FeatureState.IgnoreFarmZone.Enabled
                    and (not AICCombatUtils.IsInsideFarmArea(RootPart.Position)
                        or AICCombatUtils.IsInsideFarmDeadzone(RootPart.Position))
                then
                    AICFeature.SetFarmState("RETURN TO FARM ZONE")
                    AICFeature.MoveBackToFarmZone()
                end

                --// Something inside attack range is hit while backing away. In a
                --// duel the weapon stays drawn and no potion is drunk at all.
                local InDuel = AICCombat.IsInDuel()
                local FightBackThreat = AICCombat.GetFightBackThreat()

                if (InDuel or (FightBackThreat and not EnemyUsingSkill))
                    and AICFeature.EnsureWeaponDrawnRaw(now, InputBindableFunction, MainWeld)
                then
                    return
                end

                if FightBackThreat and not EnemyUsingSkill then
                    AICCombat.FaceWhileRetreating(FightBackThreat)
                    AICCombat.RetreatAttack(FightBackThreat, now)
                end

                --// Never stop to drink mid-dodge. Getting out of the skill first
                --// is worth more than the heal, and sheathing costs an animation.
                --// A mob in reach used to block the drink as well, which is
                --// exactly when the health was being taken: only the softer
                --// heal waits for the fight now, an emergency drink does not.
                local WantsConsume = (EmergencyHealth or (ShouldHeal and not FightBackThreat))
                    and not EnemyUsingSkill
                    and not InDuel

                if WantsConsume then
                    AICFeature.TryConsumePotion(now, PlayerStats, InputBindableFunction, MainWeld)
                end

                return
            end

            --// Low on the route: no retreat, keep walking and drink on the move.
            if RouteActive
                and (EmergencyHealth or ShouldHeal)
                and AICFeature.TryConsumePotion(now, PlayerStats, InputBindableFunction, MainWeld)
            then
                return
            end

            --// Enemy skill retreat speed is temporary. Once retreating ends,
            --// return to the normal movement cap on the next heartbeat.
            if not EnemyUsingSkill and Humanoid.WalkSpeed > CONFIG.MAXIMUM_WALKSPEED then
                Humanoid.WalkSpeed = CONFIG.MAXIMUM_WALKSPEED
            end

            --// Player Check
            --// Whitelisted players are never blocked, and a server holding only
            --// them is left alone unless Whitelist Skips Safety is off and one of
            --// them is already blocked. Anyone else is blocked individually and then the
            --// server is abandoned; the whole lobby is no longer blocked one by one.
            --// With a party Leader set, Party System deals with intruders instead.
            local PartyHandles = AICFeature.PartyHandlesIntruders and AICFeature.PartyHandlesIntruders()

            if AICFeature.S.BlockEnabled and not PartyHandles then
                local Intruder = nil
                --// A whitelisted player we have blocked. Never prompted, but
                --// with Whitelist Skips Safety off they make us hop all the same.
                local BlockedWhitelisted = nil

                --// Within the Block Delay an intruder is tolerated and the
                --// farm carries on; block and hop only once it has run out.
                --// Every intruder is asked about, so each one's delay starts
                --// when they are first seen, not when the one before is dealt with.
                for _, plr in Players:GetPlayers() do
                    if plr ~= Player then
                        if not AICFeature.IsWhitelisted(plr.UserId) then
                            if AICFeature.IsBlockDelayOver(plr) and not Intruder then
                                Intruder = plr
                            end
                        elseif not BlockedWhitelisted
                            and AICFeature.IsSafetyExempt
                            and not AICFeature.IsSafetyExempt(plr.UserId)
                            and AICFeature.IsBlockDelayOver(plr)
                            and AICFeature.isBlocked(plr.UserId)
                        then
                            BlockedWhitelisted = plr
                        end
                    end
                end

                --// Nobody on the Block Whitelist is ever an intruder, whatever
                --// a stale selection says. Leave Instead Of Block closes the
                --// game, so the list has to win before any leave is decided.
                if Intruder and AICFeature.IsWhitelisted(Intruder.UserId) then
                    Intruder = nil
                end

                local LeavingGame = FeatureState.AutoBlockLeaveOnly.Enabled == true

                if not Intruder and BlockedWhitelisted then
                    if LeavingGame then
                        --// A whitelisted player who is also blocked would
                        --// normally be hopped away; with the leave setting on
                        --// they are ignored instead, so nothing closes the
                        --// game for someone on the list.
                        AICFeature.SetFarmState("AUTO BLOCK  @" .. BlockedWhitelisted.Name .. " IS WHITELISTED, STAYING")
                    else
                        AICFeature.SetFarmState("AUTO BLOCK  HOP FROM @" .. BlockedWhitelisted.Name)
                        AICFeature.TeleportToPlace(nil, BlockedWhitelisted)
                        return
                    end
                end

                if Intruder then
                    --// Leave Instead Of Block: the delay has run out, so
                    --// drop out of the game without touching the block list.
                    --// Not another server: a kick is what a client script can
                    --// do, and it lands back in the Roblox app.
                    if LeavingGame then
                        AICFeature.SetFarmState("AUTO BLOCK  LEAVING GAME FROM @" .. Intruder.Name)
                        AICFeature.LeaveGame(
                            "Auto Block: leaving instead of blocking",
                            Intruder
                        )
                        return
                    end

                    AICFeature.SetFarmState("AUTO BLOCK  @" .. Intruder.Name)

                    if not AICFeature.isBlocked(Intruder.UserId) then
                        AICFeature.promptBlockPlayer(Intruder)
                        return
                    end

                    --// Hop only once the block has gone through, or the hop
                    --// can cut the block request short and land us back
                    --// with them.
                    if not AICFeature.IsBlockSettled(Intruder) then
                        AICFeature.SetFarmState("AUTO BLOCK  CHECKING @" .. Intruder.Name)
                        return
                    end

                    AICFeature.S.BlockCache[Intruder.UserId] = nil
                    AICFeature.TeleportToPlace(nil, Intruder)
                    return
                end
            end

            --// Play Time
            if workspace.DistributedGameTime >= CONFIG.MAX_SERVER_AGE then
                AICFeature.SetFarmState("SERVER TOO OLD, HOPPING")
                AICFeature.TeleportToPlace()
                return
            end

            --// Boss Route: its own stops and timers, above the waypoint route
            --// and the combat below. Every safety check above still ran this
            --// frame, so a Boss Route run keeps Auto Block, the retreat and the
            --// server-age hop.
            if AICFeature.BossStep and AICFeature.BossStep(now) then
                AICFeature.SetFarmState("BOSS ROUTE")
                return
            end

            --// Movement
            --// Waypoint route always has priority over combat/patrol.
            --// Combat target acquisition is completely disabled until the route is finished.
            local HasWaypoints = PlaceConfig and type(PlaceConfig.WAYPOINTS) == "table" and #PlaceConfig.WAYPOINTS > 0
            local WaypointIndex = tonumber(CONFIG.CURRENT_WAYPOINT_TARGET) or 1
            local target = nil
            local HandedOff = false

            --// Holding at a waypoint that has a wait time. Nothing else runs on
            --// the route meanwhile, the same as walking it.
            if AICFeature.S.WaypointWaitUntil then
                if HasWaypoints
                    and not FeatureState.AutoFind.Enabled
                    and now < AICFeature.S.WaypointWaitUntil
                then
                    AICFeature.SetFarmState("WAYPOINT WAIT")

                    if FaceOrientation then
                        FaceOrientation.Enabled = false
                    end
                    Humanoid.AutoRotate = true
                    Humanoid:Move(Vector3.zero)
                    return
                end

                AICFeature.S.WaypointWaitUntil = nil
            end

            if HasWaypoints then
                if WaypointIndex < 1 then
                    WaypointIndex = 1
                    CONFIG.CURRENT_WAYPOINT_TARGET = 1
                end

                local WaypointCount = #PlaceConfig.WAYPOINTS
                local AtLastWaypoint = WaypointIndex > WaypointCount
                target = not AtLastWaypoint and PlaceConfig.WAYPOINTS[WaypointIndex] or nil

                --// Route mode: never let combat target state leak into waypoint movement.
                if not FeatureState.AutoFind.Enabled and target then
                    AICFeature.SetFarmState("ROUTE  #" .. tostring(WaypointIndex))
                    AICCombat.S.ClosestTarget = nil
                    AICCombat.S.TargetPath = nil
                    AICCombat.S.TargetPathMob = nil
                    AICCombat.S.TargetApproachMob = nil
                    AICCombat.S.TargetApproachPosition = nil
                    AICCombat.S.RETREATING = false

                    local WaypointOffset = target - RootPart.Position
                    local WaypointHorizontalDistance = Vector3.new(
                        WaypointOffset.X,
                        0,
                        WaypointOffset.Z
                    ).Magnitude
                    local WaypointVerticalDistance = math.abs(WaypointOffset.Y)
                    local ReachDistance = tonumber(PlaceConfig.REACH_DISTANCE) or 5
                    --// A Jump waypoint sits at a gap's edge: reached only
                    --// right on it, and only on the ground, so the jump
                    --// below always goes off.
                    local IsJumpWaypoint, JumpReached = AICConfig.CheckJumpWaypoint(
                        PlaceConfig, WaypointIndex, WaypointHorizontalDistance
                    )
                    local Reached

                    if IsJumpWaypoint then
                        Reached = JumpReached
                            and Humanoid.FloorMaterial ~= Enum.Material.Air
                            and WaypointVerticalDistance <= math.max(ReachDistance, CONFIG.JUMP_HEIGHT + 2)
                    else
                        Reached = WaypointHorizontalDistance <= ReachDistance
                            and WaypointVerticalDistance <= math.max(ReachDistance, CONFIG.JUMP_HEIGHT + 2)
                    end

                    if Reached then
                        CONFIG.CURRENT_WAYPOINT_TARGET = WaypointIndex + 1

                        if IsJumpWaypoint then
                            AICCombatUtils.DoJump()
                            --// Keep running forward; the next waypoint's
                            --// MoveTo below takes over when there is one.
                            Humanoid:Move(AICCombatUtils.GetFlatLook(RootPart))
                        end

                        --// Waypoint Loop takes over from the first paired
                        --// waypoint, so the route ends there.
                        local LoopEntry = AICFeature.GetWaypointLoopEntry and AICFeature.GetWaypointLoopEntry()

                        if LoopEntry and WaypointIndex >= LoopEntry then
                            CONFIG.CURRENT_WAYPOINT_TARGET = WaypointCount + 1
                            AICFeature.EnterWaypointLoop(WaypointIndex)
                        end

                        AICCombatUtils.S.LAST_STUCK_POSITION = nil
                        AICCombatUtils.S.LAST_STUCK_TIME = now
                        AICDebug.UpdateDebugWaypointColors()

                        --// Waypoint wait: hold here before heading on. The
                        --// check at the top of the route stands still until then.
                        local Wait = tonumber(PlaceConfig.WAYPOINT_WAITS and PlaceConfig.WAYPOINT_WAITS[WaypointIndex]) or 0

                        if Wait > 0 then
                            AICFeature.S.WaypointWaitUntil = now + Wait
                            Humanoid:Move(Vector3.zero)
                            return
                        end

                        WaypointIndex = CONFIG.CURRENT_WAYPOINT_TARGET
                        target = PlaceConfig.WAYPOINTS[WaypointIndex]
                    end

                    if target then
                        if FaceOrientation then
                            FaceOrientation.Enabled = false
                        end
                        Humanoid.AutoRotate = true
                        Humanoid:MoveTo(target)
                        AICCombatUtils.DoJumpIfRouteHole()
                    end

                    if now - AICCombatUtils.S.LAST_STUCK_TIME >= CONFIG.STUCK_CHECK_INTERVAL then
                        AICCombatUtils.S.LAST_STUCK_TIME = now
                        if AICCombatUtils.S.LAST_STUCK_POSITION
                            and (RootPart.Position - AICCombatUtils.S.LAST_STUCK_POSITION).Magnitude < 1
                        then
                            AICCombatUtils.DoJump()
                        else
                            AICCombatUtils.S.LAST_STUCK_POSITION = RootPart.Position
                        end
                    end

                else
                    --// Final waypoint reached: the waypoint loop, when on, decides
                    --// which paired zone to fight in or walks the route to find one.
                    local LoopResult = AICFeature.WaypointLoopStep and AICFeature.WaypointLoopStep(now)
                    local OutsideFarmZone = not AICCombatUtils.IsInsideFarmArea(RootPart.Position)
                    local InFarmDeadzone = AICCombatUtils.IsInsideFarmDeadzone(RootPart.Position)

                    if LoopResult == "move" then
                        AICFeature.SetFarmState("WAYPOINT LOOP")
                        AICFeature.CancelPatrol()
                    elseif AICFeature.RunSideJobs(now) then
                        AICFeature.SetFarmState("MINING / SMITHING")
                        HandedOff = true
                    elseif FeatureState.ReturnToFarmZone.Enabled
                        and not FeatureState.IgnoreFarmZone.Enabled
                        and (OutsideFarmZone or InFarmDeadzone)
                    then
                        AICCombat.S.ClosestTarget = nil
                        AICFeature.CancelPatrol()
                        AICFeature.SetFarmState("RETURN TO FARM ZONE")
                        AICFeature.MoveBackToFarmZone()
                    elseif AICFeature.RunGather(now) then
                        AICFeature.SetFarmState("GATHER")
                        HandedOff = true
                    else
                        if not AICCombat.S.ClosestTarget or not AICCombat.IsTargetLockValid(AICCombat.S.ClosestTarget) then
                            AICCombat.S.ClosestTarget = AICCombat.AcquireCombatTarget(now)
                        else
                            local LockedTarget = AICCombat.AcquireCombatTarget(now)
                            if LockedTarget then
                                AICCombat.S.ClosestTarget = LockedTarget
                            end
                        end

                        if AICCombat.S.ClosestTarget then
                            --// Combat outranks patrolling, so drop whatever the
                            --// patrol was doing rather than leaving a pause or a leg
                            --// chain to resume once the fight is over.
                            AICFeature.CancelPatrol()
                            AICFeature.ApproachTarget(AICCombat.S.ClosestTarget)
                            AICFeature.SetFarmState(AICFeature.DescribeChase())
                        elseif FeatureState.AutoPatrol.Enabled then
                            AICFeature.SetFarmState("PATROL")
                            AICFeature.MoveToPatrol()
                        else
                            AICFeature.SetFarmState("IDLE (NO TARGET)")
                            PatrolState.PatrolPosition = nil
                            AICFeature.S.FarmReturnPosition = nil
                            if FaceOrientation then
                                FaceOrientation.Enabled = false
                            end
                            Humanoid.AutoRotate = true
                            Humanoid:Move(Vector3.zero)
                        end
                    end
                end

            else
                --// No configured waypoints: preserve the original combat/patrol flow.
                local OutsideFarmZone = not AICCombatUtils.IsInsideFarmArea(RootPart.Position)
                local InFarmDeadzone = AICCombatUtils.IsInsideFarmDeadzone(RootPart.Position)

                if AICFeature.RunSideJobs(now) then
                    AICFeature.SetFarmState("MINING / SMITHING")
                    HandedOff = true
                elseif FeatureState.ReturnToFarmZone.Enabled
                    and not FeatureState.IgnoreFarmZone.Enabled
                    and (OutsideFarmZone or InFarmDeadzone)
                then
                    AICCombat.S.ClosestTarget = nil
                    AICFeature.CancelPatrol()
                    AICFeature.SetFarmState("RETURN TO FARM ZONE")
                    AICFeature.MoveBackToFarmZone()
                elseif AICFeature.RunGather(now) then
                    AICFeature.SetFarmState("GATHER")
                    HandedOff = true
                else
                    if not AICCombat.S.ClosestTarget or not AICCombat.IsTargetLockValid(AICCombat.S.ClosestTarget) then
                        AICCombat.S.ClosestTarget = AICCombat.AcquireCombatTarget(now)
                    else
                        local LockedTarget = AICCombat.AcquireCombatTarget(now)
                        if LockedTarget then
                            AICCombat.S.ClosestTarget = LockedTarget
                        end
                    end

                    if AICCombat.S.ClosestTarget then
                        --// Combat outranks patrolling, so drop whatever the patrol
                        --// was doing rather than leaving a pause or a leg chain to
                        --// resume once the fight is over.
                        AICFeature.CancelPatrol()
                        AICFeature.ApproachTarget(AICCombat.S.ClosestTarget)
                        AICFeature.SetFarmState(AICFeature.DescribeChase())
                    elseif FeatureState.AutoPatrol.Enabled then
                        AICFeature.SetFarmState("PATROL")
                        AICFeature.MoveToPatrol()
                    else
                        AICFeature.SetFarmState("IDLE (NO TARGET)")
                        PatrolState.PatrolPosition = nil
                        AICFeature.S.FarmReturnPosition = nil
                        if FaceOrientation then
                            FaceOrientation.Enabled = false
                        end
                        Humanoid.AutoRotate = true
                        Humanoid:Move(Vector3.zero)
                    end
                end
            end

            --// Jump. A waypoint sitting higher is not a reason on its own: a ramp
            --// climbs fine on foot, and hopping up one only costs speed. Probe for
            --// something actually in the way instead. This is the waypoint route
            --// walking, so Jump While Fighting leaves it alone.
            if PlaceConfig and not FeatureState.AutoFind.Enabled and target then
                AICCombatUtils.DoJumpIfObstacle(target)
            end

            --// Swim Recovery. A fight that moved into the water (a player who
            --// jumped in, or us knocked in mid-duel) carries on: SwimChase
            --// already steered this frame, and returning here skipped the
            --// attack below, so the character only ever bobbed at the surface.
            local FightingInWater = AICCombat.S.ClosestTarget
                and AICCombat.IsWaterCombat(AICCombat.S.ClosestTarget)

            if Humanoid:GetState() == Enum.HumanoidStateType.Swimming and not FightingInWater then
                Humanoid.Jump = true
                AICCombatUtils.DoJump()
                return
            end

            if Humanoid.Sit == true then
                Humanoid.Sit = false
                AICCombatUtils.DoJump()
                return
            end

            --// Smithing or mining already moved, and fought anything close,
            --// this frame. Falling through would press Interact there.
            if HandedOff then
                return
            end

            --// Combat
            --// Never enter combat while a configured waypoint route is still active.
            --// Auto Find skips the route entirely, so for it the route never
            --// "finishes"; without this it acquired a target and then only ever
            --// pressed Interact instead of attacking.
            local WaypointRouteFinished = FeatureState.AutoFind.Enabled
                or not HasWaypoints
                or (tonumber(CONFIG.CURRENT_WAYPOINT_TARGET) or 1) > #PlaceConfig.WAYPOINTS

            --// A duel is always fought, Ignore Farm Zone or not: the opponent
            --// may be anywhere, and falling through to Interact never attacks.
            local CanFightTarget = AICCombat.S.ClosestTarget
                and (not FeatureState.IgnoreFarmZone.Enabled or AICCombat.IsInDuel())

            if WaypointRouteFinished
                and (FeatureState.AutoFind.Enabled or not HasWaypoints or CanFightTarget) then
                if AICCombat.S.ClosestTarget then
                    if not AICCombat.IsTargetLockValid(AICCombat.S.ClosestTarget) then
                        AICCombat.S.ClosestTarget = nil
                        return
                    end

                    --// Locked but not in engage range yet. The approach above has
                    --// already issued this frame's MoveTo; stopping here with
                    --// Move(zero) cancelled it, so a target more than
                    --// COMBAT_ENGAGE_MAX_DISTANCE away was never walked to and the
                    --// character just stood still.
                    if not AICCombat.IsCombatTargetValid(AICCombat.S.ClosestTarget) then
                        return
                    end

                    if AICFeature.EnsureWeaponDrawnRaw(now, InputBindableFunction, MainWeld) then
                        return
                    end

                    --// Circling (ApproachTarget): no attacks until NoDamage goes.
                    if AICCombat.HasNoDamage() then
                        return
                    end

                    local MobHumanoid = AICCombat.S.ClosestTarget:FindFirstChildOfClass("Humanoid")
                    local MobRoot     = AICCombat.S.ClosestTarget:FindFirstChild("HumanoidRootPart")

                    if MobHumanoid and MobRoot and MobHumanoid.Health > 0 then
                        AICCombat.PerformCombatActions(AICCombat.S.ClosestTarget, now)
                    else
                        AICCombat.S.ValidMobs[AICCombat.S.ClosestTarget] = nil
                        AICCombat.S.ClosestTarget = nil
                    end
                end
            else
                --// Also quiet for a moment after a script teleport: landing on
                --// a prompt and pressing it again re-fires the door (see
                --// Runtime:MuteInteract).
                if not Runtime:IsInteractMuted()
                    and now - AICFeature.S.LAST_INTERACTION_TIME >= CONFIG.INTERACTION_INTERVAL
                then
                    AICFeature.S.LAST_INTERACTION_TIME = now

                    InputBindableFunction:Invoke(
                        "InteractButton",
                        Enum.UserInputState.Begin
                    )
                end
            end
        end

        AICFeature.updateCharacter = function(...) return Feature.updateCharacter(...) end

        function Feature:CreateUI()
            if UIRef.FeatureSection and UIRef.FeatureSection.AddToggle then
                self.Button = AICUI.CreateFeature("Auto Farm", AICFeature.S.Enabled, function(Value)
                    AICFeature.S.Enabled = Value
                    FeatureState.AutoFarm.Enabled = Value

                    --// The toggle is the moment the macro starts or stops, so
                    --// the Discord report goes now rather than on the next
                    --// heartbeat, which may never come with the farm off.
                    if AICFeature.NotifyAutoFarmChanged then
                        AICFeature.NotifyAutoFarmChanged(Value)
                    end

                    --// Auto Farm off takes Boss Route with it: the route is
                    --// part of a farming session, and left on it ran a boss
                    --// loop with no farm behind it.
                    if not Value
                        and FeatureState.BossRoute
                        and FeatureState.BossRoute.Enabled == true
                    then
                        FeatureState.BossRoute.Enabled = false

                        if AICUI.SetFeatureComponent then
                            AICUI.SetFeatureComponent("BossRoute", false)
                        end

                        if AICFeature.StopBossRoute then
                            AICFeature.StopBossRoute()
                        end
                    end

                    --// Only a real click on the toggle comes through here
                    --// (a profile load and FollowerGuard set the flag
                    --// directly), so this is where FollowerGuard's hold on
                    --// Auto Farm is lifted.
                    if AICFeature.NotifyManualAutoFarmToggle then
                        AICFeature.NotifyManualAutoFarmToggle(Value)
                    end

                    AICProfile.SaveActiveProfile()
                end)
                FeatureState.AutoFarm.Button = self.Button
            end
        end

        Feature:CreateUI()

        --// Called by Init after every feature toggle exists, so the sliders sit
        --// below Reset Stats as they do in AFV2.
        function Feature:BuildLateUI()
            if not UIRef.FeatureSection then
                return
            end

            --// Ranges and defaults come from SaveConfig.Settings.
            UIRef.ExecuteChargeSlider = AICUI.AddSettingSlider(
                UIRef.FeatureSection, "Execute Charge at HP%", "EXECUTE_CHARGE_HP_PERCENT", true
            )
            UIRef.RetreatHealthSlider = AICUI.AddSettingSlider(
                UIRef.FeatureSection, "Retreat At HP%", "RETREAT_HEALTH_PERCENT", true
            )
            UIRef.AutoHealHealthSlider = AICUI.AddSettingSlider(
                UIRef.FeatureSection, "Auto Heal at HP%", "AUTO_HEAL_HEALTH_PERCENT", true
            )
        end

        if UIRef.StatusSection then
            UIRef.FarmStateLabel = UIRef.StatusSection:AddLabel("FARM STATE  --")
            UIRef.PlaceIDLabel = UIRef.StatusSection:AddLabel("PLACE ID       " .. tostring(game.PlaceId))
            UIRef.WalkSpeedLabel = UIRef.StatusSection:AddLabel("WALKSPEED      0")
            UIRef.WayPointLabel = UIRef.StatusSection:AddLabel("WAYPOINTS:  0/" .. ((Runtime:GetPlaceConfig() and #Runtime:GetPlaceConfig().WAYPOINTS) or 0))
            --// Named after the currency the game is handing out this event.
            UIRef.EventCurrencyLabel = UIRef.StatusSection:AddLabel(AICUI.FormatEventCurrency(0))
            UIRef.ServerAgeLabel = UIRef.StatusSection:AddLabel("PLAY TIME      00:00:00")
            UIRef.PositionLabel = UIRef.StatusSection:AddLabel("POSITION       --")
            UIRef.DeathLabel = UIRef.StatusSection:AddLabel("DEATH          0")
            UIRef.ExpLabel = UIRef.StatusSection:AddLabel("EXP            0/0")
        end
        --// The stamina value outlives this run.
        Context.Lifetime.OnEnd(function()
            Context.Lifetime.Disconnect(AICFeature.S.StaminaConnection)
            AICFeature.S.StaminaConnection = nil
        end)

        --// The facing constraint sits in the character, which outlives this
        --// run: left enabled, it would hold the character turned towards the
        --// last target, and the next run makes its own.
        Context.Lifetime.OnEnd(function()
            local FaceOrientation = Runtime:GetFaceOrientation()

            if FaceOrientation then
                FaceOrientation:Destroy()
                Runtime:SetFaceOrientation(nil)
            end

            if AICFeature.S.FaceAttachment then
                AICFeature.S.FaceAttachment:Destroy()
                AICFeature.S.FaceAttachment = nil
            end

            local _, Humanoid = Runtime:GetCharacter()

            if Humanoid and Humanoid.Parent then
                Humanoid.AutoRotate = true
            end
        end)

        return Feature
    end,
}
]======],
	["Features/AutoFarming_Combat.lua"] = [======[
-- AutoFarming_Combat - weapon draw and potion/heal helpers.
-- Split from Features/AutoFarming.lua as part of Step 4b.
return {
    Name = "AutoFarming_Combat",
    Dependencies = {"AutoFarming", "Logger"},

    Start = function(Context)
        local Runtime = Context.Runtime
        local Player = Context.Player
        local Replicated = Context.Services.Replicated
        local AICFeature = Context.AICFeature
        local Logger = Context.Logger
        local CONFIG = Context.CONFIG

        --// Draws the weapon when it is sheathed. True when the draw was just
        --// issued, so the caller should give it this frame.
        local function EnsureWeaponDrawn(now, InputBindableFunction, MainWeld)
            local Sheathed = not AICFeature.S.Equipped
                or (MainWeld.Part1 and MainWeld.Part1.Name == "UpperTorso")

            if not Sheathed or now - AICFeature.S.LAST_EQUIP_TIME < CONFIG.EQUIP_TOGGLE_COOLDOWN then
                return false
            end

            AICFeature.S.Equipped = true
            AICFeature.S.LAST_EQUIP_TIME = now

            InputBindableFunction:Invoke(
                "EquipButton",
                Enum.UserInputState.Begin
            )

            return true
        end

        AICFeature.EnsureWeaponDrawnRaw = EnsureWeaponDrawn

        --// For code outside the farm loop (Auto Mining's defence), which has
        --// no weld or input handle of its own.
        AICFeature.EnsureWeaponDrawn = function(now)
            local Character = Runtime:GetCharacter()
            local Sword = Character and Character:FindFirstChild("Sword")
            local MainWeld = Sword and Sword:FindFirstChild("MainWeld", true)
            local InputBindableFunction = Runtime:GetInputBindableFunction()

            if not MainWeld or not InputBindableFunction then
                Logger.debug(
                    "EnsureWeaponDrawn: missing %s%s",
                    MainWeld and "" or "MainWeld ",
                    InputBindableFunction and "" or "InputBindableFunction"
                )
                return false
            end

            return EnsureWeaponDrawn(now, InputBindableFunction, MainWeld)
        end

        --// Drinks the last used potion when it is off cooldown. The weapon
        --// is sheathed first, which costs a frame: true means this frame was
        --// spent sheathing and the caller should yield it.
        local function TryConsumePotion(now, PlayerStats, InputBindableFunction, MainWeld)
            local UseConsumable = Replicated:FindFirstChild("UseConsumable", true)
            local LastConsumed = PlayerStats and PlayerStats:FindFirstChild("LastConsumed")

            if not UseConsumable
                or not LastConsumed
                or LastConsumed.Value == ""
                or now - AICFeature.S.LAST_CONSUME_TIME < CONFIG.CONSUME_INTERVAL
            then
                return false
            end

            if InputBindableFunction
                and (AICFeature.S.Equipped or (MainWeld.Part1 and MainWeld.Part1.Name ~= "UpperTorso"))
                and now - AICFeature.S.LAST_EQUIP_TIME >= CONFIG.EQUIP_TOGGLE_COOLDOWN
            then
                AICFeature.S.Equipped = false
                AICFeature.S.LAST_EQUIP_TIME = now

                InputBindableFunction:Invoke(
                    "EquipButton",
                    Enum.UserInputState.Begin
                )

                return true
            end

            if not AICFeature.S.Equipped then
                AICFeature.S.LAST_CONSUME_TIME = now
                UseConsumable:InvokeServer(LastConsumed.Value)
            end

            return false
        end

        AICFeature.TryConsumePotion = TryConsumePotion

        --// Drinks from anywhere, for code that never reaches the retreat.
        AICFeature.TryHeal = function(now)
            local Character = Runtime:GetCharacter()
            local Sword = Character and Character:FindFirstChild("Sword")
            local MainWeld = Sword and Sword:FindFirstChild("MainWeld", true)
            local InputBindableFunction = Runtime:GetInputBindableFunction()

            if not Character or not MainWeld or not InputBindableFunction then
                Logger.debug("TryHeal: no character, weld, or input handle")
                return false
            end

            return TryConsumePotion(
                now,
                Player:FindFirstChild("PlayerStats"),
                InputBindableFunction,
                MainWeld
            )
        end

        return { Name = "AutoFarming_Combat" }
    end,
}
