	["Features/RespawnTimers.lua"] = [======[
-- RespawnTimers: reads the game's workspace.RespawnTimers folder.
--
-- Each dead enemy has a Configuration there with the attributes
--   RespawnName     the enemy's name
--   DiedAt          when it died
--   RespawnSeconds  how long it stays dead
-- The Configuration is removed once the enemy has respawned. An enemy counts
-- as dead until then; the timer running out only makes it "due". Both the
-- timer running out and the removal are reported through
-- AICFeature.OnEnemyRespawned(Name).
return {
    Name = "RespawnTimers",
    Dependencies = {"Runtime"},

    Start = function(Context)
        local AICFeature = Context.AICFeature

        local FOLDER_NAME = "RespawnTimers"

        --// [Configuration] = { Name = lowercased RespawnName, FirstSeen, Due }
        local Timers = {}
        local FolderConnections = {}

        local Module = {
            Name = "RespawnTimers",
        }

        local function NotifyRespawned(Name)
            if Name and AICFeature.OnEnemyRespawned then
                AICFeature.OnEnemyRespawned(Name)
            end
        end

        local function TimerName(Config)
            local Name = Config:GetAttribute("RespawnName")
            return type(Name) == "string" and Name ~= "" and string.lower(Name) or nil
        end

        --// DiedAt is written by the server, so which clock it uses is not
        --// known here. Every candidate clock is tried and the one giving a
        --// plausible age is used: at least as old as the timer is known to
        --// be locally, and not far past its respawn time. Failing that the
        --// local age since the timer appeared is used.
        local function GetElapsed(Timer, Config, RespawnSeconds)
            local LocalElapsed = os.clock() - Timer.FirstSeen
            local DiedAt = tonumber(Config:GetAttribute("DiedAt")) or 0

            if DiedAt <= 0 then
                return LocalElapsed
            end

            local Best = nil
            local Clocks = {
                os.clock(),
                workspace:GetServerTimeNow(),
                os.time(),
                workspace.DistributedGameTime,
            }

            for _, Now in ipairs(Clocks) do
                local Elapsed = Now - DiedAt

                if Elapsed >= LocalElapsed - 1
                    and Elapsed <= RespawnSeconds + 5
                    and (not Best or Elapsed < Best)
                then
                    Best = Elapsed
                end
            end

            return Best or LocalElapsed
        end

        --// Seconds until this timer's enemy respawns; 0 once it is due.
        local function GetRemaining(Config, Timer)
            local RespawnSeconds = tonumber(Config:GetAttribute("RespawnSeconds")) or 0
            local Remaining = math.max(0, RespawnSeconds - GetElapsed(Timer, Config, RespawnSeconds))

            if Remaining <= 0 and not Timer.Due then
                Timer.Due = true
                NotifyRespawned(TimerName(Config))
            end

            return Remaining
        end

        local function Track(Config)
            if Config:IsA("Configuration") and not Timers[Config] then
                Timers[Config] = { FirstSeen = os.clock(), Due = false }
            end
        end

        local function Untrack(Config)
            local Timer = Timers[Config]

            if not Timer then
                return
            end

            Timers[Config] = nil

            --// Removal is the real respawn, so it is always reported, even
            --// when the timer already ran out.
            NotifyRespawned(TimerName(Config))
        end

        local function WatchFolder(Folder)
            for _, Connection in ipairs(FolderConnections) do
                Connection:Disconnect()
            end

            table.clear(FolderConnections)
            table.clear(Timers)

            for _, Child in ipairs(Folder:GetChildren()) do
                Track(Child)
            end

            table.insert(FolderConnections, Folder.ChildAdded:Connect(Track))
            table.insert(FolderConnections, Folder.ChildRemoved:Connect(Untrack))
        end

        --// Respawn state of an enemy by name (any case):
        --//   Pending    how many of them have a timer, i.e. are not back yet
        --//   Remaining  seconds until the first of those respawns (0 once its
        --//              timer has run out but it has not appeared), or nil
        function AICFeature.GetRespawnState(EnemyName)
            local Wanted = string.lower(tostring(EnemyName))
            local Pending, Soonest = 0, nil

            for Config, Timer in pairs(Timers) do
                if Config.Parent and TimerName(Config) == Wanted then
                    Pending += 1
                    Soonest = math.min(Soonest or math.huge, GetRemaining(Config, Timer))
                end
            end

            return Pending, Soonest
        end

        local Existing = workspace:FindFirstChild(FOLDER_NAME)

        if Existing then
            WatchFolder(Existing)
        end

        Context.Connect(workspace.ChildAdded, function(Child)
            if Child.Name == FOLDER_NAME then
                WatchFolder(Child)
            end
        end)

        --// The enemy folders outlive this run.
        Context.Lifetime.OnEnd(function()
            Context.Lifetime.Disconnect(FolderConnections)
        end)

        return Module
    end,
}
]======],
	["Features/ReturnToFarmZone.lua"] = [======[
return {
    Name = "ReturnToFarmZone",
    IsFeature = true,
    Dependencies = {"Runtime", "CombatUtils", "ProfileManager"},
    Start = function(Context)
        local Runtime = Context.Runtime
        local Services = Context.Services
        local Players = Services.Players
        local Player = Context.Player
        local PlayerGui = Context.PlayerGui
        local Replicated = Services.Replicated
        local StarterGui = Services.StarterGui
        local RunService = Services.RunService
        local PathfindingService = Services.PathfindingService
        local HttpService = Services.HttpService
        local CONFIG = Context.CONFIG
        local FeatureState = Context.Feature
        local AICConfig = Context.AICConfig
        local AICProfile = Context.AICProfile
        local AICCombatUtils = Context.AICCombatUtils
        local AICCombat = Context.AICCombat
        local AICFeature = Context.AICFeature
        local AICUI = Context.AICUI
        local AICDebug = Context.AICDebug
        local UIRef = Context.UIRef
        local UI = Context.UI
        local PatrolState = Context.PatrolState
        local MiningFeature = Context.MiningFeature
        local NotifyAction = Context.NotifyAction

        local Feature = {
            Name = "ReturnToFarmZone",
            IsFeature = true,
        }
        function Feature.GetFarmReturnPosition()
            local Character, Humanoid, RootPart = Runtime:GetCharacter()
        local PlaceConfig = Runtime:GetPlaceConfig()
            if not RootPart or FeatureState.IgnoreFarmZone.Enabled or not PlaceConfig then
                return nil
            end
        
            local now = os.clock()
        
            if AICFeature.S.FarmReturnPosition
                and now - AICFeature.S.LastFarmReturnCalculateTime < CONFIG.FARM_RETURN_RECALCULATE_INTERVAL
            then
                return AICFeature.S.FarmReturnPosition
            end
        
            AICFeature.S.LastFarmReturnCalculateTime = now
            local PreviousReturnPosition = AICFeature.S.FarmReturnPosition
            AICFeature.S.FarmReturnPosition = nil
        
            local ActiveZone = AICCombatUtils.GetActiveFarmZone()
            local FarmCenter = (ActiveZone and ActiveZone.Center) or RootPart.Position
            local Origin = RootPart.Position
            local Candidates = {}
        
            --// Return to a randomized point 10-20 studs away from the farm center.
            --// This prevents the character from repeatedly standing on the same spot.
            for Index = 1, CONFIG.FARM_RETURN_CANDIDATES do
                local Angle = math.random() * math.pi * 2
                local Radius = CONFIG.FARM_RETURN_RADIUS_MIN
                    + math.random() * (CONFIG.FARM_RETURN_RADIUS_MAX - CONFIG.FARM_RETURN_RADIUS_MIN)
                local Offset = Vector3.new(
                    math.cos(Angle) * Radius,
                    0,
                    math.sin(Angle) * Radius
                )
        
                local Candidate = AICCombatUtils.GetPatrolGroundPosition(FarmCenter + Offset)
        
                if Candidate
                    and AICCombatUtils.IsInsideFarmArea(Candidate)
                    and not AICCombatUtils.IsInsideFarmDeadzone(Candidate)
                then
                    table.insert(Candidates, Candidate)
                end
            end
        
            if #Candidates > 0 then
                --// Prefer a point that is not almost identical to the previous return spot.
                local Filtered = {}
                for _, Candidate in ipairs(Candidates) do
                    if not PreviousReturnPosition
                        or (Candidate - PreviousReturnPosition).Magnitude >= CONFIG.FARM_RETURN_MIN_SPREAD
                    then
                        table.insert(Filtered, Candidate)
                    end
                end
        
                if #Filtered > 0 then
                    Candidates = Filtered
                end
        
                AICFeature.S.FarmReturnPosition = Candidates[math.random(1, #Candidates)]
                return AICFeature.S.FarmReturnPosition
            end
        
            return nil
        end
        function Feature.MoveBackToFarmZone()
            local Character, Humanoid, RootPart = Runtime:GetCharacter()
        local FaceOrientation = Runtime:GetFaceOrientation()
        local PlaceConfig = Runtime:GetPlaceConfig()
            if not FeatureState.ReturnToFarmZone.Enabled or not RootPart or not Humanoid then
                AICFeature.S.FarmReturnPosition = nil
                return false
            end
        
            if FeatureState.IgnoreFarmZone.Enabled then
                AICFeature.S.FarmReturnPosition = nil
                return false
            end
        
            local ActiveZone = AICCombatUtils.GetActiveFarmZone()
            local FarmCenter = (ActiveZone and ActiveZone.Center) or RootPart.Position
            local CenterOffset = RootPart.Position - FarmCenter
            local CenterDistance = Vector3.new(CenterOffset.X, 0, CenterOffset.Z).Magnitude
        
            --// Stop returning once we are close enough to the farm centre.
            if CenterDistance <= CONFIG.FARM_RETURN_CENTER_DISTANCE then
                AICFeature.S.FarmReturnPosition = nil
                AICFeature.S.LastFarmReturnCalculateTime = 0
                Humanoid.AutoRotate = true
                Humanoid:Move(Vector3.zero)
                return false
            end
        
            --// No sampled point inside the zone passed its checks. Heading for the
            --// centre is still better than the old answer, which was to stand
            --// outside the zone doing nothing.
            local Position = AICFeature.GetFarmReturnPosition() or FarmCenter
        
            local Offset = Position - RootPart.Position
            local Distance = Vector3.new(Offset.X, 0, Offset.Z).Magnitude
        
            if Distance <= CONFIG.FARM_RETURN_ARRIVAL_DISTANCE then
                AICFeature.S.FarmReturnPosition = nil
                AICFeature.S.LastFarmReturnCalculateTime = 0
                return false
            end
        
            --// The facing constraint is nil until AutoFarming makes one and again
            --// for a frame after every respawn, so setting it is optional.
            if FaceOrientation then
                FaceOrientation.Enabled = false
            end
        
            --// Straight line first, since it is free. If something is in the way,
            --// route around it rather than pressing into the obstacle.
            if AICCombatUtils.IsPathClear(Position) then
                Humanoid.AutoRotate = true
                Humanoid:MoveTo(Position)
                return true
            end
        
            if CenterDistance <= CONFIG.FARM_RETURN_PATH_DISTANCE
                and AICCombat.MoveAlongPathTo(Position, true)
            then
                return true
            end
        
            --// Pathfinding refused as well. Keep walking at the target anyway; the
            --// stuck check and the jump will usually free the character.
            Humanoid.AutoRotate = true
            Humanoid:MoveTo(Position)
            return true
        end

        AICFeature.GetFarmReturnPosition = function(...) return Feature.GetFarmReturnPosition(...) end
        AICFeature.MoveBackToFarmZone = function(...) return Feature.MoveBackToFarmZone(...) end

        function Feature:SetEnabled(Value)
            self.Enabled = Value == true
            if FeatureState.ReturnToFarmZone then
                FeatureState.ReturnToFarmZone.Enabled = self.Enabled
            end
        end

        function Feature:CreateUI()
            if UIRef.FeatureSection and UIRef.FeatureSection.AddToggle then
                --// Defaults to on. Without this the toggle drew as off while the
                --// return logic was actually running.
                self.Enabled = FeatureState.ReturnToFarmZone.Enabled == true
                self.Button = UIRef.FeatureSection:AddToggle{
                    Name = "Return To Farm Zone",
                    Default = self.Enabled,
                    Callback = function(Value)
                        self:SetEnabled(Value)

                        AICFeature.S.FarmReturnPosition = nil
                        AICFeature.S.LastFarmReturnCalculateTime = 0
                        AICProfile.SaveActiveProfile()
                    end,
                }
                FeatureState.ReturnToFarmZone.Button = self.Button
            end
        end

        function Feature:Update()
        end

        Feature:CreateUI()

        return Feature
    end,
}
]======],
	["Features/SafeBoosterReset.lua"] = [======[
return {
	Name = "SafeBoosterReset",
	IsFeature = true,
	Dependencies = {"Runtime", "SaveConfig", "ProfileManager", "Components"},
	Start = function(Context)
		local Runtime = Context.Runtime
		local Services = Context.Services
		local Player = Context.Player
		local Replicated = Services.Replicated
		local FeatureState = Context.Feature
		local AICFeature = Context.AICFeature
		local AICUI = Context.AICUI
		local UIRef = Context.UIRef
		local NotifyAction = Context.NotifyAction

		local Feature = {
			Name = "SafeBoosterReset",
			IsFeature = true,
		}

		--// The connection stays alive for the whole session, so the toggle
		--// has to be read at fire time, not here.
		local function SafeBoosterReset(Boost)
			if not FeatureState.SafeBoosterReset.Enabled then
				return
			end

			if Boost.Value <= 0 then
				NotifyAction("SAFE BOOSTER RESET", "Boost expired, no action.")
				return
			end

			local DamageTags = Replicated:FindFirstChild("PlayerDamageTags")
			if DamageTags and DamageTags:FindFirstChild(Player.Name .. "MobDamaged") then
				return
			end

			local _, Humanoid = Runtime:GetCharacter()

			if Humanoid then
				Humanoid.Health = 0
			end
		end

		function Feature.SafeBoosterReset()
			task.spawn(function()
				local PlayerStats = Player:WaitForChild("PlayerStats")
				local ExpBoost = PlayerStats:FindFirstChild("Boost")

				if ExpBoost then
					table.insert(
						AICFeature.S.BoosterConnections,
						ExpBoost:GetPropertyChangedSignal("Value"):Connect(function()
							SafeBoosterReset(ExpBoost)
						end)
					)
				end
			end)
		end

		AICFeature.SafeBoosterReset = Feature.SafeBoosterReset

		function Feature:Update()
		end

		--// The value is saved through Feature.SafeBoosterReset.Enabled like
		--// every other toggle and restored on load by updateFeatureButtons.
		AICUI.BindFeatureToggle("SafeBoosterReset", "Safe Booster Reset", nil, UIRef.BoosterSection)
		Feature.SafeBoosterReset()

		return Feature
	end,
}
