	["Features/ServerHop.lua"] = [======[
-- ServerHop owns moving between servers and watching who is in this one,
-- ported from Iambatman:
--   Rejoin, Server Hop (a random public server with a free slot) and joining
--   a server by Job ID; reading the public server list for the browser;
--   Leave On Danger Group: when a member of any group in DANGER_GROUP_IDS
--   who is not on the Danger Whitelist (nor, with Whitelist Skips Safety on,
--   the Auto Block whitelist) is in the server, it blocks them and then
--   joins another public server (toggle, groups and whitelist are global,
--   not per profile); Join Alerts for players off the Auto Block whitelist;
--   and the Player Log of who joined and left.
-- ServerUI draws all of it on the Server tab.
return {
    Name = "ServerHop",
    IsFeature = true,
    Dependencies = {"Runtime", "SaveConfig", "AutoBlock"},

    Start = function(Context)
        local Services = Context.Services
        local Players = Services.Players
        local HttpService = Services.HttpService
        local TeleportService = game:GetService("TeleportService")
        local Player = Context.Player
        local Feature = Context.Feature
        local CONFIG = Context.CONFIG
        local AICFeature = Context.AICFeature
        local NotifyAction = Context.NotifyAction

        local DANGER_HOP_MAX_ATTEMPTS = 3
        local DANGER_HOP_RETRY_DELAY = 3
        --// How long a danger hop waits for the block to take before leaving
        --// anyway (time to press Block by hand when Auto Confirm Block is
        --// off), and how often it looks.
        local DANGER_BLOCK_WAIT = 10
        local DANGER_BLOCK_POLL = 0.25
        local GROUP_CHECK_MAX_ATTEMPTS = 3
        local GROUP_CHECK_RETRY_DELAY = 5
        --// Players are checked again this often, so a player taken off the
        --// whitelist, or a toggle switched on, is acted on.
        local SCAN_INTERVAL = 2
        --// Pages of the public server list a hop reads before giving up.
        local HOP_MAX_PAGES = 4
        local LOG_LIMIT = 100
        --// The same notice is not shown again within this.
        local NOTICE_COOLDOWN = 8
        --// One "could not check" notice at most this often, however many
        --// players' group checks fail (the details go to the console).
        local GROUP_CHECK_NOTICE_COOLDOWN = 60
        --// Join alerts arriving within this are shown as one notice.
        local JOIN_ALERT_BATCH_SECONDS = 1.5
        --// Names listed in one notice; the rest are counted.
        local JOIN_ALERT_MAX_NAMES = 4
        --// A player who leaves and comes back within this is not announced
        --// again.
        local JOIN_ALERT_REPEAT_SECONDS = 120
        local SERVER_LIST_URL = "https://games.roblox.com/v1/games/%d/servers/Public?sortOrder=Asc&limit=100"

        local ServerHop = {
            Name = "ServerHop",
            IsFeature = true,
            S = {
                Teleporting = false,
                --// A hop is reading the server list.
                Finding = false,
                Status = "IDLE",
                --// Notice key -> os.clock() it was last shown.
                NoticeAt = {},
                --// Join alerts waiting to be shown together.
                AlertQueue = {},
                AlertFlushScheduled = false,
                --// UserId -> the danger group ID they were found in.
                DangerUsers = {},
                --// Bumped when the group list changes, so a check that was
                --// asking about the old list is dropped.
                GroupListVersion = 0,
                CheckedUsers = {},
                CheckInFlight = {},
                CheckFailures = {},
                DangerHopStarted = false,
                DangerHopAttempts = 0,
                --// UserId -> os.clock() of their last join alert.
                AlertSeen = {},
                Log = {},
                --// Bumped on every log change, so the UI redraws only then.
                LogVersion = 0,
                Online = {},
                LastScan = 0,
                --// Set by the first Update, once the profile is loaded.
                Ready = false,
            },
        }

        local S = ServerHop.S

        --// The Auto Block whitelist, which Join Alerts goes by.
        local function IsWhitelisted(OtherPlayer)
            return AICFeature.IsWhitelisted ~= nil and AICFeature.IsWhitelisted(OtherPlayer.UserId) == true
        end

        --// Leave On Danger Group's own whitelist (CONFIG.DANGER_WHITELIST),
        --// global and separate from the Auto Block one.
        function ServerHop:IsDangerWhitelisted(UserId)
            local Id = tostring(UserId or ""):gsub("%s+", "")
            return table.find(CONFIG.DANGER_WHITELIST or {}, Id) ~= nil
        end

        local function SetStatus(Text)
            S.Status = Text
        end

        --// Every notice goes through here, so a repeat within Cooldown
        --// (NOTICE_COOLDOWN by default) is dropped. Key defaults to the
        --// title and message.
        local function Notify(Title, Message, Duration, Key, Cooldown)
            Key = Key or (Title .. "|" .. Message)

            local now = os.clock()

            if now - (S.NoticeAt[Key] or -math.huge) < (Cooldown or NOTICE_COOLDOWN) then
                return
            end

            S.NoticeAt[Key] = now
            NotifyAction(Title, Message, Duration)
        end

        function ServerHop:GetStatus()
            return S.Status
        end

        function ServerHop:IsDangerPlayer(OtherPlayer)
            return S.DangerUsers[tostring(OtherPlayer.UserId)] ~= nil
        end

        --// CONFIG.DANGER_GROUP_IDS as numbers.
        local function GetDangerGroupIds()
            local Ids = {}

            for _, Text in ipairs(CONFIG.DANGER_GROUP_IDS or {}) do
                local Id = tonumber(Text)

                if Id then
                    table.insert(Ids, Id)
                end
            end

            return Ids
        end

        --// The group list changed: everyone is asked again about the new one.
        function ServerHop:ResetGroupChecks()
            S.GroupListVersion += 1
            table.clear(S.DangerUsers)
            table.clear(S.CheckedUsers)
            table.clear(S.CheckInFlight)
            table.clear(S.CheckFailures)
            S.LastScan = 0
            S.LogVersion += 1
        end

        ------------------------------------------------------------------------
        --// Player Log
        ------------------------------------------------------------------------

        local function RecordLog(OtherPlayer, Event)
            if not OtherPlayer or OtherPlayer == Player then
                return
            end

            table.insert(S.Log, {
                Time = os.date("%H:%M:%S"),
                Event = Event,
                Name = OtherPlayer.Name,
                UserId = tostring(OtherPlayer.UserId),
            })

            while #S.Log > LOG_LIMIT do
                table.remove(S.Log, 1)
            end

            S.LogVersion += 1
        end

        --// Newest first.
        function ServerHop:GetLog()
            local Result = {}

            for Index = #S.Log, 1, -1 do
                table.insert(Result, S.Log[Index])
            end

            return Result
        end

        function ServerHop:ClearLog()
            table.clear(S.Log)
            S.LogVersion += 1
        end

        ------------------------------------------------------------------------
        --// Teleports
        ------------------------------------------------------------------------

        local function TeleportToInstance(JobId, Status, OnFailed)
            if S.Teleporting then
                return false
            end

            S.Teleporting = true
            SetStatus(Status)

            task.spawn(function()
                --// The Webhook report goes while the client is still here.
                if AICFeature.ReportBeforeLeave then
                    AICFeature.ReportBeforeLeave()
                end

                local Success, Error = pcall(function()
                    TeleportService:TeleportToPlaceInstance(game.PlaceId, JobId, Player)
                end)

                if not Success then
                    S.Teleporting = false
                    SetStatus("TELEPORT FAILED")
                    Notify("SERVER", tostring(Error), 6)

                    if OnFailed then
                        OnFailed(tostring(Error))
                    end
                end
            end)

            return true
        end

        function ServerHop:Rejoin()
            local JobId = tostring(game.JobId or "")

            if JobId == "" then
                Notify("SERVER", "This server has no Job ID, so Rejoin is unavailable", 4)
                return false
            end

            Notify("SERVER", "Rejoining this server...")
            return TeleportToInstance(JobId, "REJOINING")
        end

        function ServerHop:Join(JobId)
            JobId = tostring(JobId or ""):gsub("%s+", "")

            if JobId == "" or JobId == game.JobId then
                Notify("SERVER", "That Job ID is empty or is this server", 4)
                return false
            end

            return TeleportToInstance(JobId, "JOINING SERVER")
        end

        --// One page of public servers with a free slot, other than this one.
        --// Returns the servers and the next page's cursor, or nil and an error.
        function ServerHop:ReadPublicServers(Cursor)
            local Url = string.format(SERVER_LIST_URL, game.PlaceId)

            if type(Cursor) == "string" and Cursor ~= "" then
                Url ..= "&cursor=" .. HttpService:UrlEncode(Cursor)
            end

            local Success, Body = pcall(function()
                return game:HttpGet(Url)
            end)

            if not Success then
                return nil, nil, Body
            end

            local Decoded, Payload = pcall(function()
                return HttpService:JSONDecode(Body)
            end)

            if not Decoded or type(Payload) ~= "table" or type(Payload.data) ~= "table" then
                return nil, nil, "The public server list response was invalid"
            end

            local Servers = {}

            for _, Server in ipairs(Payload.data) do
                local Playing = tonumber(Server.playing)
                local MaxPlayers = tonumber(Server.maxPlayers)

                if type(Server.id) == "string" and Server.id ~= game.JobId
                    and Playing and MaxPlayers and Playing < MaxPlayers
                then
                    table.insert(Servers, {
                        Id = Server.id,
                        Playing = Playing,
                        MaxPlayers = MaxPlayers,
                        Ping = tonumber(Server.ping),
                        FPS = tonumber(Server.fps),
                    })
                end
            end

            local NextCursor = type(Payload.nextPageCursor) == "string" and Payload.nextPageCursor or nil
            return Servers, NextCursor
        end

        --// The Job ID of a random public server with a free slot other than
        --// this one, or nil and why (nil error: there is none). Yields.
        local function FindOtherServer()
            local Cursor

            for _ = 1, HOP_MAX_PAGES do
                local Servers, NextCursor, ReadError = ServerHop:ReadPublicServers(Cursor)

                if not Servers then
                    return nil, ReadError
                end

                if #Servers > 0 then
                    return Servers[math.random(1, #Servers)].Id
                end

                Cursor = NextCursor

                if not Cursor then
                    break
                end
            end

            return nil, nil
        end

        --// Finds another public server and joins it. OnFailed is called when
        --// a hop was started but could not be carried out -- the server list
        --// could not be read, no other server had a free slot, or the
        --// teleport was refused -- so a caller that has to get out of this
        --// server can fall back to stopping the farm.
        --// Returns false when another hop is already on its way: that is
        --// still leaving, for somebody else's reason.
        function ServerHop:Hop(OnFailed)
            --// A second press while one is finding or teleporting does nothing.
            if S.Teleporting or S.Finding then
                return false
            end

            S.Finding = true
            SetStatus("FINDING SERVER")

            task.spawn(function()
                local Target, Error = FindOtherServer()

                S.Finding = false

                if Target then
                    Notify("SERVER HOP", "Joining another public server...")
                    TeleportToInstance(Target, "HOPPING", OnFailed)
                elseif Error then
                    SetStatus("HOP FAILED")
                    Notify("SERVER HOP", "Could not read the server list: " .. tostring(Error), 6)

                    if OnFailed then
                        OnFailed(tostring(Error))
                    end
                else
                    SetStatus("NO OTHER SERVER")
                    Notify("SERVER HOP", "No other public server with a free slot was found", 6)

                    if OnFailed then
                        OnFailed("no other server with a free slot")
                    end
                end
            end)

            return true
        end

        ------------------------------------------------------------------------
        --// Leave On Danger Group
        ------------------------------------------------------------------------

        --// Whitelist Skips Safety also exempts the Auto Block whitelist.
        local function IsSafetyExempt(OtherPlayer)
            return AICFeature.IsSafetyExempt ~= nil and AICFeature.IsSafetyExempt(OtherPlayer.UserId) == true
        end

        local function ShouldLeaveFor(OtherPlayer)
            return Feature.DangerGroupHop.Enabled
                and OtherPlayer.Parent == Players
                and ServerHop:IsDangerPlayer(OtherPlayer)
                and not ServerHop:IsDangerWhitelisted(OtherPlayer.UserId)
                and not IsSafetyExempt(OtherPlayer)
        end

        local function IsBlocked(OtherPlayer)
            return AICFeature.isBlocked ~= nil and AICFeature.isBlocked(OtherPlayer.UserId) == true
        end

        --// Auto Block's check that the block has gone through, not just
        --// shown up on the list.
        local function IsBlockSettled(OtherPlayer)
            if AICFeature.IsBlockSettled then
                return AICFeature.IsBlockSettled(OtherPlayer) == true
            end

            return IsBlocked(OtherPlayer)
        end

        --// Blocks the player through Auto Block's prompt (Auto Confirm Block
        --// presses it when on) and waits, at most DANGER_BLOCK_WAIT, for the
        --// block to go through. Roblox does not put us in a server with
        --// someone we blocked, so without this a hop can land straight back
        --// here. True when they are blocked. Yields.
        local function BlockBeforeLeaving(OtherPlayer)
            if not IsBlocked(OtherPlayer) then
                if not AICFeature.promptBlockPlayer then
                    return false
                end

                SetStatus("BLOCKING @" .. OtherPlayer.Name .. " (DANGER GROUP)")
                AICFeature.promptBlockPlayer(OtherPlayer)
            end

            local Deadline = os.clock() + DANGER_BLOCK_WAIT

            while os.clock() < Deadline and OtherPlayer.Parent == Players do
                if IsBlockSettled(OtherPlayer) then
                    return true
                end

                --// Taken off the list again (the block failed): ask again.
                if not IsBlocked(OtherPlayer) and AICFeature.promptBlockPlayer then
                    AICFeature.promptBlockPlayer(OtherPlayer)
                end

                task.wait(DANGER_BLOCK_POLL)
            end

            return IsBlockSettled(OtherPlayer)
        end

        --// Blocks the danger player first, then joins another public server
        --// from the list, so it cannot be this one. Without a readable list
        --// it lets Roblox pick a server instead.
        local function LeaveFor(OtherPlayer)
            if S.DangerHopStarted
                or S.DangerHopAttempts >= DANGER_HOP_MAX_ATTEMPTS
                or not ShouldLeaveFor(OtherPlayer)
            then
                return
            end

            S.DangerHopStarted = true
            S.DangerHopAttempts += 1
            S.Teleporting = true

            if S.DangerHopAttempts == 1 then
                local GroupId = S.DangerUsers[tostring(OtherPlayer.UserId)]
                Notify("DANGER", string.format("@%s is in group %s. Blocking, then leaving this server.", OtherPlayer.Name, tostring(GroupId)), 7)
            end

            task.spawn(function()
                --// Nothing leaves the instant a Danger Group member is
                --// spotted: the same random 2-4 s pause every other leave
                --// takes runs first (Random Leave Delay), and what was
                --// decided before it is looked at again after it.
                local Wait = AICFeature.LeaveDelay and AICFeature.LeaveDelay() or 0

                if Wait > 0 then
                    task.wait(Wait)

                    if OtherPlayer.Parent ~= Players or not ShouldLeaveFor(OtherPlayer) then
                        S.DangerHopAttempts = math.max(S.DangerHopAttempts - 1, 0)
                        S.DangerHopStarted = false
                        S.Teleporting = false
                        SetStatus("IDLE")
                        return
                    end
                end

                local Blocked = BlockBeforeLeaving(OtherPlayer)

                --// They left while we waited: nothing to leave for any more.
                --// Not a failed hop, so it does not use up an attempt.
                if OtherPlayer.Parent ~= Players then
                    S.DangerHopAttempts = math.max(S.DangerHopAttempts - 1, 0)
                    S.DangerHopStarted = false
                    S.Teleporting = false
                    SetStatus("IDLE")
                    return
                end

                if not Blocked then
                    Notify("DANGER", "@" .. OtherPlayer.Name .. " is not blocked yet; leaving anyway", 6)
                end

                SetStatus("LEAVING (DANGER GROUP)")

                --// Report before the hop, like every other leave, naming the
                --// player whose group made us leave.
                if AICFeature.ReportBeforeLeave then
                    AICFeature.ReportBeforeLeave(OtherPlayer)
                end

                local Target = FindOtherServer()

                local Success, Error = pcall(function()
                    if Target then
                        TeleportService:TeleportToPlaceInstance(game.PlaceId, Target, Player)
                    else
                        TeleportService:Teleport(game.PlaceId, Player)
                    end
                end)

                if Success then
                    return
                end

                warn("[ServerHop] Danger group hop failed:", Error)
                S.DangerHopStarted = false
                S.Teleporting = false

                if S.DangerHopAttempts < DANGER_HOP_MAX_ATTEMPTS then
                    task.delay(DANGER_HOP_RETRY_DELAY, LeaveFor, OtherPlayer)
                else
                    SetStatus("TELEPORT FAILED")
                    Notify("DANGER", "Teleport failed after " .. DANGER_HOP_MAX_ATTEMPTS .. " attempts", 7)
                end
            end)
        end

        --// IsInGroupAsync where the client has it, IsInGroup otherwise. Errors
        --// from the second reach the caller's pcall.
        local function IsInGroup(OtherPlayer, GroupId)
            local Success, IsMember = pcall(function()
                return OtherPlayer:IsInGroupAsync(GroupId)
            end)

            if Success then
                return IsMember
            end

            return OtherPlayer:IsInGroup(GroupId)
        end

        --// The first of GroupIds the player is in, or nil.
        local function FindDangerGroup(OtherPlayer, GroupIds)
            for _, GroupId in ipairs(GroupIds) do
                if IsInGroup(OtherPlayer, GroupId) then
                    return GroupId
                end
            end

            return nil
        end

        --// Group membership is asked once per player; the answer is kept for
        --// as long as they are in the server.
        local function CheckDangerGroup(OtherPlayer)
            if OtherPlayer == Player or OtherPlayer.Parent ~= Players then
                return
            end

            local UserId = tostring(OtherPlayer.UserId)

            if S.DangerUsers[UserId] then
                LeaveFor(OtherPlayer)
                return
            end

            if S.CheckedUsers[UserId] or S.CheckInFlight[UserId] then
                return
            end

            local GroupIds = GetDangerGroupIds()

            if #GroupIds == 0 then
                return
            end

            S.CheckInFlight[UserId] = true

            local Version = S.GroupListVersion

            task.spawn(function()
                local Success, GroupId = pcall(FindDangerGroup, OtherPlayer, GroupIds)

                --// The group list changed while asking: the scan asks again.
                if Version ~= S.GroupListVersion then
                    return
                end

                if not Success then
                    S.CheckFailures[UserId] = (S.CheckFailures[UserId] or 0) + 1
                    warn("[ServerHop] Group check failed for @" .. OtherPlayer.Name .. ":", GroupId)

                    --// Not marked checked: a scan after the retry delay asks
                    --// again, until the last attempt has failed.
                    if S.CheckFailures[UserId] >= GROUP_CHECK_MAX_ATTEMPTS then
                        S.CheckedUsers[UserId] = true
                        Notify("GROUP CHECK", "Could not check @" .. OtherPlayer.Name .. " after " .. GROUP_CHECK_MAX_ATTEMPTS .. " tries", 7,
                            "GROUP CHECK", GROUP_CHECK_NOTICE_COOLDOWN)
                    else
                        task.wait(GROUP_CHECK_RETRY_DELAY)
                    end

                    S.CheckInFlight[UserId] = nil
                    return
                end

                S.CheckInFlight[UserId] = nil
                S.CheckFailures[UserId] = nil
                S.CheckedUsers[UserId] = true

                if GroupId and OtherPlayer.Parent == Players then
                    S.DangerUsers[UserId] = GroupId
                    S.LogVersion += 1
                    LeaveFor(OtherPlayer)
                end
            end)
        end

        ------------------------------------------------------------------------
        --// Join Alerts
        ------------------------------------------------------------------------

        --// "@a, @b, @c, @d and 2 more"
        local function ListNames(Names)
            local Shown = {}

            for Index = 1, math.min(#Names, JOIN_ALERT_MAX_NAMES) do
                Shown[Index] = Names[Index]
            end

            local Text = table.concat(Shown, ", ")

            if #Names > JOIN_ALERT_MAX_NAMES then
                Text ..= string.format(" and %d more", #Names - JOIN_ALERT_MAX_NAMES)
            end

            return Text
        end

        --// Shows the queued alerts as at most two notices: who joined, and
        --// who was already here. Anyone who left or was whitelisted while
        --// queued, or Join Alerts switched off meanwhile, is dropped.
        local function FlushJoinAlerts()
            S.AlertFlushScheduled = false

            local Queue = S.AlertQueue
            S.AlertQueue = {}

            if not Feature.JoinAlerts.Enabled then
                return
            end

            local Joined, Here = {}, {}

            for _, Entry in ipairs(Queue) do
                if Entry.Player.Parent == Players and not IsWhitelisted(Entry.Player) then
                    table.insert(Entry.WasAlreadyHere and Here or Joined, "@" .. Entry.Player.Name)
                end
            end

            if #Joined == 1 then
                NotifyAction("PLAYER JOINED", Joined[1] .. " joined the server", 6)
            elseif #Joined > 1 then
                NotifyAction("PLAYERS JOINED", string.format("%d players joined: %s", #Joined, ListNames(Joined)), 6)
            end

            if #Here == 1 then
                NotifyAction("PLAYER ALREADY HERE", Here[1] .. " is already in this server", 6)
            elseif #Here > 1 then
                NotifyAction("PLAYERS ALREADY HERE", string.format("%d players off the whitelist are here: %s", #Here, ListNames(Here)), 6)
            end
        end

        --// Force skips the repeat window, for a fresh look at who is here.
        local function AlertIfStranger(OtherPlayer, WasAlreadyHere, Force)
            if OtherPlayer == Player or not Feature.JoinAlerts.Enabled or IsWhitelisted(OtherPlayer) then
                return
            end

            local UserId = tostring(OtherPlayer.UserId)
            local now = os.clock()

            if not Force and now - (S.AlertSeen[UserId] or -math.huge) < JOIN_ALERT_REPEAT_SECONDS then
                return
            end

            S.AlertSeen[UserId] = now
            table.insert(S.AlertQueue, { Player = OtherPlayer, WasAlreadyHere = WasAlreadyHere })

            if not S.AlertFlushScheduled then
                S.AlertFlushScheduled = true
                task.delay(JOIN_ALERT_BATCH_SECONDS, FlushJoinAlerts)
            end
        end

        --// Join Alerts switched on, or loaded on: everyone already here, in
        --// one notice.
        function ServerHop:ScanJoinAlerts()
            for _, OtherPlayer in ipairs(Players:GetPlayers()) do
                AlertIfStranger(OtherPlayer, true, true)
            end
        end

        ------------------------------------------------------------------------

        local function OnPlayerAdded(OtherPlayer, WasAlreadyHere)
            if OtherPlayer == Player then
                return
            end

            local UserId = tostring(OtherPlayer.UserId)

            if not S.Online[UserId] then
                S.Online[UserId] = true
                RecordLog(OtherPlayer, WasAlreadyHere and "present" or "joined")
            end

            task.defer(AlertIfStranger, OtherPlayer, WasAlreadyHere)

            --// Before the first Update the profile, and with it the
            --// whitelist, is not loaded yet; that scan covers everyone.
            if S.Ready then
                CheckDangerGroup(OtherPlayer)
            end
        end

        Context.Connect(Players.PlayerAdded, function(OtherPlayer)
            OnPlayerAdded(OtherPlayer, false)
        end)

        Context.Connect(Players.PlayerRemoving, function(OtherPlayer)
            local UserId = tostring(OtherPlayer.UserId)

            if S.Online[UserId] then
                RecordLog(OtherPlayer, "left")
            end

            --// AlertSeen is kept, so leaving and coming straight back is not
            --// announced twice.
            S.Online[UserId] = nil
            S.CheckedUsers[UserId] = nil
            S.CheckFailures[UserId] = nil
        end)

        for _, OtherPlayer in ipairs(Players:GetPlayers()) do
            OnPlayerAdded(OtherPlayer, true)
        end

        Context.Connect(TeleportService.TeleportInitFailed, function(Who, _, ErrorMessage)
            --// Auto Block and Party System teleport too, and report their own
            --// failures; only a teleport of ours is reported here.
            if Who ~= Player or not (S.Teleporting or S.DangerHopStarted) then
                return
            end

            S.Teleporting = false
            SetStatus("TELEPORT FAILED")
            Notify("SERVER", tostring(ErrorMessage or "Teleport failed"), 6)

            --// A failed danger hop tries again on the next scan.
            S.DangerHopStarted = false
        end)

        function ServerHop:Update()
            local now = os.clock()

            if now - S.LastScan < SCAN_INTERVAL then
                return
            end

            S.LastScan = now

            --// A profile that loaded with Join Alerts on: everyone already here.
            if not S.Ready and Feature.JoinAlerts.Enabled then
                ServerHop:ScanJoinAlerts()
            end

            S.Ready = true

            for _, OtherPlayer in ipairs(Players:GetPlayers()) do
                CheckDangerGroup(OtherPlayer)
            end
        end

        return ServerHop
    end,
}
]======],
	["Features/ServerUI.lua"] = [======[
-- ServerUI owns the Server tab, ported from Iambatman's Server page, status
-- card, server info panel and join log: this server's players, place, Job
-- ID, FPS and ping; Rejoin, Server Hop, Copy Job ID and Join Job ID; the
-- Leave On Danger Group and Join Alerts toggles; the Player Log; and the
-- Server Browser window listing public servers. ServerHop does the work.
return {
    Name = "ServerUI",
    IsFeature = true,
    Dependencies = {"Runtime", "SaveConfig", "Components", "ServerHop", "Floating"},

    Start = function(Context)
        local UI = Context.UI
        local UIRef = Context.UIRef
        local CONFIG = Context.CONFIG
        local AICUI = Context.AICUI
        local AICProfile = Context.AICProfile
        local Services = Context.Services
        local Players = Services.Players
        local Player = Context.Player
        local NotifyAction = Context.NotifyAction
        local ServerHop = Context.ServerHop
        local Floating = Context.Floating

        local New, Label, Button = Floating.New, Floating.Label, Floating.Button
        local ClearChildren = Floating.ClearChildren

        local INFO_INTERVAL = 1
        local LOG_SHOWN = 15
        local WINDOW_WIDTH = 600
        local WINDOW_HEIGHT = 420
        --// Share of the window the server list takes; the details get the rest.
        local LIST_WIDTH_SCALE = 0.5
        local ROW_HEIGHT = 40
        --// FPS and ping colour bands, as in Iambatman.
        local FPS_GOOD, FPS_OK = 50, 30
        local PING_GOOD, PING_OK = 100, 200

        local Module = {
            Name = "ServerUI",
            IsFeature = true,
            S = {
                LastInfo = 0,
                FrameCount = 0,
                FrameTime = 0,
                FPS = nil,
                PlaceName = "Place " .. tostring(game.PlaceId),
                LogLabels = {},
                LogVersion = -1,
                --// Server Browser
                Built = false,
                Servers = {},
                Cursor = nil,
                Loading = false,
                Selected = nil,
            },
        }

        local S = Module.S
        local Window, ListScroll, DetailScroll, StatusLabel, RefreshButton, MoreButton

        task.spawn(function()
            local Success, Info = pcall(function()
                return Services.MarketplaceService:GetProductInfo(game.PlaceId)
            end)

            if Success and type(Info) == "table" and Info.Name then
                S.PlaceName = Info.Name
            end
        end)

        local function ShortJobId(JobId)
            JobId = tostring(JobId or "")

            if #JobId > 18 then
                return JobId:sub(1, 8) .. "..." .. JobId:sub(-6)
            end

            return JobId ~= "" and JobId or "-"
        end

        local function GetPingMs()
            local Success, Seconds = pcall(function()
                return Player:GetNetworkPing()
            end)

            return Success and type(Seconds) == "number" and math.floor(Seconds * 1000 + 0.5) or nil
        end

        local function CopyJobId(JobId)
            if JobId == "" then
                NotifyAction("SERVER", "This server has no Job ID", 3)
            elseif Floating.CopyText(JobId) then
                NotifyAction("SERVER", "Job ID copied")
            else
                NotifyAction("SERVER", "Copy is not available here. Job ID: " .. JobId, 8)
            end
        end

        --// The current server as a server list entry.
        local function CurrentServerEntry()
            return {
                Id = tostring(game.JobId or ""),
                Playing = #Players:GetPlayers(),
                MaxPlayers = Players.MaxPlayers,
                Ping = GetPingMs(),
                FPS = S.FPS,
                IsCurrent = true,
            }
        end

        ------------------------------------------------------------------------
        --// Current Server
        ------------------------------------------------------------------------

        local Section = UIRef.ServerSection

        UIRef.ServerPlayersLabel = Section:AddLabel("PLAYERS  0")
        UIRef.ServerJobLabel = Section:AddLabel("JOB ID  -")
        UIRef.ServerFPSLabel = Section:AddLabel("FPS  --")
        UIRef.ServerPingLabel = Section:AddLabel("PING  -- MS")
        UIRef.ServerStatusLabel = Section:AddLabel("STATUS  IDLE")

        Section:AddButton{
            Name = "Rejoin",
            Callback = function()
                ServerHop:Rejoin()
            end,
        }

        Section:AddButton{
            Name = "Server Hop",
            Callback = function()
                ServerHop:Hop()
            end,
        }

        Section:AddButton{
            Name = "Copy Job ID",
            Callback = function()
                CopyJobId(tostring(game.JobId or ""))
            end,
        }

        UIRef.JoinJobIdBox = Section:AddTextBox{ Name = "Job ID", Default = "", Callback = function() end }

        Section:AddButton{
            Name = "Join Job ID",
            Callback = function()
                ServerHop:Join(UIRef.JoinJobIdBox:Get())
            end,
        }

        Section:AddButton{
            Name = "Open Server Browser",
            Callback = function()
                Module:ToggleBrowser()
            end,
        }

        ------------------------------------------------------------------------
        --// Server Safety
        ------------------------------------------------------------------------

        local SafetySection = UIRef.ServerSafetySection

        AICUI.BindFeatureToggle("DangerGroupHop", "Leave On Danger Group", function()
            ServerHop.S.LastScan = 0
        end, SafetySection)

        SafetySection:AddLabel("Leaves if a Danger Group member is here (Danger Whitelist exempt; Block Whitelist too with Whitelist Skips Safety)")
        SafetySection:AddLabel("Toggle, groups and whitelist are shared by every profile")

        --// A list of IDs kept in CONFIG[Key] and the global file. Removing
        --// or reordering a row saves too; OnChanged runs after every save.
        --// Returns the list and its save function.
        local function AddGlobalIdList(Title, Key, OnChanged)
            local List = SafetySection:AddPriority(Title, CONFIG[Key] or {})
            CONFIG[Key] = List.Priority

            local function Save()
                CONFIG[Key] = List.Priority
                AICProfile.WriteGlobalStore()

                if OnChanged then
                    OnChanged()
                end
            end

            local OriginalRemove = List.Remove
            local OriginalMoveUp = List.MoveUp
            local OriginalMoveDown = List.MoveDown

            function List:Remove(Entry)
                local Changed = OriginalRemove(self, Entry)
                Save()
                return Changed
            end

            function List:MoveUp(Entry)
                OriginalMoveUp(self, Entry)
                Save()
            end

            function List:MoveDown(Entry)
                OriginalMoveDown(self, Entry)
                Save()
            end

            return List, Save
        end

        --// Groups whose members Leave On Danger Group leaves for.
        local DangerGroups, SaveDangerGroups = AddGlobalIdList("Danger Groups", "DANGER_GROUP_IDS", function()
            ServerHop:ResetGroupChecks()
        end)

        local DangerGroupBox = SafetySection:AddTextBox{ Name = "Group ID", Default = "", Callback = function() end }

        SafetySection:AddButton{
            Name = "Add Group ID",
            Callback = function()
                local Id = tostring(DangerGroupBox:Get() or ""):gsub("%s+", "")

                if not Id:match("^%d+$") then
                    NotifyAction("Danger Groups", "Enter a numeric group ID")
                    return
                end

                if table.find(CONFIG.DANGER_GROUP_IDS or {}, Id) then
                    NotifyAction("Danger Groups", Id .. " is already on the list")
                    return
                end

                DangerGroups:Add(Id)
                SaveDangerGroups()
                DangerGroupBox:Set("")
                NotifyAction("Danger Groups", "Added group " .. Id)
            end,
        }

        --// Players Leave On Danger Group stays for, separate from the Auto
        --// Block whitelist.
        local DangerPlayerOptions = {}
        local DangerPlayerDropdown
        local RefreshDangerPlayerDropdown

        local DangerWhitelist, SaveDangerWhitelist = AddGlobalIdList("Danger Whitelist", "DANGER_WHITELIST", function()
            --// Someone taken off the list is acted on at the next frame.
            ServerHop.S.LastScan = 0
            task.defer(RefreshDangerPlayerDropdown)
        end)

        AICUI.ShowUserNames(DangerWhitelist)

        local function AddDangerWhitelist(UserId, Label)
            if ServerHop:IsDangerWhitelisted(UserId) then
                NotifyAction("Danger Whitelist", tostring(Label) .. " is already on the list")
                return false
            end

            DangerWhitelist:Add(UserId)
            SaveDangerWhitelist()
            NotifyAction("Danger Whitelist", "Added " .. tostring(Label))
            return true
        end

        --// DangerPlayerOptions maps each label to its UserId text.
        function RefreshDangerPlayerDropdown()
            table.clear(DangerPlayerOptions)

            local Options = {}

            for _, OtherPlayer in ipairs(Players:GetPlayers()) do
                if OtherPlayer ~= Player and not ServerHop:IsDangerWhitelisted(OtherPlayer.UserId) then
                    local Text = string.format("%s (@%s)  %d", OtherPlayer.DisplayName, OtherPlayer.Name, OtherPlayer.UserId)
                    DangerPlayerOptions[Text] = tostring(OtherPlayer.UserId)
                    table.insert(Options, Text)
                end
            end

            table.sort(Options, function(A, B)
                return string.lower(A) < string.lower(B)
            end)

            if #Options == 0 then
                Options = {"No other players"}
            end

            --// A new dropdown is appended to the section, so it takes the
            --// old one's slot to keep its place in the list.
            local Order = DangerPlayerDropdown and DangerPlayerDropdown.Row and DangerPlayerDropdown.Row.LayoutOrder

            if DangerPlayerDropdown and DangerPlayerDropdown.Remove then
                DangerPlayerDropdown:Remove()
            end

            DangerPlayerDropdown = SafetySection:AddDropdown{
                Name = "Add Player In Server",
                Options = Options,
                Callback = function(Value)
                    local Id = DangerPlayerOptions[Value]

                    if Id then
                        AddDangerWhitelist(Id, Value)
                    end
                end,
            }

            if Order and DangerPlayerDropdown.Row then
                DangerPlayerDropdown.Row.LayoutOrder = Order
            end
        end

        RefreshDangerPlayerDropdown()

        local DangerWhitelistBox = SafetySection:AddTextBox{ Name = "User ID", Default = "", Callback = function() end }

        SafetySection:AddButton{
            Name = "Add User ID",
            Callback = function()
                local Id = tostring(DangerWhitelistBox:Get() or ""):gsub("%s+", "")

                if not Id:match("^%d+$") then
                    NotifyAction("Danger Whitelist", "Enter a numeric UserId")
                    return
                end

                if AddDangerWhitelist(Id, Id) then
                    DangerWhitelistBox:Set("")
                end
            end,
        }

        SafetySection:AddButton{
            Name = "Clear Danger Whitelist",
            Callback = function()
                DangerWhitelist:SetPriority({})
                SaveDangerWhitelist()
                NotifyAction("Danger Whitelist", "Cleared")
            end,
        }

        Context.Connect(Players.PlayerAdded, function()
            RefreshDangerPlayerDropdown()
        end)

        Context.Connect(Players.PlayerRemoving, function()
            task.defer(RefreshDangerPlayerDropdown)
        end)

        AICUI.BindFeatureToggle("JoinAlerts", "Join Alerts", function(Enabled)
            if Enabled then
                ServerHop:ScanJoinAlerts()
            end
        end, SafetySection)

        SafetySection:AddLabel("Notifies about players off the Auto Block whitelist")

        ------------------------------------------------------------------------
        --// Player Log
        ------------------------------------------------------------------------

        local LogSection = UIRef.ServerLogSection

        LogSection:AddButton{
            Name = "Clear Log",
            Callback = function()
                ServerHop:ClearLog()
            end,
        }

        local function DescribeLogEntry(Entry)
            local Tags = ""
            local OtherPlayer = Players:GetPlayerByUserId(tonumber(Entry.UserId) or 0)

            if Context.AICFeature.IsWhitelisted and Context.AICFeature.IsWhitelisted(Entry.UserId) then
                Tags ..= "  [WHITELIST]"
            end

            if ServerHop:IsDangerWhitelisted(Entry.UserId) then
                Tags ..= "  [DANGER WHITELIST]"
            end

            if OtherPlayer and ServerHop:IsDangerPlayer(OtherPlayer) then
                Tags ..= "  [DANGER]"
            end

            return string.format("%s  %s  @%s%s", Entry.Time, string.upper(Entry.Event), Entry.Name, Tags)
        end

        local function RefreshLog()
            if ServerHop.S.LogVersion == S.LogVersion then
                return
            end

            S.LogVersion = ServerHop.S.LogVersion

            local Lines = {}

            for Index, Entry in ipairs(ServerHop:GetLog()) do
                if Index > LOG_SHOWN then
                    break
                end

                Lines[Index] = DescribeLogEntry(Entry)
            end

            if #Lines == 0 then
                Lines[1] = "NO PLAYERS LOGGED YET"
            end

            for Index, Text in ipairs(Lines) do
                local LogLabel = S.LogLabels[Index]

                if not LogLabel then
                    LogLabel = LogSection:AddLabel(Text)
                    S.LogLabels[Index] = LogLabel
                end

                LogLabel:Set(Text)
                LogLabel:SetVisible(true)
            end

            for Index = #Lines + 1, #S.LogLabels do
                S.LogLabels[Index]:SetVisible(false)
            end
        end

        ------------------------------------------------------------------------
        --// Server Browser
        ------------------------------------------------------------------------

        local function PingText(Ping)
            return Ping and string.format("%d ms", math.floor(Ping + 0.5)) or "n/a"
        end

        local function FPSText(FPS)
            return FPS and tostring(math.floor(FPS + 0.5)) or "n/a"
        end

        local function BuildDetail()
            local Theme = UI.Theme
            local Server = S.Selected

            ClearChildren(DetailScroll)

            if not Server then
                Label(DetailScroll, "Pick a server from the list", 12, { TextColor3 = Theme.TextMuted, LayoutOrder = 1 })
                return
            end

            local IsCurrent = Server.Id == tostring(game.JobId or "")

            if IsCurrent then
                Server = CurrentServerEntry()
            end

            Label(DetailScroll, (IsCurrent and "◇  THIS SERVER" or "◇  PUBLIC SERVER"), 13, {
                TextColor3 = Theme.Cyan,
                Font = Floating.Fonts.Bold,
                LayoutOrder = 1,
            })
            Label(DetailScroll, string.format("PLAYERS  %d / %d", Server.Playing or 0, Server.MaxPlayers or 0), 10, {
                Font = Floating.Fonts.Bold,
                LayoutOrder = 2,
            })
            Label(DetailScroll, string.format("PING  %s  ·  FPS  %s", PingText(Server.Ping), FPSText(Server.FPS)):upper(), 10, {
                TextColor3 = Theme.TextSecondary,
                LayoutOrder = 3,
            })
            Label(DetailScroll, "JOB ID  " .. Server.Id, 9, {
                TextColor3 = Theme.TextMuted,
                TextWrapped = true,
                TextTruncate = Enum.TextTruncate.None,
                AutomaticSize = Enum.AutomaticSize.Y,
                LayoutOrder = 4,
            })

            local Copy = Button(DetailScroll, "COPY JOB ID", Theme.Text, { LayoutOrder = 5 })
            UI:_Connect(Copy.Activated, function()
                CopyJobId(Server.Id)
            end)

            if not IsCurrent then
                local Join = Button(DetailScroll, "JOIN", Theme.Cyan, { LayoutOrder = 6 })
                UI:_Connect(Join.Activated, function()
                    ServerHop:Join(Server.Id)
                end)

                Label(DetailScroll, "Roblox's server list gives player counts only, not names, for other servers", 9, {
                    TextColor3 = Theme.TextMuted,
                    TextWrapped = true,
                    TextTruncate = Enum.TextTruncate.None,
                    AutomaticSize = Enum.AutomaticSize.Y,
                    LayoutOrder = 7,
                })
                return
            end

            Label(DetailScroll, "PLAYERS IN THIS SERVER", 8, {
                TextColor3 = Theme.TextMuted,
                Font = Floating.Fonts.Bold,
                LayoutOrder = 6,
            })

            local Here = Players:GetPlayers()

            table.sort(Here, function(A, B)
                if A == Player or B == Player then
                    return A == Player and B ~= Player
                end

                return string.lower(A.Name) < string.lower(B.Name)
            end)

            for Index, OtherPlayer in ipairs(Here) do
                local Display = OtherPlayer.DisplayName ~= "" and OtherPlayer.DisplayName or OtherPlayer.Name
                local Text = string.format("%s%s  @%s", OtherPlayer == Player and "YOU  ·  " or "", Display, OtherPlayer.Name)

                if ServerHop:IsDangerPlayer(OtherPlayer) then
                    Text ..= "  [DANGER]"
                end

                Label(DetailScroll, Text, 10, {
                    TextColor3 = OtherPlayer == Player and Theme.Cyan
                        or (ServerHop:IsDangerPlayer(OtherPlayer) and Theme.Danger or Theme.Text),
                    LayoutOrder = 6 + Index,
                })
            end
        end

        local function SelectServer(Server)
            S.Selected = Server
            S.DetailSignature = nil
            BuildDetail()
        end

        local function AddServerRow(Server, Order)
            local Theme = UI.Theme
            local IsCurrent = Server.IsCurrent == true

            local Row = New("TextButton", {
                Parent = ListScroll,
                Size = UDim2.new(1, -6, 0, ROW_HEIGHT),
                BackgroundColor3 = IsCurrent and Theme.PanelHover or Theme.Element,
                BackgroundTransparency = 0.1,
                BorderSizePixel = 0,
                Text = "",
                AutoButtonColor = false,
                LayoutOrder = Order,
            })

            Floating.Hover(Row)

            --// Accent bar on the left: cyan for the server we are in.
            New("Frame", {
                Parent = Row,
                BackgroundColor3 = IsCurrent and Theme.Cyan or Theme.BorderDim,
                BorderSizePixel = 0,
                Position = UDim2.fromOffset(0, 6),
                Size = UDim2.new(0, 2, 1, -12),
            })

            Label(Row, string.format("%s%d / %d PLAYERS", IsCurrent and "◆  YOU ARE HERE  ·  " or "◇  ", Server.Playing or 0, Server.MaxPlayers or 0), 10, {
                Position = UDim2.fromOffset(10, 5),
                Size = UDim2.new(1, -18, 0, 15),
                TextColor3 = IsCurrent and Theme.Cyan or Theme.Text,
                Font = Floating.Fonts.Bold,
            })
            Label(Row, string.format("PING %s  ·  FPS %s  ·  %s", PingText(Server.Ping), FPSText(Server.FPS), ShortJobId(Server.Id)):upper(), 8, {
                Position = UDim2.fromOffset(10, 22),
                Size = UDim2.new(1, -18, 0, 12),
                TextColor3 = Theme.TextMuted,
            })

            UI:_Connect(Row.Activated, function()
                SelectServer(Server)
            end)
        end

        local function RedrawList()
            ClearChildren(ListScroll)

            for Index, Server in ipairs(S.Servers) do
                AddServerRow(Server, Index)
            end
        end

        --// Reset starts over with this server on top; otherwise the next page.
        local function LoadServers(Reset)
            if S.Loading or (not Reset and not S.Cursor) then
                return
            end

            if Reset then
                S.Cursor = nil
                S.Servers = { CurrentServerEntry() }
                RedrawList()
            end

            S.Loading = true
            StatusLabel.Text = Reset and "Loading public servers..." or "Loading more servers..."

            task.spawn(function()
                local Servers, NextCursor, Error = ServerHop:ReadPublicServers(not Reset and S.Cursor or nil)
                S.Loading = false

                if not Servers then
                    S.Cursor = nil
                    MoreButton.Visible = false
                    StatusLabel.Text = "Could not load servers: " .. tostring(Error)
                    return
                end

                local Seen = {}

                for _, Server in ipairs(S.Servers) do
                    Seen[Server.Id] = true
                end

                for _, Server in ipairs(Servers) do
                    if not Seen[Server.Id] then
                        Seen[Server.Id] = true
                        table.insert(S.Servers, Server)
                        AddServerRow(Server, #S.Servers)
                    end
                end

                S.Cursor = NextCursor
                MoreButton.Visible = NextCursor ~= nil
                StatusLabel.Text = string.format("%d servers%s", #S.Servers, NextCursor and "  ·  more available" or "")
            end)
        end

        local function BuildBrowser()
            local Theme = UI.Theme

            Window = Floating.CreateWindow({
                Title = "SERVER BROWSER",
                Subtitle = "Public servers  //  pick one to see it and join",
                Width = WINDOW_WIDTH,
                Height = WINDOW_HEIGHT,
            })

            RefreshButton = Button(Window.Body, "◇  REFRESH", Theme.Cyan, { Size = UDim2.fromOffset(100, 26) })
            MoreButton = Button(Window.Body, "LOAD MORE", Theme.Text, {
                Position = UDim2.fromOffset(106, 0),
                Size = UDim2.fromOffset(90, 26),
                Visible = false,
            })
            StatusLabel = Label(Window.Body, "", 9, {
                Position = UDim2.fromOffset(206, 0),
                Size = UDim2.new(1, -206, 0, 26),
                TextColor3 = Theme.TextMuted,
            })

            local Lists = New("Frame", {
                Parent = Window.Body,
                BackgroundTransparency = 1,
                Position = UDim2.fromOffset(0, 34),
                Size = UDim2.new(1, 0, 1, -34),
            })

            ListScroll = Floating.Scroller(Lists, UDim2.new(), UDim2.new(LIST_WIDTH_SCALE, -4, 1, 0), 4, 4)
            DetailScroll = Floating.Scroller(Lists, UDim2.new(LIST_WIDTH_SCALE, 4, 0, 0), UDim2.new(1 - LIST_WIDTH_SCALE, -4, 1, 0), 8, 6)

            UI:_Connect(RefreshButton.Activated, function()
                LoadServers(true)
            end)

            UI:_Connect(MoreButton.Activated, function()
                LoadServers(false)
            end)

            S.Built = true
        end

        function Module:ToggleBrowser()
            if not Floating.Available() then
                return
            end

            if not S.Built then
                BuildBrowser()
            end

            if Window.IsOpen then
                Window:Close()
                return
            end

            Window:Open()
            SelectServer(CurrentServerEntry())
            LoadServers(true)
        end

        ------------------------------------------------------------------------

        local function ColorBand(Value, Good, Ok, LowerIsBetter)
            local Theme = UI.Theme

            if not Value then
                return Theme.TextMuted
            end

            local IsGood = LowerIsBetter and Value < Good or not LowerIsBetter and Value >= Good
            local IsOk = LowerIsBetter and Value < Ok or not LowerIsBetter and Value >= Ok
            return IsGood and Theme.Cyan or (IsOk and Theme.Warning or Theme.Danger)
        end

        local function RefreshInfo()
            local Ping = GetPingMs()

            UIRef.ServerPlayersLabel:Set(string.format("PLAYERS  %d / %d  //  %s", #Players:GetPlayers(), Players.MaxPlayers, S.PlaceName))
            UIRef.ServerJobLabel:Set(string.format("JOB ID  %s  //  PLACE  %d", ShortJobId(game.JobId), game.PlaceId))
            UIRef.ServerFPSLabel:Set("FPS  " .. (S.FPS and tostring(S.FPS) or "--"))
            UIRef.ServerFPSLabel:SetColor(ColorBand(S.FPS, FPS_GOOD, FPS_OK, false))
            UIRef.ServerPingLabel:Set("PING  " .. (Ping and tostring(Ping) or "--") .. " MS")
            UIRef.ServerPingLabel:SetColor(ColorBand(Ping, PING_GOOD, PING_OK, true))
            UIRef.ServerStatusLabel:Set("STATUS  " .. ServerHop:GetStatus())

            RefreshLog()

            --// The current server's details follow its players while shown,
            --// redrawn only when they change so the scroll stays put.
            if Window and Window.IsOpen and S.Selected and S.Selected.Id == tostring(game.JobId or "") then
                local Names = {}

                for _, OtherPlayer in ipairs(Players:GetPlayers()) do
                    table.insert(Names, OtherPlayer.Name .. (ServerHop:IsDangerPlayer(OtherPlayer) and "!" or ""))
                end

                table.sort(Names)

                local Signature = table.concat(Names, ",")

                if Signature ~= S.DetailSignature then
                    S.DetailSignature = Signature
                    BuildDetail()
                end
            end
        end

        --// Heartbeat drives this every frame, so it also counts the FPS.
        function Module:Update(dt)
            S.FrameCount += 1
            S.FrameTime += dt or 0

            if S.FrameTime >= INFO_INTERVAL then
                S.FPS = math.floor(S.FrameCount / S.FrameTime + 0.5)
                S.FrameCount = 0
                S.FrameTime = 0
            end

            local now = os.clock()

            if now - S.LastInfo >= INFO_INTERVAL then
                S.LastInfo = now
                RefreshInfo()
            end
        end

        return Module
    end,
}
]======],
	["Features/SmithingBrowser.lua"] = [======[
-- SmithingBrowser is the Recipe Browser, a window of its own opened from the
-- Crafting tab. Everything about crafting can be done from it, without the
-- main window:
--
--   * The left side lists every recipe, narrowed by the search box (recipe
--     or material name), the item type chips and READY ONLY.
--   * The RECIPE tab (SmithingDetail) shows the one picked, with CRAFT NOW
--     and the button that adds it to Recipe Priority.
--   * The PRIORITY tab is the Recipe Priority list itself, the same one as
--     on the Crafting tab.
return {
    Name = "SmithingBrowser",
    IsFeature = true,
    Dependencies = {"Runtime", "SaveConfig", "Components", "SmithingRecipes", "SmithingDetail", "Floating"},

    Start = function(Context)
        local UI = Context.UI
        local CONFIG = Context.CONFIG
        local AICUI = Context.AICUI
        local Recipes = Context.SmithingRecipes
        local Detail = Context.SmithingDetail
        local Floating = Context.Floating

        local New, Stroke = Floating.New, Floating.Stroke
        local Label, Button, ClearChildren = Floating.Label, Floating.Button, Floating.ClearChildren

        local ReadInventory, Describe, GetCraftMax = Detail.ReadInventory, Detail.Describe, Detail.GetCraftMax
        local IsInPriority, DescribeStatus, DescribeItem = Detail.IsInPriority, Detail.DescribeStatus, Detail.DescribeItem

        local MAX_STACK = Context.SaveConfig.ITEM_MAX_STACK
        local WINDOW_WIDTH = 820
        local WINDOW_HEIGHT = 540
        local MIN_WIDTH = 640
        local MIN_HEIGHT = 420
        --// Share of the window the recipe list takes; the tabs get the rest.
        local LIST_WIDTH_SCALE = 0.44
        local ROW_HEIGHT = 54
        local BAR_HEIGHT = 36
        local CHIP_HEIGHT = 32
        local ALL_TYPES = "ALL"
        --// Inventory and skill are read again this often while open.
        local REFRESH_INTERVAL = 1

        local Browser = {
            Name = "SmithingBrowser",
            IsFeature = true,
            --// Set by AutoSmithing: the PRIORITY tab changed the list.
            OnPriorityChanged = nil,
            S = {
                Built = false,
                IsOpen = false,
                --// "Recipe" or "Priority".
                Tab = "Recipe",
                TypeFilter = ALL_TYPES,
                ReadyOnly = false,
                --// Recipe name -> list row, kept between refreshes.
                Rows = {},
                --// Type -> chip button.
                Chips = {},
                ChipSignature = nil,
                LastRefresh = 0,
                --// Shows CONFIG.SMITH_RECIPES in the PRIORITY tab's list.
                LoadPriority = nil,
            },
        }

        local S = Browser.S
        local Theme, Window, SearchBox, ReadyButton, ChipScroll, ListScroll, EmptyLabel
        local DetailScroll, PriorityScroll, RecipeTabButton, PriorityTabButton

        ------------------------------------------------------------------------
        --// Filters
        ------------------------------------------------------------------------

        local function MatchesSearch(Recipe, Query)
            if Query == "" or string.find(string.lower(Recipe.Name), Query, 1, true) then
                return true
            end

            --// Also finds what a material is used in.
            for _, Material in ipairs(Recipe.Materials) do
                if string.find(string.lower(Material.Name), Query, 1, true) then
                    return true
                end
            end

            return false
        end

        local function IsShown(Recipe, Query, Stock)
            if S.TypeFilter ~= ALL_TYPES and Recipes:GetItemType(Recipe.Name) ~= S.TypeFilter then
                return false
            end

            if S.ReadyOnly and GetCraftMax(Describe(Recipe.Name, Stock)) < 1 then
                return false
            end

            return MatchesSearch(Recipe, Query)
        end

        ------------------------------------------------------------------------
        --// Tabs
        ------------------------------------------------------------------------

        local function StyleTab(TabButton, Active)
            TabButton.TextColor3 = Active and Theme.Cyan or Theme.TextMuted
            TabButton.BackgroundColor3 = Active and Theme.PanelHover or Theme.Element
        end

        local function RefreshTabs()
            DetailScroll.Visible = S.Tab == "Recipe"
            PriorityScroll.Visible = S.Tab == "Priority"
            PriorityTabButton.Text = string.format("PRIORITY  (%d)", #(CONFIG.SMITH_RECIPES or {}))
            StyleTab(RecipeTabButton, S.Tab == "Recipe")
            StyleTab(PriorityTabButton, S.Tab == "Priority")
        end

        local function SetTab(Tab)
            S.Tab = Tab
            Detail:HidePopup()
            RefreshTabs()
        end

        --// PRIORITY: the Utils priority list, bound to SMITH_RECIPES like the
        --// one on the Crafting tab. Either one changing reloads the other.
        local function BuildPriorityTab()
            local Section = Floating.Section(PriorityScroll, { Size = UDim2.new(1, -6, 0, 0) })

            Label(Section.Holder, "Recipes are crafted top to bottom until each reaches its Target. Add them from the RECIPE tab.", 10, {
                TextColor3 = Theme.TextMuted,
                TextWrapped = true,
                TextTruncate = Enum.TextTruncate.None,
                AutomaticSize = Enum.AutomaticSize.Y,
                LayoutOrder = 0,
            })

            local PriorityList = Section:AddPriority("Recipe Priority", {}, {
                Values = true,
                ValueLabel = "Target",
                Default = MAX_STACK,
                Min = 0,
                Max = MAX_STACK,
            })

            S.LoadPriority = AICUI.BindCountList(PriorityList, "SMITH_RECIPES", "Target", function()
                if Browser.OnPriorityChanged then
                    Browser.OnPriorityChanged()
                end

                Browser:Refresh()
            end)

            S.LoadPriority()
        end

        ------------------------------------------------------------------------
        --// Filters and recipe list
        ------------------------------------------------------------------------

        local function StyleChip(Chip, Active)
            Chip.TextColor3 = Active and Theme.Cyan or Theme.TextMuted
            Chip.BackgroundColor3 = Active and Theme.PanelHover or Theme.Element
        end

        --// One chip per item type among the recipes, rebuilt when the types
        --// change; the active one is highlighted.
        local function RefreshChips(All)
            local Counts = { [ALL_TYPES] = #All }
            local Types = {}

            for _, Recipe in ipairs(All) do
                local Type = Recipes:GetItemType(Recipe.Name)

                if not Counts[Type] then
                    Counts[Type] = 0
                    table.insert(Types, Type)
                end

                Counts[Type] += 1
            end

            table.sort(Types)
            table.insert(Types, 1, ALL_TYPES)

            local Parts = {}

            for _, Type in ipairs(Types) do
                table.insert(Parts, Type .. "=" .. Counts[Type])
            end

            local Signature = table.concat(Parts, "|")

            if Signature ~= S.ChipSignature then
                S.ChipSignature = Signature
                ClearChildren(ChipScroll)
                table.clear(S.Chips)

                if not Counts[S.TypeFilter] then
                    S.TypeFilter = ALL_TYPES
                end

                for Index, Type in ipairs(Types) do
                    local Text = string.format("%s  %d", Type:upper(), Counts[Type])
                    local Chip = Button(ChipScroll, Text, Theme.TextMuted, {
                        Size = UDim2.fromOffset(0, CHIP_HEIGHT),
                        AutomaticSize = Enum.AutomaticSize.X,
                        TextSize = 9,
                        LayoutOrder = Index,
                    })

                    New("UIPadding", { Parent = Chip, PaddingLeft = UDim.new(0, 14), PaddingRight = UDim.new(0, 14) })

                    UI:_Connect(Chip.Activated, function()
                        S.TypeFilter = Type
                        Browser:Refresh()
                    end)

                    S.Chips[Type] = Chip
                end
            end

            for Type, Chip in pairs(S.Chips) do
                StyleChip(Chip, Type == S.TypeFilter)
            end

            StyleChip(ReadyButton, S.ReadyOnly)
        end

        local function CreateRow(Name)
            local Row = New("TextButton", {
                Parent = ListScroll,
                Size = UDim2.new(1, -6, 0, ROW_HEIGHT),
                BackgroundColor3 = Theme.Element,
                BackgroundTransparency = 0,
                BorderSizePixel = 0,
                Text = "",
                AutoButtonColor = false,
            })

            Floating.Hover(Row)

            local Bar = New("Frame", {
                Parent = Row,
                Position = UDim2.fromOffset(0, 6),
                Size = UDim2.new(0, 3, 1, -12),
                BorderSizePixel = 0,
            })

            local NameLabel = Label(Row, string.upper(Name), 13, {
                Position = UDim2.fromOffset(14, 6),
                Size = UDim2.new(1, -22, 0, 20),
                Font = Floating.Fonts.Bold,
            })
            local InfoLabel = Label(Row, "", 10, { Position = UDim2.fromOffset(14, 29), Size = UDim2.new(1, -22, 0, 17) })

            UI:_Connect(Row.Activated, function()
                Browser:Select(Name)
            end)

            return { Button = Row, Bar = Bar, NameLabel = NameLabel, InfoLabel = InfoLabel }
        end

        local function UpdateRow(Row, Recipe, Stock)
            local Status, Color = DescribeStatus(Describe(Recipe.Name, Stock))
            local Selected = Detail:GetSelected() == Recipe.Name
            local Info = DescribeItem(Recipe.Name) .. "  ·  " .. Status

            if IsInPriority(Recipe.Name) then
                Info = "✓ " .. Info
            end

            Row.Bar.BackgroundColor3 = Color
            Row.InfoLabel.Text = Info
            Row.InfoLabel.TextColor3 = Color
            Row.NameLabel.TextColor3 = Selected and Theme.Cyan or Theme.Text
            Row.Button.BackgroundColor3 = Selected and Theme.PanelHover or Theme.Element
        end

        local function RefreshList(Stock)
            local Query = string.lower(SearchBox.Text or "")
            local All = Recipes:GetAll()
            local Seen = {}
            local Shown = 0

            RefreshChips(All)

            for Index, Recipe in ipairs(All) do
                Seen[Recipe.Name] = true

                local Row = S.Rows[Recipe.Name]

                if not Row then
                    Row = CreateRow(Recipe.Name)
                    S.Rows[Recipe.Name] = Row
                end

                local Visible = IsShown(Recipe, Query, Stock)
                Row.Button.Visible = Visible
                Row.Button.LayoutOrder = Index

                if Visible then
                    Shown += 1
                    UpdateRow(Row, Recipe, Stock)
                end
            end

            for Name, Row in pairs(S.Rows) do
                if not Seen[Name] then
                    Row.Button:Destroy()
                    S.Rows[Name] = nil
                end
            end

            EmptyLabel.Text = #All == 0 and "No recipes found" or "No recipes match the filters"
            EmptyLabel.Visible = Shown == 0
        end

        ------------------------------------------------------------------------
        --// Window
        ------------------------------------------------------------------------

        local function BuildFilterBar(Body)
            SearchBox = New("TextBox", {
                Parent = Body,
                Size = UDim2.new(1, -144, 0, BAR_HEIGHT),
                BackgroundColor3 = Theme.Element,
                BorderSizePixel = 0,
                Text = "",
                PlaceholderText = "SEARCH RECIPE OR MATERIAL...",
                PlaceholderColor3 = Theme.TextMuted,
                TextColor3 = Theme.Text,
                TextSize = 10,
                Font = Floating.Fonts.Regular,
                TextXAlignment = Enum.TextXAlignment.Left,
                ClearTextOnFocus = false,
            })

            Floating.Hover(SearchBox, Stroke(SearchBox, Theme.BorderDim, 0.15))
            New("UIPadding", { Parent = SearchBox, PaddingLeft = UDim.new(0, 14), PaddingRight = UDim.new(0, 14) })

            ReadyButton = Button(Body, "◇  READY ONLY", Theme.TextMuted, {
                AnchorPoint = Vector2.new(1, 0),
                Position = UDim2.new(1, 0, 0, 0),
                Size = UDim2.fromOffset(136, BAR_HEIGHT),
            })

            ChipScroll = New("ScrollingFrame", {
                Parent = Body,
                Position = UDim2.fromOffset(0, BAR_HEIGHT + 6),
                Size = UDim2.new(1, 0, 0, CHIP_HEIGHT + 6),
                BackgroundTransparency = 1,
                BorderSizePixel = 0,
                CanvasSize = UDim2.new(),
                AutomaticCanvasSize = Enum.AutomaticSize.X,
                ScrollBarThickness = 3,
                ScrollBarImageColor3 = Theme.Border,
                ScrollingDirection = Enum.ScrollingDirection.X,
            })

            New("UIListLayout", {
                Parent = ChipScroll,
                FillDirection = Enum.FillDirection.Horizontal,
                SortOrder = Enum.SortOrder.LayoutOrder,
                Padding = UDim.new(0, 6),
            })

            UI:_Connect(SearchBox:GetPropertyChangedSignal("Text"), function()
                RefreshList(ReadInventory())
            end)

            UI:_Connect(ReadyButton.Activated, function()
                S.ReadyOnly = not S.ReadyOnly
                Browser:Refresh()
            end)
        end

        local function BuildRightSide(Lists)
            local Right = New("Frame", {
                Parent = Lists,
                BackgroundTransparency = 1,
                Position = UDim2.new(LIST_WIDTH_SCALE, 4, 0, 0),
                Size = UDim2.new(1 - LIST_WIDTH_SCALE, -4, 1, 0),
            })

            RecipeTabButton = Button(Right, "RECIPE", Theme.Cyan, { Size = UDim2.new(0.5, -2, 0, BAR_HEIGHT) })
            PriorityTabButton = Button(Right, "PRIORITY", Theme.TextMuted, {
                Position = UDim2.new(0.5, 2, 0, 0),
                Size = UDim2.new(0.5, -2, 0, BAR_HEIGHT),
            })

            local Below = UDim2.fromOffset(0, BAR_HEIGHT + 6)
            local BelowSize = UDim2.new(1, 0, 1, -(BAR_HEIGHT + 6))

            DetailScroll = Floating.Scroller(Right, Below, BelowSize, 8, 6)
            PriorityScroll = Floating.Scroller(Right, Below, BelowSize, 8, 6)
            Detail:Build(DetailScroll, Browser)

            UI:_Connect(RecipeTabButton.Activated, function()
                SetTab("Recipe")
            end)

            UI:_Connect(PriorityTabButton.Activated, function()
                SetTab("Priority")
            end)

            BuildPriorityTab()
        end

        local function Build()
            Theme = UI.Theme

            Window = Floating.CreateWindow({
                Title = "RECIPE BROWSER",
                Subtitle = "Find recipes  //  craft now  //  edit Recipe Priority",
                Width = WINDOW_WIDTH,
                Height = WINDOW_HEIGHT,
                MinWidth = MIN_WIDTH,
                MinHeight = MIN_HEIGHT,
                OnClose = function()
                    S.IsOpen = false
                    Detail:HidePopup()
                end,
                --// The popup belongs to a row that is now hidden.
                OnMinimize = function()
                    Detail:HidePopup()
                end,
            })

            BuildFilterBar(Window.Body)

            local Top = BAR_HEIGHT + CHIP_HEIGHT + 24
            local Lists = New("Frame", {
                Parent = Window.Body,
                BackgroundTransparency = 1,
                Position = UDim2.fromOffset(0, Top),
                Size = UDim2.new(1, 0, 1, -Top),
            })

            ListScroll = Floating.Scroller(Lists, UDim2.new(), UDim2.new(LIST_WIDTH_SCALE, -4, 1, 0), 4, 4)
            EmptyLabel = Label(ListScroll, "No recipes match the filters", 10, {
                TextColor3 = Theme.TextMuted,
                Visible = false,
                LayoutOrder = -1,
            })

            BuildRightSide(Lists)
            RefreshTabs()

            S.Built = true
        end

        ------------------------------------------------------------------------
        --// API
        ------------------------------------------------------------------------

        function Browser:Refresh()
            if not S.IsOpen then
                return
            end

            S.LastRefresh = os.clock()

            local Stock = ReadInventory()
            RefreshList(Stock)
            Detail:Refresh(Stock)
            RefreshTabs()
        end

        --// Recipe Priority changed outside the window (the Crafting tab, a
        --// profile load): show it in the PRIORITY tab too.
        function Browser:SyncPriority()
            if S.LoadPriority then
                S.LoadPriority()
            end

            Browser:Refresh()
        end

        function Browser:Select(Name)
            Detail:Select(Name)

            if S.Tab ~= "Recipe" then
                SetTab("Recipe")
            end

            Browser:Refresh()
        end

        function Browser:Open()
            if not Floating.Available() then
                return
            end

            if not S.Built then
                Build()
            end

            S.IsOpen = true
            Detail:Invalidate()
            Window:Open()
            Browser:Refresh()
        end

        function Browser:Close()
            if Window then
                Window:Close()
            end
        end

        function Browser:Toggle()
            if S.IsOpen then
                Browser:Close()
            else
                Browser:Open()
            end
        end

        function Browser:Update()
            if S.IsOpen and os.clock() - S.LastRefresh >= REFRESH_INTERVAL then
                Browser:Refresh()
            end
        end

        return Browser
    end,
}
]======],
	["Features/SmithingDetail.lua"] = [======[
-- SmithingDetail is the RECIPE tab of the Recipe Browser (SmithingBrowser):
-- the recipe picked in the list with its type, level or skill and stats
-- from the game's assets, whether it can be traded, what one craft needs
-- and what is missing, a popup showing what a tapped material is crafted
-- from, CRAFT NOW (a craft order in AutoSmithing, up to what the materials
-- allow) and the button that adds it to Recipe Priority or takes it out.
-- It also holds the recipe helpers the browser's list shares.
return {
    Name = "SmithingDetail",
    Dependencies = {"Runtime", "SaveConfig", "SmithingRecipes", "AutoSmithing", "Floating"},

    Start = function(Context)
        local UI = Context.UI
        local UIRef = Context.UIRef
        local CONFIG = Context.CONFIG
        local NotifyAction = Context.NotifyAction
        local Recipes = Context.SmithingRecipes
        local AutoSmithing = Context.AutoSmithing
        local Floating = Context.Floating
        local UserInputService = Context.Services.UserInputService

        local New, Stroke, Padding, List = Floating.New, Floating.Stroke, Floating.Padding, Floating.List
        local Label, Button, ClearChildren, IsInside = Floating.Label, Floating.Button, Floating.ClearChildren, Floating.IsInside

        local MAX_STACK = Context.SaveConfig.ITEM_MAX_STACK
        local ROW_HEIGHT = 34
        local POPUP_WIDTH = 240

        local Detail = {
            Name = "SmithingDetail",
            S = {
                Selected = nil,
                --// CRAFT NOW amount, kept while the details are rebuilt.
                CraftAmount = 1,
                CraftMax = 0,
                --// Material name -> its row in the details, for the popup.
                MaterialRows = {},
                DetailSignature = nil,
                PopupFor = nil,
                PopupAnchor = nil,
            },
        }

        local S = Detail.S
        local Theme, DetailScroll, Popup, PopupContent
        --// Set by Build: Select(Name) opens a recipe, Refresh() redraws
        --// the whole browser.
        local Browser
        --// Parts of the details updated in place by every refresh.
        local Craft = {}

        ------------------------------------------------------------------------
        --// What the inventory says about a recipe or a material
        ------------------------------------------------------------------------

        local function ReadInventory()
            return {
                Inventory = Recipes:GetInventory(),
                Reserves = Recipes:GetReserves(),
                Skill = Recipes:GetSkill(),
            }
        end

        local function Describe(Name, Stock)
            return Recipes:Describe({ Name = Name, Target = 0 }, Stock.Inventory, Stock.Reserves, Stock.Skill)
        end

        --// One material of one craft: Have counts the whole inventory, Usable
        --// what is left after Material Reserve, Missing what one craft lacks.
        local function DescribeMaterial(Material, Stock)
            local Have = Stock.Inventory[Material.Name] or 0
            local Keep = Stock.Reserves[Material.Name] or 0
            local Usable = math.max(0, Have - Keep)

            return {
                Have = Have,
                Keep = Keep,
                Usable = Usable,
                Missing = math.max(0, Material.Amount - Usable),
            }
        end

        --// The most CRAFT NOW may ask for: what the materials allow, and no
        --// more than the inventory can hold of the item.
        local function GetCraftMax(State)
            if not State.Known or State.Locked then
                return 0
            end

            return math.max(0, math.min(State.Craftable, MAX_STACK - State.Have))
        end

        local function IsInPriority(Name)
            for _, Entry in ipairs(CONFIG.SMITH_RECIPES or {}) do
                if Entry.Name == Name then
                    return true
                end
            end

            return false
        end

        --// The status line of a recipe and its colour.
        local function DescribeStatus(State)
            local Theme = UI.Theme

            if State.Locked then
                return "LOCKED", Theme.TextMuted
            elseif State.Craftable > 0 or not State.Short then
                return string.format("READY  x%d", State.Craftable), Theme.Cyan
            end

            return string.format("NEED %s %d/%d", State.Short.Name, State.Short.Have, State.Short.Need), Theme.Warning
        end

        --// "WEAPON  ·  LV 20  ·  BOUND": type, level (or skill) and whether
        --// it can be traded, from the assets.
        local function DescribeItem(Name)
            local Info = Recipes:GetItemInfo(Name)

            if not Info then
                return Recipes.UNKNOWN_TYPE:upper()
            end

            local Parts = { Info.Type:upper() }

            if Info.Level ~= nil then
                table.insert(Parts, "LV " .. tostring(Info.Level))
            elseif Info.Skill ~= nil then
                table.insert(Parts, "SKILL " .. tostring(Info.Skill))
            end

            if Info.Bound then
                table.insert(Parts, "BOUND")
            end

            return table.concat(Parts, "  ·  ")
        end

        --// "DMG 12  ·  DEF 3  ·  DEX 4", or nil when it has none of them.
        local function DescribeStats(Name)
            local Info = Recipes:GetItemInfo(Name)
            local Parts = {}

            for _, Stat in ipairs({ "DMG", "DEF", "DEX" }) do
                if Info and Info[Stat] ~= nil then
                    table.insert(Parts, Stat .. " " .. tostring(Info[Stat]))
                end
            end

            return #Parts > 0 and table.concat(Parts, "  ·  ") or nil
        end

        Detail.ReadInventory = ReadInventory
        Detail.Describe = Describe
        Detail.GetCraftMax = GetCraftMax
        Detail.IsInPriority = IsInPriority
        Detail.DescribeStatus = DescribeStatus
        Detail.DescribeItem = DescribeItem

        ------------------------------------------------------------------------
        --// Material popup
        ------------------------------------------------------------------------

        local function HidePopup()
            S.PopupFor = nil
            S.PopupAnchor = nil

            if Popup then
                Popup.Visible = false
            end
        end

        --// Beside the tapped row, flipped to its left when it would run off
        --// the screen, then pulled inside once its height is known.
        --// Deferred: a row just rebuilt has no position until layout runs.
        local function PlacePopup(Anchor)
            task.defer(function()
                if not Popup.Visible or S.PopupAnchor ~= Anchor or not Anchor.Parent then
                    return
                end

                local Screen = UI.ScreenGui.AbsoluteSize
                local Left = Anchor.AbsolutePosition.X + Anchor.AbsoluteSize.X + 6

                if Left + POPUP_WIDTH > Screen.X - Floating.SCREEN_MARGIN then
                    Left = Anchor.AbsolutePosition.X - POPUP_WIDTH - 6
                end

                Popup.Position = UDim2.fromOffset(Left, Anchor.AbsolutePosition.Y)
                UI._ClampToParent(Popup)
            end)
        end

        local function ShowPopup(MaterialName, Anchor)
            local Stock = ReadInventory()
            local Recipe = Recipes:Get(MaterialName)
            local Have = Stock.Inventory[MaterialName] or 0
            local Keep = Stock.Reserves[MaterialName] or 0

            ClearChildren(PopupContent)

            local Header = New("Frame", { Parent = PopupContent, BackgroundTransparency = 1, Size = UDim2.new(1, 0, 0, 20), LayoutOrder = 1 })
            Label(Header, MaterialName, 12, { Size = UDim2.new(1, -24, 1, 0), TextColor3 = Theme.Cyan, Font = Floating.Fonts.Bold })

            local Close = Button(Header, "×", Theme.Danger, {
                AnchorPoint = Vector2.new(1, 0.5),
                Position = UDim2.new(1, 0, 0.5, 0),
                Size = UDim2.fromOffset(20, 18),
            })
            UI:_Connect(Close.Activated, HidePopup)

            local HaveText = string.format("HAVE  %d", Have)

            if Keep > 0 then
                HaveText ..= string.format("   (KEEP %d)", Keep)
            end

            Label(PopupContent, HaveText, 9, { TextColor3 = Theme.TextSecondary, LayoutOrder = 2 })

            if not Recipe then
                Label(PopupContent, "Not craftable: no smithing recipe makes it", 9, {
                    TextColor3 = Theme.TextMuted,
                    TextWrapped = true,
                    TextTruncate = Enum.TextTruncate.None,
                    AutomaticSize = Enum.AutomaticSize.Y,
                    LayoutOrder = 3,
                })
            else
                local Locked = Recipe.Skill > Stock.Skill

                Label(PopupContent, string.format("CRAFTED FROM  ·  SKILL %s", tostring(Recipe.Skill)), 9, {
                    TextColor3 = Locked and Theme.Danger or Theme.TextSecondary,
                    LayoutOrder = 3,
                })

                for Index, Material in ipairs(Recipe.Materials) do
                    local Info = DescribeMaterial(Material, Stock)

                    Label(PopupContent, string.format("  %s   %d / %d", Material.Name, Info.Usable, Material.Amount), 9, {
                        TextColor3 = Info.Missing > 0 and Theme.Warning or Theme.Text,
                        LayoutOrder = 3 + Index,
                    })
                end

                local Open = Button(PopupContent, "OPEN RECIPE", Theme.Cyan, { LayoutOrder = 100, Size = UDim2.new(1, 0, 0, 22) })

                UI:_Connect(Open.Activated, function()
                    Browser:Select(MaterialName)
                end)
            end

            S.PopupFor = MaterialName
            S.PopupAnchor = Anchor
            Popup.Visible = true
            PlacePopup(Anchor)
        end

        ------------------------------------------------------------------------
        --// RECIPE tab: details and CRAFT NOW
        ------------------------------------------------------------------------

        local function GetDetailSignature(Recipe, Stock)
            local Parts = { Recipe.Name, tostring(Stock.Skill), tostring(Stock.Inventory[Recipe.Name] or 0), tostring(IsInPriority(Recipe.Name)) }

            for _, Material in ipairs(Recipe.Materials) do
                local Info = DescribeMaterial(Material, Stock)
                table.insert(Parts, Material.Name .. ":" .. Info.Have .. ":" .. Info.Keep)
            end

            return table.concat(Parts, "|")
        end

        local function AddMaterialRow(Material, Stock, Order)
            local Info = DescribeMaterial(Material, Stock)
            local Craftable = Recipes:Get(Material.Name) ~= nil

            local Row = New("TextButton", {
                Parent = DetailScroll,
                Size = UDim2.new(1, -6, 0, ROW_HEIGHT),
                BackgroundColor3 = Theme.Element,
                BorderSizePixel = 0,
                Text = "",
                AutoButtonColor = false,
                LayoutOrder = Order,
            })

            local RowStroke = Stroke(Row, Info.Missing > 0 and Theme.Warning or Theme.BorderDim, Info.Missing > 0 and 0.4 or 0.3)
            Floating.Hover(Row, RowStroke)

            Label(Row, Material.Name .. (Craftable and "  ›" or ""), 10, {
                Position = UDim2.fromOffset(8, 3),
                Size = UDim2.new(1, -90, 0, 15),
            })

            Label(Row, string.format("%d / %d", Info.Usable, Material.Amount), 10, {
                AnchorPoint = Vector2.new(1, 0),
                Position = UDim2.new(1, -8, 0, 3),
                Size = UDim2.fromOffset(80, 15),
                TextXAlignment = Enum.TextXAlignment.Right,
                TextColor3 = Info.Missing > 0 and Theme.Warning or Theme.Cyan,
            })

            local Note = Info.Missing > 0 and string.format("MISSING %d", Info.Missing) or "OK"

            if Info.Keep > 0 then
                Note ..= string.format("   ·   HAVE %d, KEEP %d", Info.Have, Info.Keep)
            end

            Label(Row, Note, 10, {
                Position = UDim2.fromOffset(8, 18),
                Size = UDim2.new(1, -16, 0, 13),
                TextColor3 = Info.Missing > 0 and Theme.Warning or Theme.TextMuted,
            })

            UI:_Connect(Row.Activated, function()
                if S.PopupFor == Material.Name then
                    HidePopup()
                else
                    ShowPopup(Material.Name, Row)
                end
            end)

            S.MaterialRows[Material.Name] = Row
        end

        local function TogglePriority(Name)
            local RecipeList = UIRef.RecipePriorityComponent

            if not RecipeList then
                return
            end

            if IsInPriority(Name) then
                RecipeList:Remove(Name)
                NotifyAction("AUTO SMITHING", "Removed " .. Name)
            elseif RecipeList:Add(Name, MAX_STACK) then
                NotifyAction("AUTO SMITHING", "Added " .. Name)
            end

            Browser:Refresh()
        end

        --// Clamped to what can be crafted; at least 1 whenever any can.
        local function SetCraftAmount(Value)
            local Amount = math.clamp(math.floor(tonumber(Value) or 0), math.min(1, S.CraftMax), S.CraftMax)
            S.CraftAmount = Amount

            if Craft.Slider then
                Craft.Slider:Set(Amount, false)
            end

            if Craft.AmountBox then
                Craft.AmountBox.Text = tostring(Amount)
            end
        end

        local function StartCraft(Name)
            if S.CraftMax < 1 then
                NotifyAction("CRAFT NOW", Name .. ": nothing to craft with (locked, missing materials or a full stack)")
                return
            end

            local Amount = math.clamp(S.CraftAmount, 1, S.CraftMax)

            if AutoSmithing:StartOrder(Name, Amount) then
                NotifyAction("CRAFT NOW", string.format("Crafting %d x %s", Amount, Name))
                Browser:Refresh()
            end
        end

        --// The order line and CANCEL under CRAFT NOW, kept current.
        local function RefreshOrderLine()
            if not Craft.OrderLabel or not Craft.OrderLabel.Parent then
                return
            end

            local Order = AutoSmithing:GetOrder()

            Craft.OrderLabel.Text = Order
                and string.format("ORDER  %s  %d / %d", Order.Name, Order.Done, Order.Count)
                or "NO CRAFT ORDER RUNNING"
            Craft.OrderLabel.TextColor3 = Order and Theme.Cyan or Theme.TextMuted
            Craft.CancelButton.Visible = Order ~= nil
        end

        local function BuildCraftPanel(Recipe, State, Order)
            S.CraftMax = GetCraftMax(State)

            local Panel = New("Frame", {
                Parent = DetailScroll,
                Size = UDim2.new(1, -6, 0, 0),
                AutomaticSize = Enum.AutomaticSize.Y,
                BackgroundColor3 = Theme.Element,
                BorderSizePixel = 0,
                LayoutOrder = Order,
            })

            Panel.BackgroundTransparency = 0.1
            Stroke(Panel, Theme.BorderDim, 0.25)
            Padding(Panel, 8, 8)
            List(Panel, 5)

            Label(Panel, string.format("CRAFT NOW  ·  UP TO %d", S.CraftMax), 10, {
                TextColor3 = S.CraftMax > 0 and Theme.Cyan or Theme.TextMuted,
                Font = Floating.Fonts.Bold,
                LayoutOrder = 1,
            })

            local SliderSection = Floating.Section(Panel, { LayoutOrder = 2 })

            Craft.Slider = SliderSection:AddSlider{
                Name = "Amount",
                Default = 0,
                Min = 0,
                Max = math.max(1, S.CraftMax),
                Callback = function(Value)
                    SetCraftAmount(Value)
                end,
            }

            local Controls = New("Frame", { Parent = Panel, BackgroundTransparency = 1, Size = UDim2.new(1, 0, 0, 26), LayoutOrder = 3 })

            Craft.AmountBox = New("TextBox", {
                Parent = Controls,
                Size = UDim2.fromOffset(64, 26),
                BackgroundColor3 = Theme.PanelLight,
                BorderSizePixel = 0,
                Text = "",
                PlaceholderText = "amount",
                PlaceholderColor3 = Theme.TextMuted,
                TextColor3 = Theme.Text,
                TextSize = 10,
                Font = Floating.Fonts.Bold,
                ClearTextOnFocus = false,
            })

            Floating.Hover(Craft.AmountBox, Stroke(Craft.AmountBox, Theme.BorderDim, 0.15))

            local MaxButton = Button(Controls, "MAX", Theme.Text, {
                Position = UDim2.fromOffset(70, 0),
                Size = UDim2.fromOffset(52, 26),
            })

            local CraftButton = Button(Controls, "CRAFT", S.CraftMax > 0 and Theme.Cyan or Theme.TextMuted, {
                Position = UDim2.fromOffset(128, 0),
                Size = UDim2.new(1, -128, 0, 26),
            })

            local OrderRow = New("Frame", { Parent = Panel, BackgroundTransparency = 1, Size = UDim2.new(1, 0, 0, 22), LayoutOrder = 4 })
            Craft.OrderLabel = Label(OrderRow, "", 9, { Size = UDim2.new(1, -76, 1, 0) })
            Craft.CancelButton = Button(OrderRow, "CANCEL", Theme.Danger, {
                AnchorPoint = Vector2.new(1, 0),
                Position = UDim2.new(1, 0, 0, 0),
                Size = UDim2.fromOffset(70, 22),
            })

            UI:_Connect(Craft.AmountBox.FocusLost, function()
                SetCraftAmount(Craft.AmountBox.Text)
            end)

            UI:_Connect(MaxButton.Activated, function()
                SetCraftAmount(S.CraftMax)
            end)

            UI:_Connect(CraftButton.Activated, function()
                StartCraft(Recipe.Name)
            end)

            UI:_Connect(Craft.CancelButton.Activated, function()
                AutoSmithing:CancelOrder()
                RefreshOrderLine()
            end)

            SetCraftAmount(S.CraftAmount)
            RefreshOrderLine()
        end

        local function BuildDetail(Recipe, Stock)
            ClearChildren(DetailScroll)
            table.clear(S.MaterialRows)
            table.clear(Craft)

            if not Recipe then
                Label(DetailScroll, "Pick a recipe from the list", 10, { TextColor3 = Theme.TextMuted, LayoutOrder = 1 })
                return
            end

            local State = Describe(Recipe.Name, Stock)
            local Status, StatusColor = DescribeStatus(State)
            local Info = Recipes:GetItemInfo(Recipe.Name)
            local Stats = DescribeStats(Recipe.Name)

            Label(DetailScroll, "◇  " .. string.upper(Recipe.Name), 13, { TextColor3 = Theme.Cyan, Font = Floating.Fonts.Bold, LayoutOrder = 1 })
            Label(DetailScroll, DescribeItem(Recipe.Name) .. ((Info and not Info.Bound) and "  ·  TRADEABLE" or ""), 9, {
                TextColor3 = (Info and Info.Bound) and Theme.Warning or Theme.TextSecondary,
                LayoutOrder = 2,
            })

            if Stats then
                Label(DetailScroll, Stats, 10, { TextColor3 = Theme.Text, LayoutOrder = 3 })
            end

            Label(DetailScroll, string.format("SMITHING SKILL  %s  ·  YOURS  %s  ·  HAVE  %d", tostring(Recipe.Skill), tostring(Stock.Skill), State.Have), 9, {
                TextColor3 = State.Locked and Theme.Danger or Theme.TextSecondary,
                LayoutOrder = 4,
            })
            Label(DetailScroll, Status, 10, { TextColor3 = StatusColor, Font = Floating.Fonts.Bold, LayoutOrder = 5 })
            Label(DetailScroll, "MATERIALS PER CRAFT  (tap one to see how it is made)", 10, {
                TextColor3 = Theme.TextMuted,
                LayoutOrder = 6,
            })

            if #Recipe.Materials == 0 then
                Label(DetailScroll, "  none", 9, { TextColor3 = Theme.TextMuted, LayoutOrder = 7 })
            end

            for Index, Material in ipairs(Recipe.Materials) do
                AddMaterialRow(Material, Stock, 6 + Index)
            end

            BuildCraftPanel(Recipe, State, 500)

            local InPriority = IsInPriority(Recipe.Name)
            local Toggle = Button(DetailScroll, InPriority and "REMOVE FROM RECIPE PRIORITY" or "ADD TO RECIPE PRIORITY",
                InPriority and Theme.Danger or Theme.Cyan, { Size = UDim2.new(1, -6, 0, 26), LayoutOrder = 1000 })

            UI:_Connect(Toggle.Activated, function()
                TogglePriority(Recipe.Name)
            end)
        end

        --// Rebuilt only when something it shows changed, so a refresh does
        --// not reset the scroll or drop an open popup.
        local function RefreshDetail(Stock)
            local Recipe = S.Selected and Recipes:Get(S.Selected)

            if S.Selected and not Recipe then
                S.Selected = nil
            end

            local Signature = Recipe and GetDetailSignature(Recipe, Stock) or ""

            if Signature == S.DetailSignature then
                RefreshOrderLine()
                return
            end

            S.DetailSignature = Signature
            BuildDetail(Recipe, Stock)

            --// The popup's row was replaced: follow the new one, or close.
            if S.PopupFor then
                local Anchor = S.MaterialRows[S.PopupFor]

                if Anchor then
                    ShowPopup(S.PopupFor, Anchor)
                else
                    HidePopup()
                end
            end
        end

        local function BuildPopup()
            Popup = New("TextButton", {
                --// A button, so a click on it stops here instead of reaching the UI
                --// underneath; it draws like a frame.
                Text = "",
                AutoButtonColor = false,
                Name = "SmithingBrowserPopup",
                Parent = UI.ScreenGui,
                Size = UDim2.fromOffset(POPUP_WIDTH, 0),
                AutomaticSize = Enum.AutomaticSize.Y,
                BackgroundColor3 = Theme.Panel,
                BorderSizePixel = 0,
                Active = true,
                Visible = false,
                ZIndex = Floating.POPUP_Z,
            })

            Stroke(Popup, Theme.CyanDark, 0.1)
            Padding(Popup, 8, 8)

            PopupContent = New("Frame", {
                Parent = Popup,
                BackgroundTransparency = 1,
                Size = UDim2.new(1, 0, 0, 0),
                AutomaticSize = Enum.AutomaticSize.Y,
            })

            List(PopupContent, 3)

            --// A tap anywhere but the popup or its row closes the popup.
            UI:_Connect(UserInputService.InputBegan, function(Input)
                if not Popup.Visible
                    or (Input.UserInputType ~= Enum.UserInputType.MouseButton1
                        and Input.UserInputType ~= Enum.UserInputType.Touch)
                then
                    return
                end

                local Position = Vector2.new(Input.Position.X, Input.Position.Y)

                if not IsInside(Popup, Position) and not IsInside(S.PopupAnchor, Position) then
                    HidePopup()
                end
            end)
        end

        ------------------------------------------------------------------------
        --// API (for SmithingBrowser)
        ------------------------------------------------------------------------

        --// Builds the tab into Scroll. Owner is the browser: Owner:Select(Name)
        --// opens a recipe, Owner:Refresh() redraws the window.
        function Detail:Build(Scroll, Owner)
            Theme = UI.Theme
            DetailScroll = Scroll
            Browser = Owner
            BuildPopup()
        end

        function Detail:Refresh(Stock)
            RefreshDetail(Stock)
        end

        function Detail:Select(Name)
            S.Selected = Name
            S.DetailSignature = nil
            S.CraftAmount = 1
            HidePopup()
        end

        function Detail:GetSelected()
            return S.Selected
        end

        --// Rebuilt on the next refresh even when nothing it shows changed.
        function Detail:Invalidate()
            S.DetailSignature = nil
        end

        function Detail:HidePopup()
            HidePopup()
        end

        return Detail
    end,
}
]======],
	["Features/SmithingMinigame.lua"] = [======[
-- SmithingMinigame plays the strike minigame the game opens after
-- CraftingStart: PlayerGui.CraftingGame.Main holds a moving line (Mover), a
-- target band (ClickArea) and the strike button (Action); Success or Failed
-- becomes visible when the round is over.
--
-- While running it checks every rendered frame and strikes when Mover reaches
-- ClickArea. The strike is only pressed while the mover's centre is inside the
-- band on the frame the strike is decided on and on the frame the click lands
-- on: a direct click (firesignal / getconnections) is run at once, a synthetic
-- one on the mouse release a few frames later, and either way the press has to
-- land inside the band. Pressing as soon as the mover's leading edge touches
-- the band presses before the mover has arrived, and a speed measured across
-- the game's reset can throw the check past the band as well, so neither is
-- struck on.
--
-- The speed is only ever measured between two frames of the same sweep. The
-- game resets Mover for the next strike, so the frame just before and the
-- frame just after a strike (or after the minigame window comes and goes) are
-- not two samples of one movement: the reset itself would read as speed. Those
-- frames only take the sample, and the speed goes with them, so the prediction
-- of a later frame is never made from a reset.
return {
    Name = "SmithingMinigame",
    Dependencies = {"Runtime", "GuiClick"},

    Start = function(Context)
        local Player = Context.Player
        local RunService = Context.Services.RunService
        local GuiClick = Context.GuiClick

        --// Pixels of slack around ClickArea, as in the proof of concept. It
        --// is given to the frame the click lands on, never to the frame the
        --// strike is decided on, so it cannot make a strike early.
        local STRIKE_PADDING = 1
        --// Never strike twice within this, so one overlap is one strike.
        local STRIKE_COOLDOWN = 0.12
        --// The strike button listens to this signal.
        local STRIKE_SIGNALS = { "MouseButton1Click" }

        local Minigame = {
            Name = "SmithingMinigame",
            S = {
                Connection = nil,
                LastStrike = 0,
                Strikes = 0,
                LastMoverPosition = nil,
                MoverVelocity = Vector2.zero,
                --// The click method that worked last; firesignal is what
                --// the proof of concept used.
                Method = "firesignal",
            },
        }

        local S = Minigame.S

        --// CraftingGame.Main, or nil while the minigame is not open.
        function Minigame:Find()
            local PlayerGui = Player:FindFirstChild("PlayerGui")
            local CraftingGame = PlayerGui and PlayerGui:FindFirstChild("CraftingGame")
            return CraftingGame and CraftingGame:FindFirstChild("Main")
        end

        --// "Success", "Failed", or nil while the round is still running.
        function Minigame:GetResult(Main)
            local Success = Main:FindFirstChild("Success")
            local Failed = Main:FindFirstChild("Failed")

            if Success and Success.Visible then
                return "Success"
            elseif Failed and Failed.Visible then
                return "Failed"
            end

            return nil
        end

        function Minigame:GetStrikes()
            return S.Strikes
        end

        --// Whether the mover has reached the band, with Slack pixels of room
        --// to spare. Along the bar it is the mover's centre that counts, not
        --// the edge that arrives first, so a strike is never pressed before
        --// the mover is at the band; the two still have to meet across it.
        local function Inside(Mover, Position, Band, Slack)
            local Size = Mover.AbsoluteSize
            local BandPosition = Band.AbsolutePosition
            local BandSize = Band.AbsoluteSize

            local CentreX = Position.X + Size.X / 2

            return CentreX >= BandPosition.X - Slack
                and CentreX <= BandPosition.X + BandSize.X + Slack
                and Position.Y < BandPosition.Y + BandSize.Y + Slack
                and Position.Y + Size.Y + Slack > BandPosition.Y
        end

        --// Forgets the mover's motion. Used wherever the next frame is not
        --// the continuation of the last one: the round ended, the minigame
        --// window came or went, or a strike was just pressed and the game is
        --// resetting the mover for the next strike.
        local function ForgetMover()
            S.LastMoverPosition = nil
            S.MoverVelocity = Vector2.zero
        end

        local function Step(DeltaTime)
            local Main = Minigame:Find()

            if not Main or Minigame:GetResult(Main) then
                ForgetMover()
                return
            end

            local ClickArea = Main:FindFirstChild("ClickArea")
            local Mover = Main:FindFirstChild("Mover")
            local Action = Main:FindFirstChild("Action")

            if not ClickArea or not Mover or not Action then
                ForgetMover()
                return
            end

            local Position = Mover.AbsolutePosition
            local Previous = S.LastMoverPosition
            S.LastMoverPosition = Position

            --// Without a frame before it there is no movement to measure, so
            --// this frame only takes the sample, and never strikes: it may be
            --// the frame the mover was reset on.
            if not Previous or DeltaTime <= 0 then
                S.MoverVelocity = Vector2.zero
                return
            end

            S.MoverVelocity = (Position - Previous) / DeltaTime

            local now = os.clock()

            if now - S.LastStrike < STRIKE_COOLDOWN then
                return
            end

            --// Where the mover will be when the click lands. The centre has
            --// to be inside the band there as well as on this frame, so the
            --// press cannot be early however the click is delivered, and a
            --// speed measured across a reset cannot strike on its own.
            local CheckPosition = Position + S.MoverVelocity * DeltaTime

            if not Inside(Mover, Position, ClickArea, 0)
                or not Inside(Mover, CheckPosition, ClickArea, STRIKE_PADDING) then
                return
            end

            --// Before the click: a synthetic click yields, and later frames
            --// run meanwhile and would strike again.
            S.LastStrike = now

            local Method = GuiClick.Click(Action, S.Method, STRIKE_SIGNALS)

            if Method then
                S.Method = Method
                S.Strikes += 1
            end

            --// The next strike is measured from the next strike's mover, not
            --// from the movement of the one just struck.
            ForgetMover()
        end

        --// Starts playing; idempotent. Runs on RenderStepped, where the GUI
        --// has its final position for the frame.
        function Minigame:Start()
            if S.Connection then
                return
            end

            S.Strikes = 0
            S.LastStrike = 0
            S.LastMoverPosition = nil
            S.MoverVelocity = Vector2.zero
            S.Connection = RunService.RenderStepped:Connect(Step)
        end

        function Minigame:Stop()
            if S.Connection then
                S.Connection:Disconnect()
                S.Connection = nil
            end
        end

        Context.Lifetime.OnEnd(function()
            Minigame:Stop()
        end)

        return Minigame
    end,
}
]======],
	["Features/SmithingRecipes.lua"] = [======[
-- SmithingRecipes reads the game's crafting recipes and answers what can be
-- crafted right now. Shared by AutoSmithing (which recipe to craft next, and
-- what each recipe in its Recipe Status list is waiting on).
--
-- A recipe is a child of ReplicatedStorage.CraftingRecipes holding
--   CraftingSkill  the SmithingSkill a player needs to craft it
--   CraftType      the kind of craft
--   <Material>     a number value per material: how many one craft uses
-- The crafted item is assumed to be named like the recipe ("Iron Ingot").
--
-- What an item is comes from the game's assets, Commons.getAssets(true)
-- from CoreCommons: Assets[Name].Value is its type, and its children
-- LVL, Skill, DMG, DEF and DEX its stats. A Bound child means it cannot
-- be traded.
return {
    Name = "SmithingRecipes",
    Dependencies = {"Runtime", "SaveConfig"},

    Start = function(Context)
        local Player = Context.Player
        local Replicated = Context.Services.Replicated
        local CONFIG = Context.CONFIG

        local SKILL_STAT = "SmithingSkill"
        --// Recipe children that are settings rather than materials.
        local NON_MATERIALS = { CraftType = true, CraftingSkill = true }
        --// Assets that could not be read are tried again after this long.
        local ASSETS_RETRY_SECONDS = 10
        --// An item with no type in the assets is filed under this.
        local UNKNOWN_TYPE = "Other"

        local Recipes = {
            Name = "SmithingRecipes",
            UNKNOWN_TYPE = UNKNOWN_TYPE,
            S = {
                --// Recipe name -> parsed recipe; nil until read, and dropped
                --// whenever the recipe folder changes.
                Cache = nil,
                Folder = nil,
                Connections = {},
                Assets = nil,
                AssetsRetryAt = 0,
                --// Item name -> GetItemInfo result (false when not an asset).
                ItemInfo = {},
            },
        }

        local S = Recipes.S

        local function GetAssets()
            if S.Assets or os.clock() < S.AssetsRetryAt then
                return S.Assets
            end

            local Module = Replicated:FindFirstChild("CoreCommons", true)
            local Ok, Assets = pcall(function()
                local Commons = Module and require(Module)
                return Commons and Commons.getAssets and Commons.getAssets(true)
            end)

            if Ok and type(Assets) == "table" then
                S.Assets = Assets
                table.clear(S.ItemInfo)
            else
                S.AssetsRetryAt = os.clock() + ASSETS_RETRY_SECONDS

                if not S.WarnedAssets then
                    S.WarnedAssets = true
                    warn("[SmithingRecipes] Could not read the game's assets:", Assets)
                end
            end

            return S.Assets
        end

        --// The game's assets (item name -> asset), or nil while they cannot
        --// be read. Shared with the Asset Explorer.
        function Recipes:GetAssets()
            return GetAssets()
        end

        --// An asset is an Instance with value children; a plain table of the
        --// same shape is read the same way.
        local function GetChild(Asset, ChildName)
            if typeof(Asset) == "Instance" then
                return Asset:FindFirstChild(ChildName)
            end

            return type(Asset) == "table" and Asset[ChildName] or nil
        end

        --// The Value of a child of Asset, or nil when it has none.
        local function ReadChild(Asset, ChildName)
            local Child = GetChild(Asset, ChildName)

            if not Child then
                return nil
            end

            local Ok, Value = pcall(function()
                return Child.Value
            end)

            return Ok and Value or nil
        end

        local function ReadItemInfo(Asset)
            local Ok, Type = pcall(function()
                return Asset.Value
            end)

            Type = Ok and Type ~= nil and tostring(Type) or ""

            return {
                Type = Type ~= "" and Type or UNKNOWN_TYPE,
                Level = ReadChild(Asset, "LVL"),
                Skill = ReadChild(Asset, "Skill"),
                DMG = ReadChild(Asset, "DMG"),
                DEF = ReadChild(Asset, "DEF"),
                DEX = ReadChild(Asset, "DEX"),
                Bound = GetChild(Asset, "Bound") ~= nil,
            }
        end

        --// What the game's assets say about an item: { Type, Level, Skill,
        --// DMG, DEF, DEX, Bound }, the stats nil when it has none. Nil when
        --// the item is not in the assets or they cannot be read.
        function Recipes:GetItemInfo(Name)
            local Cached = S.ItemInfo[Name]

            if Cached ~= nil then
                return Cached or nil
            end

            local Assets = GetAssets()

            if not Assets then
                return nil
            end

            local Asset = Assets[Name]
            local IsAsset = typeof(Asset) == "Instance" or type(Asset) == "table"
            local Info = IsAsset and ReadItemInfo(Asset) or false

            S.ItemInfo[Name] = Info
            return Info or nil
        end

        --// The item's type for filtering; UNKNOWN_TYPE when it has none.
        function Recipes:GetItemType(Name)
            local Info = self:GetItemInfo(Name)
            return Info and Info.Type or UNKNOWN_TYPE
        end

        local function ReadRecipe(Recipe)
            local Skill = Recipe:FindFirstChild("CraftingSkill")
            local CraftType = Recipe:FindFirstChild("CraftType")

            if not Skill or not CraftType then
                return nil
            end

            local Materials = {}

            for _, Child in ipairs(Recipe:GetChildren()) do
                if not NON_MATERIALS[Child.Name]
                    and (Child:IsA("NumberValue") or Child:IsA("IntValue"))
                    and Child.Value > 0
                then
                    table.insert(Materials, { Name = Child.Name, Amount = Child.Value })
                end
            end

            table.sort(Materials, function(A, B)
                return A.Name < B.Name
            end)

            return {
                Name = Recipe.Name,
                CraftType = tostring(CraftType.Value),
                Skill = tonumber(Skill.Value) or 0,
                Materials = Materials,
            }
        end

        --// Watches the folder so a recipe added or removed (or the folder
        --// being replaced) is read again on the next question.
        local function GetCache()
            local Folder = Replicated:FindFirstChild("CraftingRecipes")

            if Folder ~= S.Folder then
                for _, Connection in ipairs(S.Connections) do
                    Connection:Disconnect()
                end

                table.clear(S.Connections)
                S.Folder = Folder
                S.Cache = nil

                if Folder then
                    local function Invalidate()
                        S.Cache = nil
                    end

                    table.insert(S.Connections, Folder.ChildAdded:Connect(Invalidate))
                    table.insert(S.Connections, Folder.ChildRemoved:Connect(Invalidate))
                end
            end

            if not S.Cache then
                S.Cache = {}

                for _, Recipe in ipairs(Folder and Folder:GetChildren() or {}) do
                    local Parsed = ReadRecipe(Recipe)

                    if Parsed then
                        S.Cache[Parsed.Name] = Parsed
                    end
                end
            end

            return S.Cache
        end

        function Recipes:Get(Name)
            return GetCache()[Name]
        end

        --// Every recipe, easiest first.
        function Recipes:GetAll()
            local List = {}

            for _, Recipe in pairs(GetCache()) do
                table.insert(List, Recipe)
            end

            table.sort(List, function(A, B)
                if A.Skill ~= B.Skill then
                    return A.Skill < B.Skill
                end

                return A.Name < B.Name
            end)

            return List
        end

        --// Every material any recipe uses, sorted.
        function Recipes:GetMaterialNames()
            local Seen = {}
            local Names = {}

            for _, Recipe in pairs(GetCache()) do
                for _, Material in ipairs(Recipe.Materials) do
                    if not Seen[Material.Name] then
                        Seen[Material.Name] = true
                        table.insert(Names, Material.Name)
                    end
                end
            end

            table.sort(Names)
            return Names
        end

        function Recipes:GetSkillValue()
            local PlayerStats = Player:FindFirstChild("PlayerStats")
            return PlayerStats and PlayerStats:FindFirstChild(SKILL_STAT)
        end

        function Recipes:GetSkill()
            local Skill = self:GetSkillValue()
            return Skill and tonumber(Skill.Value) or 0
        end

        function Recipes:GetInventoryText()
            local PlayerStats = Player:FindFirstChild("PlayerStats")
            local Inventory = PlayerStats and PlayerStats:FindFirstChild("Inventory")
            return Inventory and Inventory.Value or ""
        end

        --// Item name -> count, from the "Name|Amount,Name|Amount" string.
        function Recipes:GetInventory()
            local Counts = {}

            for Item in string.gmatch(self:GetInventoryText(), "([^,]+)") do
                local Name, Amount = string.match(Item, "([^|]+)|(.+)")

                if Name then
                    Counts[Name] = tonumber(Amount) or 0
                end
            end

            return Counts
        end

        --// Material name -> how many Material Reserve keeps back.
        function Recipes:GetReserves()
            local Reserves = {}

            for _, Entry in ipairs(CONFIG.SMITH_RESERVES or {}) do
                Reserves[Entry.Name] = tonumber(Entry.Keep) or 0
            end

            return Reserves
        end

        --// Where one recipe of the list stands:
        --//   Known      the game has this recipe
        --//   Locked     SmithingSkill is below its requirement
        --//   Have / Target / Remaining  of the crafted item
        --//   Craftable  crafts the materials allow, after the reserves
        --//   Short      the first material holding it back { Name, Have, Need }
        function Recipes:Describe(Entry, Inventory, Reserves, Skill)
            local Recipe = self:Get(Entry.Name)
            local Have = Inventory[Entry.Name] or 0
            local Target = tonumber(Entry.Target) or 0
            local State = {
                Name = Entry.Name,
                Recipe = Recipe,
                Known = Recipe ~= nil,
                Have = Have,
                Target = Target,
                Remaining = math.max(0, Target - Have),
                Skill = Skill,
                Locked = false,
                Craftable = 0,
                Short = nil,
            }

            if not Recipe then
                return State
            end

            State.Locked = Recipe.Skill > Skill

            local Craftable = math.huge

            for _, Material in ipairs(Recipe.Materials) do
                local Usable = math.max(0, (Inventory[Material.Name] or 0) - (Reserves[Material.Name] or 0))
                local Count = math.floor(Usable / Material.Amount)

                if Count < Craftable then
                    Craftable = Count
                end

                if Count < 1 and not State.Short then
                    State.Short = { Name = Material.Name, Have = Usable, Need = Material.Amount }
                end
            end

            State.Craftable = Craftable == math.huge and State.Remaining or Craftable
            return State
        end

        --// Every recipe in the Recipe Priority list, in order.
        function Recipes:GetPlan()
            local Inventory = self:GetInventory()
            local Reserves = self:GetReserves()
            local Skill = self:GetSkill()
            local Plan = {}

            for _, Entry in ipairs(CONFIG.SMITH_RECIPES or {}) do
                table.insert(Plan, self:Describe(Entry, Inventory, Reserves, Skill))
            end

            return Plan
        end

        --// The first recipe in priority that can be crafted now and is not
        --// done, skipping any IsPaused(Name) reports. Also returns the plan.
        function Recipes:PickNext(IsPaused)
            local Plan = self:GetPlan()

            for _, State in ipairs(Plan) do
                if State.Known
                    and not State.Locked
                    and State.Remaining > 0
                    and State.Craftable > 0
                    and not IsPaused(State.Name)
                then
                    return State, Plan
                end
            end

            return nil, Plan
        end

        Context.Lifetime.OnEnd(function()
            Context.Lifetime.Disconnect(S.Connections)
        end)

        return Recipes
    end,
}
